local UhhhhhhVersion = "V10"
if _G.UhhhhhhLoaded == UhhhhhhVersion then return end

-- External-admin bootstrap compatibility. Optional executor helpers must be
-- defined before the first service lookup.
cloneref = cloneref or function(o) return o end
getcustomasset = getcustomasset or getsynasset
gethiddengui = get_hidden_gui or gethui
request = request or http_request or (syn and syn.request) or (http and http.request)

local Debris = cloneref(game:GetService("Debris"))
local CoreGui = cloneref(game:GetService("CoreGui"))
local Players = cloneref(game:GetService("Players"))
local VRService = cloneref(game:GetService("VRService"))
local RunService = cloneref(game:GetService("RunService"))
local StarterGui = cloneref(game:GetService("StarterGui"))
local GuiService = cloneref(game:GetService("GuiService"))
local HttpService = cloneref(game:GetService("HttpService"))
local TextService = cloneref(game:GetService("TextService"))
local TweenService = cloneref(game:GetService("TweenService"))
local TextChatService = cloneref(game:GetService("TextChatService"))
local UserInputService = cloneref(game:GetService("UserInputService"))
local AvatarEditorService = cloneref(game:GetService("AvatarEditorService"))
local ContextActionService = cloneref(game:GetService("ContextActionService"))

local Util = {}

Util.RandomString = function(length)
	length = length or math.random(32, 256)
	local str = ""
	for _=1, length do
		str ..= string.char(math.random(32, 126))
	end
	return str
end
Util.DeepcopyTable = function(t)
	local c = {}
	for k, v in pairs(t) do
		if type(v) == "table" then
			v = Util.DeepcopyTable(v)
		end
		c[k] = v
	end
	return c
end
Util.ParseHex = function(s)
	if type(s) ~= "string" then return nil end
	s = s:gsub("%s+", ""):gsub("^#", "")
	if #s == 3 then
		s = s:sub(1, 1):rep(2) .. s:sub(2, 2):rep(2) .. s:sub(3, 3):rep(2)
	end
	if not s:match("^%x%x%x%x%x%x$") then return nil end
	return Color3.fromRGB(tonumber(s:sub(1, 2), 16), tonumber(s:sub(3, 4), 16), tonumber(s:sub(5, 6), 16))
end
Util.Notify = function(text)
	-- [custom] Util.FX.Cfg (Customization page) decides where notifications go
	local cfg = Util.FX and Util.FX.Cfg
	if cfg then
		if cfg.NotifMode == 4 then return end
		if cfg.NotifMode == 2 and Util.UINotify then
			if pcall(Util.UINotify, text) then return end
		end
	end
	StarterGui:SetCore("SendNotification", {
		Title = (cfg and cfg.NotifTitle ~= "" and cfg.NotifTitle) or "Nooby's Uh Modded Reanimation",
		Text = text,
		Duration = (cfg and cfg.NotifDuration + 1) or 5
	})
end

local function ismissing(func)
	return not func or type(func) ~= "function"
end

-- Optional executor capabilities are recorded rather than hard-failing the
-- entire script. Commands which need a missing API can then report their own error.
Util.Capabilities = {
	request = not ismissing(request),
	customasset = not ismissing(getcustomasset),
	filesystem = not (ismissing(readfile) or ismissing(writefile) or ismissing(delfile) or ismissing(isfile) or ismissing(isfolder) or ismissing(makefolder) or ismissing(listfiles)),
	firetouch = not ismissing(firetouchinterest),
	hiddenproperty = not ismissing(gethiddenproperty),
	setscriptable = not ismissing(setscriptable),
	replicatesignal = not ismissing(replicatesignal),
}
if ismissing(isfile) then isfile = function() return false end end
if ismissing(isfolder) then isfolder = function() return false end end
if ismissing(listfiles) then listfiles = function() return {} end end

-- Correct fallback for sethiddenproperty when setscriptable is available.
if ismissing(sethiddenproperty) and not ismissing(setscriptable) and not ismissing(isscriptable) then
	sethiddenproperty = function(inst, prop, value)
		local ok, old = pcall(isscriptable, inst, prop)
		if ok and old == false then pcall(setscriptable, inst, prop, true) end
		local success, err = pcall(function() inst[prop] = value end)
		if ok and old == false then pcall(setscriptable, inst, prop, false) end
		return success, err
	end
end

-- Protected-call compatibility. Capture native functions before shadowing.
local _native_pcall = pcall
local _native_xpcall = xpcall
local pcall = function(func, ...)
	return _native_pcall(func, ...)
end
local xpcall = function(func, handler, ...)
	return _native_xpcall(func, handler, ...)
end
local b_getfenv = getfenv

local Player = Players.LocalPlayer

if not game:IsLoaded() then
	local notLoaded = Instance.new("Message")
	xpcall(function()
		notLoaded.Parent = CoreGui
	end, function()
		notLoaded.Parent = workspace
	end)
	notLoaded.Text = "Nooby's Uh Modded Reanimation is waiting for the game to load"
	game.Loaded:Wait()
	for i=1, 60 do
		while task.wait() > 1 / 10 do end
	end
	notLoaded:Destroy()
end

local Camera = workspace.CurrentCamera
workspace:GetPropertyChangedSignal("CurrentCamera"):Connect(function()
	local newCamera = workspace.CurrentCamera
	if newCamera ~= nil then
		Camera = newCamera
	end
end)
Util._scrsiz = Vector2.new(512, 512)
Util.GetScreenSize = function()
	if Camera ~= nil then
		Util._scrsiz = Camera.ViewportSize
	end
	return Util._scrsiz
end

--[[ ════════════════════════════════════════════════════════════════════
