pcall(function()
	local future = table.clone(MusicPlayer.Database)
	if isfile("UhhhhhhReanim/Muzik/nobuiltin") then
		table.clear(future)
	end
	for _,file in listfiles("UhhhhhhReanim/Muzik") do
		if isfile(file) and file:sub(-4, -1) == ".mp3" then
			table.insert(future, {file, file:sub(21, -5)})
		end
	end
	if #future > 0 then
		MusicPlayer.Database = future
	end
end)
MusicPlayer.Switching = false
MusicPlayer.Last = 1
MusicPlayer.PlayMusic = function(i)
	if MusicPlayer.Switching then return end
	MusicPlayer.Switching = true
	local last = MusicPlayer.LastMusic
	if not i then
		i = last
		while i == last do
			i = math.random(1, #MusicPlayer.Database)
			task.wait()
		end
	end
	MusicPlayer.LastMusic = i
	local hi = MusicPlayer.Database[i]
	local soundid, soundname = hi[1], hi[2]
	local s, id = pcall(isfile, soundid)
	if s and id then
		s, id = pcall(getcustomasset, soundid)
		if s then
			soundid = id
		else
			soundid = ""
		end
	else
		soundid = ""
	end
	if #soundid == 0 then
		MusicPlayer.Switching = false
		return MusicPlayer.PlayMusic()
	end
	UISound.Music.SoundId = soundid
	UISound.Music.Name = soundname
	UISound.Music:Stop()
	task.wait()
	UISound.Music.TimePosition = 0
	task.wait()
	UISound.Music:Play()
	task.wait()
	MusicPlayer.Switching = false
end
UISound.Music.Ended:Connect(function()
	MusicPlayer.PlayMusic()
end)

Util.FX.InitCustom(SaveData) -- [custom] load saved customization before the intro runs

-- [uh admin ext] FLOATING COMMAND TRIANGLE (standalone launcher)
-- Built right here, BEFORE the intro / module loading / admin core, so it can never be blocked by them.
-- It is its own ScreenGui, completely outside the reanimation UI: it works before, during and after reanimating.
-- tap = open the command bar | drag = move (mouse + touch) | hold ~0.7s = hide (tab at the top edge brings it back)
do
	local okL, errL = pcall(function()
		local FX = Util.FX
		Util.UhAdmin = Util.UhAdmin or {
			Tris = {},
			State = {open = false, hover = false, boost = 0, flash = 0, shake = 0, shown = false},
		}
		local U = Util.UhAdmin
		U.Tris = U.Tris or {}
		U.State = U.State or {open = false, hover = false, boost = 0, flash = 0, shake = 0, shown = false}
		local S = U.State
		local SIZE, TRI = 56, 42
		local UIS = UserInputService

		local sg = Instance.new("ScreenGui")
		sg.Name = "UhAdminButton"
		sg.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
		sg.ResetOnSpawn = false
		sg.IgnoreGuiInset = true
		sg.DisplayOrder = 2147483647
		pcall(function() sg.ClipToDeviceSafeArea = false end)
		pcall(function() sg.ScreenInsets = Enum.ScreenInsets.None end)
		local parented = false
		if gethiddengui then
			parented = pcall(function() sg.Parent = gethiddengui() end)
		end
		if not parented then
			parented = pcall(function() sg.Parent = CoreGui end)
		end
		if not parented then
			sg.Parent = Players.LocalPlayer:WaitForChild("PlayerGui")
		end
		U.ButtonGui = sg

		-- themed objects (colors are refreshed by the driver below)
		local accents, bgs, texts = {}, {}, {}
		local function mk(class, props, parent, theme)
			local o = Instance.new(class)
			for k, v in pairs(props) do o[k] = v end
			o.Parent = parent
			if theme == "accent" then accents[#accents + 1] = o
			elseif theme == "bg" then bgs[#bgs + 1] = o
			elseif theme == "text" then texts[#texts + 1] = o end
			return o
		end
		local function round(parent, r)
			mk("UICorner", {CornerRadius = r or UDim.new(1, 0)}, parent)
		end

		local root = mk("Frame", {
			Name = "UhTriRoot", AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5),
			Size = UDim2.fromOffset(SIZE, SIZE), BackgroundTransparency = 1, Visible = false,
		}, sg)
		local scale = mk("UIScale", {Scale = 0}, root)

		-- pulsing aura + faint orbit ring behind the button
		local aura = mk("Frame", {
			Name = "Aura", AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5),
			Size = UDim2.fromOffset(SIZE + 14, SIZE + 14), BackgroundTransparency = 0.9, BorderSizePixel = 0, ZIndex = 1,
		}, root, "accent")
		round(aura)
		local orbit = mk("Frame", {
			Name = "Orbit", AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5),
			Size = UDim2.fromOffset(SIZE + 8, SIZE + 8), BackgroundTransparency = 1, BorderSizePixel = 0, ZIndex = 2,
		}, root)
		round(orbit)
		mk("UIStroke", {Thickness = 1, Transparency = 0.7, ApplyStrokeMode = Enum.ApplyStrokeMode.Border}, orbit, "accent")

		-- the button: dark disc with a comet border that keeps circling
		local btn = mk("TextButton", {
			Name = "UhAdminButton", Size = UDim2.fromScale(1, 1), BackgroundTransparency = 0.12, BorderSizePixel = 0,
			Text = "", AutoButtonColor = false, Active = true, ZIndex = 3,
		}, root, "bg")
		round(btn)
		local stroke = mk("UIStroke", {Thickness = 2.4, ApplyStrokeMode = Enum.ApplyStrokeMode.Border}, btn, "accent")
		local grad = mk("UIGradient", {
			Color = ColorSequence.new(Color3.new(1, 1, 1)),
			Transparency = NumberSequence.new({
				NumberSequenceKeypoint.new(0, 0), NumberSequenceKeypoint.new(0.35, 0.8),
				NumberSequenceKeypoint.new(0.65, 0.8), NumberSequenceKeypoint.new(1, 0),
			}),
		}, stroke)

		-- three dots orbiting the button
		local dots = {}
		for i = 1, 3 do
			local px = i == 1 and 6 or 4
			local d = mk("Frame", {
				AnchorPoint = Vector2.new(0.5, 0.5), Size = UDim2.fromOffset(px, px),
				BackgroundTransparency = 0.1, BorderSizePixel = 0, ZIndex = 4,
			}, root, "accent")
			round(d)
			dots[i] = d
		end

		-- name tag under the triangle
		local label = mk("TextLabel", {
			Name = "Label", AnchorPoint = Vector2.new(0.5, 0), Position = UDim2.new(0.5, 0, 1, 12),
			Size = UDim2.fromOffset(190, 16), BackgroundTransparency = 1, Font = Enum.Font.GothamBold,
			TextSize = 12, Text = "UH ADMIN  \u{2022}  tap = commands  \u{2022}  hold = hide", TextTransparency = 1, ZIndex = 5,
		}, root, "text")
		local function flashLabel(secs)
			task.spawn(function()
				TweenService:Create(label, TweenInfo.new(0.3), {TextTransparency = 0}):Play()
				task.wait(secs)
				TweenService:Create(label, TweenInfo.new(0.6), {TextTransparency = 1}):Play()
			end)
		end

		-- fallback glyph (only shown if the 3D triangle engine fails, so something is ALWAYS visible)
		local glyph = mk("TextLabel", {
			Name = "Glyph", AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5),
			Size = UDim2.fromOffset(34, 34), BackgroundTransparency = 1, Text = "\u{25B2}", Font = Enum.Font.GothamBold,
			TextSize = 28, TextColor3 = Color3.new(1, 1, 1), Visible = false, ZIndex = 9,
		}, btn)

		-- the 3D triangle (same engine as the hero triangle on the home page)
		local tri
		local okTri, errTri = pcall(function()
			tri = FX.NewTriangle3D(btn, {
				Interactive = false,
				ZIndex = 9,
				LayerAnchor = Vector2.new(0.5, 0.5),
				LayerPos = UDim2.fromScale(0.5, 0.5),
				LayerSize = UDim2.fromOffset(TRI, TRI),
				IsVisible = function() return S.shown end,
			})
			tri.baseSpin = 1.2
			tri.scaleBase = 1.2
			table.insert(U.Tris, {tri = tri, mult = 1, scale = 1.2})
			U.ButtonTri = tri
		end)
		if not okTri or not tri then
			glyph.Visible = true
			warn("[UhAdmin] 3D triangle failed, using the flat one: " .. tostring(errTri))
		end

		btn.MouseEnter:Connect(function() S.hover = true end)
		btn.MouseLeave:Connect(function() S.hover = false end)

		-- ── position / drag (mouse + touch) ──
		local function vpSize()
			local v = sg.AbsoluteSize
			if v.X < 50 or v.Y < 50 then v = Util.GetScreenSize() end
			return v
		end
		local function placeAt(cx, cy) -- pixel centre, clamped so the triangle can never be lost off screen
			local v = vpSize()
			local half = SIZE / 2 + 10
			cx = math.clamp(cx, half, math.max(half, v.X - half))
			cy = math.clamp(cy, half, math.max(half, v.Y - half - 14))
			root.Position = UDim2.fromScale(cx / v.X, cy / v.Y)
		end
		local function loadPos()
			local sx, sy = tostring(FX.Cfg.AdminTriPos or ""):match("^([%d%.]+),([%d%.]+)$")
			sx, sy = tonumber(sx), tonumber(sy)
			if sx and sy then
				root.Position = UDim2.fromScale(math.clamp(sx, 0.03, 0.97), math.clamp(sy, 0.03, 0.95))
			else
				root.Position = UDim2.fromScale(0.5, 0.5) -- default: middle of the screen
			end
		end
		U.ResetTriPos = function()
			FX.SetCfg("AdminTriPos", "")
			loadPos()
		end
		loadPos()

		local function isPress(i)
			return i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch
		end
		local dragInput, dragStart, startCX, startCY
		local moved, swallow, holdToken, suppressUntil = false, false, 0, 0

		btn.InputBegan:Connect(function(input)
			if not isPress(input) then return end
			local v = vpSize()
			dragInput, dragStart, moved, swallow = input, input.Position, false, false
			startCX = root.Position.X.Scale * v.X
			startCY = root.Position.Y.Scale * v.Y
			holdToken += 1
			local mine = holdToken
			task.delay(0.7, function() -- held still = hide the triangle
				if holdToken == mine and dragInput == input and not moved then
					dragInput, moved, swallow = nil, true, true
					FX.SetCfg("AdminTriHidden", true)
					pcall(Util.Notify, FX.Cfg.AdminTriTab ~= false
						and "Command triangle hidden. Tap the little tab at the top edge (or type showtri) to bring it back."
						or "Command triangle hidden. Type showtri (prefix + showtri) or use the Customization page to bring it back.")
				end
			end)
		end)
		UIS.InputChanged:Connect(function(input)
			if not dragInput then return end
			local same = input == dragInput
				or (dragInput.UserInputType == Enum.UserInputType.MouseButton1 and input.UserInputType == Enum.UserInputType.MouseMovement)
			if not same then return end
			local d = input.Position - dragStart
			if not moved and d.Magnitude > 8 then moved = true end
			if moved then placeAt(startCX + d.X, startCY + d.Y) end
		end)
		UIS.InputEnded:Connect(function(input)
			if not dragInput then return end
			local same = input == dragInput
				or (dragInput.UserInputType == Enum.UserInputType.MouseButton1 and input.UserInputType == Enum.UserInputType.MouseButton1)
			if not same then return end
			holdToken += 1
			if moved then
				suppressUntil = os.clock() + 0.3 -- a drag never counts as a tap
				FX.SetCfg("AdminTriPos", string.format("%.4f,%.4f", root.Position.X.Scale, root.Position.Y.Scale))
			end
			dragInput = nil
		end)

		-- tap = open the command bar (the admin core plugs U.OpenBar in once it is ready)
		btn.MouseButton1Click:Connect(function()
			if swallow or os.clock() < suppressUntil then return end
			if U.OpenBar then
				local ok, e = pcall(U.OpenBar)
				if not ok then warn("[UhAdmin] open bar failed: " .. tostring(e)) end
			else
				S.shake = 1
				if U.CoreError then
					pcall(Util.Notify, "Commands failed to load at '" .. tostring(U.Stage) .. "': " .. tostring(U.CoreError):sub(1, 180))
				else
					pcall(Util.Notify, "Commands are still loading (" .. tostring(U.Stage or "waiting") .. "), tap again in a moment.")
				end
			end
		end)

		-- tiny restore tab at the top edge while the triangle is hidden
		local tab = mk("TextButton", {
			Name = "UhRestoreTab", AnchorPoint = Vector2.new(0.5, 0), Position = UDim2.new(0.5, 0, 0, 0),
			Size = UDim2.fromOffset(44, 16), BackgroundTransparency = 0.5, BorderSizePixel = 0, Visible = false,
			Text = "\u{25BC}", TextSize = 9, TextColor3 = Color3.new(1, 1, 1), Font = Enum.Font.GothamBold,
			AutoButtonColor = false, ZIndex = 3,
		}, sg, "accent")
		round(tab, UDim.new(0, 8))
		U.RestoreTab = tab
		tab.MouseButton1Click:Connect(function()
			FX.SetCfg("AdminTriHidden", false)
		end)

		-- hide / show (cfg AdminTriHidden: Customization switch + hidetri / showtri / tri commands)
		S.applied = nil
		local function applyHidden(hidden)
			if S.applied == hidden then return end
			local first = S.applied == nil
			S.applied = hidden
			if hidden then
				S.shown = false
				S.hover = false
				if first then
					scale.Scale = 0
					root.Visible = false
					if tri then tri:SetActive(false) end
				else
					TweenService:Create(scale, TweenInfo.new(0.35, Enum.EasingStyle.Back, Enum.EasingDirection.In), {Scale = 0}):Play()
					task.delay(0.37, function()
						if S.applied == true then
							root.Visible = false
							if tri then tri:SetActive(false) end
						end
					end)
				end
			else
				root.Visible = true
				S.shown = true
				if tri then
					tri:SetActive(true)
					tri:PopIn()
				end
				TweenService:Create(scale, TweenInfo.new(0.55, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {Scale = 1}):Play()
				pcall(FX.Ring, btn, Color3.new(1, 1, 1), 90, 0.6, 2)
				flashLabel(3)
			end
		end

		-- live theme (follows the UI color / accent override)
		local themeT = 0
		local function applyTheme(t)
			if t - themeT < 0.05 then return end
			themeT = t
			local cfg = FX.Cfg
			local a, b, c
			if U.GetTheme then
				local ok, x, y, z = pcall(U.GetTheme, t)
				if ok and x then a, b, c = x, y, z end
			end
			a = a or Util.LoopedHSV(t / 10, 0.8, 1)
			b = b or Color3.new(0, 0, 0)
			c = c or Color3.new(1, 1, 1)
			if cfg.UIAccent and cfg.UIAccent ~= "" then a = Util.ParseHex(cfg.UIAccent) or a end
			for _, o in ipairs(accents) do
				if o:IsA("UIStroke") then o.Color = a else o.BackgroundColor3 = a end
			end
			for _, o in ipairs(bgs) do o.BackgroundColor3 = b end
			for _, o in ipairs(texts) do o.TextColor3 = c end
		end

		-- one driver for everything that moves (also drives the command bar's comet border + scan line)
		RunService.RenderStepped:Connect(function(dt)
			local ok, err = pcall(function()
				local t = os.clock()
				applyHidden(FX.Cfg.AdminTriHidden == true)
				local showTab = S.applied == true and FX.Cfg.AdminTriTab ~= false
				tab.Visible = showTab
				if showTab then
					tab.Position = UDim2.new(root.Position.X.Scale, 0, 0, 0)
					tab.BackgroundTransparency = 0.45 + math.sin(t * 2.5) * 0.15
				end
				applyTheme(t)

				S.boost = math.max(0, S.boost - dt * 1.6)
				S.flash = math.max(0, S.flash - dt * 2.2)
				S.shake = math.max(0, S.shake - dt * 3)

				-- every registered triangle (button + bar logo) spins faster the more is going on
				local want = 0.9 + (S.hover and 1.1 or 0) + (S.open and 1.6 or 0) + S.boost * 2.5 + S.flash * 3
				for _, e in ipairs(U.Tris) do
					local T = e.tri
					if T and T.active then
						T.baseSpin = T.baseSpin + (want * e.mult - T.baseSpin) * (1 - math.exp(-6 * dt))
						T.scaleBase = e.scale * (1 + 0.05 * math.sin(t * 2.3) + 0.12 * S.flash)
					end
				end

				if S.shown then
					local speed = 1.4 + (S.open and 1.6 or 0) + S.boost * 3 + S.flash * 5
					U.orbitA = (U.orbitA or 0) + dt * speed
					local R = (SIZE + 8) / 2
					for i, d in ipairs(dots) do
						local a = U.orbitA + (i - 1) * (math.pi * 2 / 3)
						d.Position = UDim2.new(0.5, math.cos(a) * R, 0.5, math.sin(a) * R)
					end
					U.btnGrad = ((U.btnGrad or 0) + dt * (90 + S.boost * 220 + (S.open and 120 or 0))) % 360
					grad.Rotation = U.btnGrad
					local pulse = SIZE + 14 + math.sin(t * 2) * 4 + S.flash * 18
					aura.Size = UDim2.fromOffset(pulse, pulse)
					aura.BackgroundTransparency = 0.9 - S.flash * 0.35 - (S.open and 0.07 or 0)
					btn.Rotation = S.shake > 0 and math.sin(t * 55) * 7 * S.shake or 0
					if glyph.Visible then glyph.Rotation = (t * 80 * want) % 360 end
				end

				-- command bar: rotating comet border, thicker while typing / running, scan line while open
				local g, bs = U.BarGrad, U.BarStroke
				if g and g.Parent then
					U.barGradA = ((U.barGradA or 0) + dt * (70 + (S.open and 90 or 0) + S.boost * 260)) % 360
					g.Rotation = U.barGradA
					bs.Thickness = 1.4 + S.boost * 1.2 + S.flash * 1.4
				end
				local sc = U.BarScan
				if sc and sc.Parent and S.open then
					U.scanT = ((U.scanT or 0) + dt / 1.5) % 1
					sc.Position = UDim2.new(0, -70 + U.scanT * 320, 1, 0)
				end
			end)
			if not ok and not U.tickWarned then
				U.tickWarned = true
				warn("[UhAdmin] driver error: " .. tostring(err))
			end
		end)

		applyHidden(FX.Cfg.AdminTriHidden == true)
	end)
	if not okL then
		warn("[UhAdmin] triangle launcher failed: " .. tostring(errL))
	end
end

-- [uh admin ext] COMMAND CORE now starts right here (on its own thread), BEFORE the intro / module loading,
-- so the triangle can open the command bar immediately instead of waiting for them.
 --[=[ NAMELESS ADMIN CORE — UH MOD INTEGRATION ]=]--
 -- spawned on its own thread so the mod's loading/websocket loops never block the admin core
 Util.UhAdmin.Stage = "core: starting"
 task.spawn(function()
 local okCore, errCore = xpcall(function()

 --[============================================================================[]--
   NAMELESS ADMIN x NOOBY'S UH MODDED REANIMATION — integrated core
   • Full Nameless Admin command set (every cmd) running inside the Uh mod
   • Nameless Admin UI stripped & rebuilt from scratch with the Uh mod theme
     (live animated accent / dark background, follows the Customization page)
   • Nameless Admin logo PNG replaced by the mod's dynamic 3D triangle
   • Discord startup notification removed
   • Storage forwarded: Nameless-Admin/* -> UhhhhhhReanim/*
 --[]============================================================================]--

 -- [uh integration] notifications routed through the mod's own notification system
 local Notification = {}
 Notification.Notify = function(t)
	 t = t or {}
	 local desc = tostring(t.Description or "")
	 local title = tostring(t.Title or "")
	 local msg = desc
	 if title ~= "" and title ~= "Nameless Admin" then
		 msg = title .. ": " .. desc
	 end
	 pcall(Util.Notify, msg)
 end
 local Notify = Notification.Notify

 -- [uh admin ext] shared state + helpers for the command triangle, command-bar FX, fling removal, hide/show.
 -- Everything lives in Util.UhAdmin so the admin core doesn't gain extra locals (Lua's 200-local limit).
 Util.UhAdmin = Util.UhAdmin or {
	 Tris = {},
	 State = {open = false, hover = false, boost = 0, flash = 0, shake = 0, shown = false},
 }
 -- extra command names to drop on top of the "anything with 'fling' in its name" rule below
 Util.UhAdmin.BlockedCmds = {punch = true}
 -- theme colours (accent, background, text). Uses the mod's live theme once it exists, a rainbow/black/white fallback before.
 Util.UhAdmin.Theme = function(t)
	 local th = Util.UhAdmin.GetTheme
	 if th then
		 local ok, a, b, c = pcall(th, t)
		 if ok and a then return a, b or Color3.new(0, 0, 0), c or Color3.new(1, 1, 1) end
	 end
	 return Util.LoopedHSV(t / 10, 0.8, 1), Color3.new(0, 0, 0), Color3.new(1, 1, 1)
 end
	 Util.UhAdmin.IsBlocked = function(aliases)
		 local allowed = {walkfling = true, wfling = true, unwalkfling = true, unwfling = true}
		 for _, n in ipairs(aliases) do
			 local l = tostring(n):lower()
			 if Util.UhAdmin.BlockedCmds[l] then return true end
			 if l:find("fling", 1, true) and not allowed[l] then return true end
		 end
		 return false
	 end
	 Util.UhAdmin.RegisterTri = function(tri, mult, scale)
	 if tri then
		 table.insert(Util.UhAdmin.Tris, {tri = tri, mult = mult or 1, scale = scale or 1})
	 end
 end
 -- events from the bar / list: open, close, type, run, unknown. Every registered triangle reacts.
 Util.UhAdmin.Fire = function(ev)
	 local U = Util.UhAdmin
	 local S = U.State
	 local function each(f)
		 for _, e in ipairs(U.Tris) do
			 if e.tri and e.tri.active then pcall(f, e.tri) end
		 end
	 end
	 if ev == "open" then
		 S.open = true
		 each(function(t) t.yawVel = t.yawVel + 8 t.pulse = math.max(t.pulse, 0.7) end)
		 pcall(Util.FX.Play, "open", 1.2)
	 elseif ev == "close" then
		 S.open = false
	 elseif ev == "type" then
		 S.boost = math.min(1, S.boost + 0.3)
		 each(function(t) t.yawVel = t.yawVel + 2.2 end)
	 elseif ev == "run" then
		 S.flash = 1
		 each(function(t) t.yawVel = t.yawVel + 16 t.pulse = 1 t.prism = 1 end)
		 pcall(Util.FX.Play, "hit", 1.3)
	 elseif ev == "unknown" then
		 S.shake = 1
		 each(function(t)
			 t.yawVel = t.yawVel - 12
			 if not t.flipT then t.flipT = 0 end
		 end)
		 pcall(Util.FX.Play, "release", 0.8)
	 end
 end

 -- [uh integration] live theme engine for the rebuilt admin UI.
 -- Uses CollectionService tags so cloned template elements (autofill entries,
 -- command list rows, chat log lines) keep following the theme automatically.
 local UhCollectionService = game:GetService("CollectionService")
 local UH_TAG_ACCENT = "UhAdmin_Accent"
 local UH_TAG_BG     = "UhAdmin_BG"
 local UH_TAG_TEXT   = "UhAdmin_Text"
 local function uhTag(obj, kind)
	 local tagName = (kind == "accent" and UH_TAG_ACCENT) or (kind == "bg" and UH_TAG_BG) or UH_TAG_TEXT
	 UhCollectionService:AddTag(obj, tagName)
 end
 do
	 local uhThemeLast = 0
	 game:GetService("RunService").Heartbeat:Connect(function()
		 local now = os.clock()
		 if now - uhThemeLast < 0.1 then return end
		 uhThemeLast = now
		 local cfg = Util.FX and Util.FX.Cfg
		 local accent, bg, textCol = Util.UhAdmin.Theme(now)
		 if cfg and cfg.UIAccent and cfg.UIAccent ~= "" then
			 accent = Util.ParseHex(cfg.UIAccent) or accent
		 end
		 for _, o in ipairs(UhCollectionService:GetTagged(UH_TAG_ACCENT)) do
			 if o:IsA("UIStroke") then
				 o.Color = accent
			 elseif o:IsA("GuiObject") then
				 o.BackgroundColor3 = accent
			 end
		 end
		 for _, o in ipairs(UhCollectionService:GetTagged(UH_TAG_BG)) do
			 if o:IsA("GuiObject") then
				 o.BackgroundColor3 = bg
			 end
		 end
		 for _, o in ipairs(UhCollectionService:GetTagged(UH_TAG_TEXT)) do
			 if o:IsA("TextLabel") or o:IsA("TextButton") or o:IsA("TextBox") then
				 o.TextColor3 = textCol
			 end
		 end
	 end)
 end

 -- [uh integration] programmatic rebuild of the Nameless Admin UI in the Uh theme.
 -- Keeps the exact instance hierarchy the command logic expects
 -- (CmdBar.CenterBar.Input, CmdBar.Autofill.Cmd, ChatLogs.Container.Logs, ...)
 -- so every original gui.* function works untouched, minus the remote UI model.
 local function uhNew(class, props, parent)
	 local o = Instance.new(class)
	 for k, v in pairs(props) do
		 o[k] = v
	 end
	 o.Parent = parent
	 return o
 end

