		 ScreenGui = sg,
		 AdminScale = adminScale,
		 Description = description,
		 CmdBar = cmdBar,
		 CenterBar = centerBar,
		 LogoHolder = logoHolder,
		 CmdInput = cmdInput,
		 ListBtn = listBtn,
		 LeftFill = leftFill,
		 RightFill = rightFill,
		 CmdAutofill = cmdAutofill,
		 CmdExample = cmdExample,
		 CmdExampleInput = cmdExampleInput,
		 ChatLogsFrame = chatLogsFrame,
		 ChatLogs = chatLogs,
		 ChatExample = chatExample,
		 CommandsFrame = commandsFrame,
		 CommandsFilter = commandsFilter,
		 CommandsList = commandsList,
		 CommandExample = commandExample,
		 ResizeFrame = resizeFrame,
	 }
	 return sg
 end


	 -- Build the UI before the later gui.* functions populate its command list.
