 --[[ COMMAND FUNCTIONS ]]--
 commandcount = 0
 cmd = {}
 cmd._lastError = nil
 cmd.add = function(...)
	local vars = {...}
	local aliases, info, func = vars[1], vars[2], vars[3]
	if type(aliases) ~= "table" or type(func) ~= "function" then return false end
	if Util.UhAdmin.IsBlocked(aliases) then return false end
	local registration = {func, info or {}}
	local primary = aliases[1]
	if type(primary) ~= "string" or primary == "" then return false end
	Commands[primary:lower()] = registration
	for i = 2, #aliases do
		local alias = aliases[i]
		if type(alias) == "string" and alias ~= "" then Aliases[alias:lower()] = registration end
	end
	commandcount = commandcount + 1
	return true
 end

 cmd.run = function(args)
	cmd._lastError = nil
	if type(args) ~= "table" then cmd._lastError = "Invalid command arguments"; return false, cmd._lastError end
	local caller = type(args[1]) == "string" and args[1]:lower() or nil
	if not caller or caller == "" then cmd._lastError = "No command specified"; return false, cmd._lastError end
	local registration = Commands[caller] or Aliases[caller]
	if not registration then cmd._lastError = "Unknown command: " .. tostring(args[1]); return false, cmd._lastError end
	local arguments = {}
	for i = 2, #args do arguments[#arguments + 1] = args[i] end
	local success, err = _native_pcall(function() registration[1](table.unpack(arguments)) end)
	if not success then cmd._lastError = tostring(err); return false, cmd._lastError end
	return true
 end
 
