 -- [[ FUNCTION TO GET A PLAYER ]] --
 local getPlr = function(Name)
	if type(Name) ~= "string" then return nil end
	local query = Name:lower():gsub("%s", "")
	local players = Players:GetPlayers()
	if query == "random" then if #players == 0 then return nil end; return players[math.random(1, #players)] end
	if query == "" then return nil end
	local prefixMatch, containsMatch
	for _, x in ipairs(players) do
		local user = x.Name:lower()
		local display = x.DisplayName:lower():gsub("%s", "")
		if user == query or display == query then return x end
		if not prefixMatch and (user:sub(1, #query) == query or display:sub(1, #query) == query) then prefixMatch = x end
		if not containsMatch and user:find(query, 1, true) then containsMatch = x end
	end
	return prefixMatch or containsMatch
end

