function mobilefly(speed)
	local player = cmdlp or Players.LocalPlayer
	if not player then return false end

	pcall(unvfly)

	_G.__UH_MOBILE_FLY_SPEED = math.clamp(tonumber(speed) or 10, 1, 200)
	pcall(unmobilefly)

	local function getCharacter()
		local char = player.Character
		local hum = char and char:FindFirstChildOfClass("Humanoid")
		local root = char and char:FindFirstChild("HumanoidRootPart")
		return char, hum, root
	end

	local function makeMovers(root)
		if not root then return nil, nil end
		for _, name in ipairs({"UHAdminMobileFlyVelocity", "UHAdminMobileFlyGyro"}) do
			local old = root:FindFirstChild(name)
			if old then old:Destroy() end
		end

		local bv = Instance.new("BodyVelocity")
		bv.Name = "UHAdminMobileFlyVelocity"
		bv.MaxForce = Vector3.new(1e9, 1e9, 1e9)
		bv.P = 10000
		bv.Velocity = Vector3.zero
		bv.Parent = root

		local bg = Instance.new("BodyGyro")
		bg.Name = "UHAdminMobileFlyGyro"
		bg.MaxTorque = Vector3.new(1e9, 1e9, 1e9)
		bg.P = 100000
		bg.D = 1000
		bg.CFrame = root.CFrame
		bg.Parent = root

		return bv, bg
	end

	local controlModule
	pcall(function()
		local playerScripts = player:FindFirstChild("PlayerScripts") or player:WaitForChild("PlayerScripts", 5)
		local playerModule = playerScripts and (playerScripts:FindFirstChild("PlayerModule") or playerScripts:WaitForChild("PlayerModule", 5))
		local controlModuleScript = playerModule and (playerModule:FindFirstChild("ControlModule") or playerModule:WaitForChild("ControlModule", 5))
		if controlModuleScript then
			controlModule = require(controlModuleScript)
		end
	end)

	local jumpUntil = 0
	FLYING = true
	_G.__UH_FLY_MODE = "mobile"

	_G.__UH_MOBILE_FLY_JUMP = UserInputService.JumpRequest:Connect(function()
		if FLYING then
			jumpUntil = os.clock() + 0.35
		end
	end)

	local _, hum, root = getCharacter()
	if root then makeMovers(root) end
	if hum then
		hum.AutoRotate = false
		hum.PlatformStand = false
	end

	_G.__UH_MOBILE_FLY_STEP = RunService.RenderStepped:Connect(function()
		if not FLYING or (_G.__UH_FLY_MODE and _G.__UH_FLY_MODE ~= "mobile") then return end

		local char, humanoid, hrp = getCharacter()
		local camera = workspace.CurrentCamera
		if not humanoid or not hrp or not camera or humanoid.Health <= 0 then return end

		local bv = hrp:FindFirstChild("UHAdminMobileFlyVelocity")
		local bg = hrp:FindFirstChild("UHAdminMobileFlyGyro")
		if not bv or not bg then
			bv, bg = makeMovers(hrp)
		end
		if not bv or not bg then return end

		local move = Vector3.zero
		if controlModule then
			pcall(function()
				move = controlModule:GetMoveVector() or Vector3.zero
			end)
		end

		-- Fallback for games/executors where PlayerModule's ControlModule
		-- cannot be required. MoveDirection is still reliable for the thumbstick.
		if move.Magnitude < 0.01 then
			move = humanoid.MoveDirection
		end

		local cf = camera.CFrame
		local flatLook = Vector3.new(cf.LookVector.X, 0, cf.LookVector.Z)
		local flatRight = Vector3.new(cf.RightVector.X, 0, cf.RightVector.Z)

		if flatLook.Magnitude > 0.001 then
			flatLook = flatLook.Unit
		else
			flatLook = Vector3.new(0, 0, -1)
		end
		if flatRight.Magnitude > 0.001 then
			flatRight = flatRight.Unit
		else
			flatRight = Vector3.new(1, 0, 0)
		end

		local horizontal = flatRight * move.X + flatLook * (-move.Z)
		local vertical = 0

		-- Looking up/down while pushing the thumbstick now gives true 3D flight.
		if move.Magnitude > 0.05 then
			vertical = cf.LookVector.Y * math.clamp(math.abs(move.Z), 0, 1)
		end

		-- Jump provides a short, reliable upward boost on mobile.
		if os.clock() < jumpUntil then
			vertical = math.max(vertical, 1)
		end

		local velocity = horizontal + Vector3.new(0, vertical, 0)
		if velocity.Magnitude > 0.001 then
			bv.Velocity = velocity.Unit * _G.__UH_MOBILE_FLY_SPEED
		else
			bv.Velocity = Vector3.zero
		end

		bg.CFrame = CFrame.lookAt(hrp.Position, hrp.Position + flatLook, Vector3.yAxis)
		humanoid.AutoRotate = false
		-- PlatformStand can suppress MoveDirection on some mobile clients.
		-- BodyVelocity is sufficient to hold the character in flight.
		humanoid.PlatformStand = false
	end)

	_G.__UH_MOBILE_FLY_RESPAWN = player.CharacterAdded:Connect(function(char)
		local hrp = char:WaitForChild("HumanoidRootPart", 10)
		local humanoid = char:FindFirstChildOfClass("Humanoid") or char:WaitForChild("Humanoid", 5)
		if not FLYING or not hrp then return end
		makeMovers(hrp)
		if humanoid then
			humanoid.AutoRotate = false
			humanoid.PlatformStand = false
		end
	end)

	return true
end

function unmobilefly()
	if _G.__UH_FLY_MODE == "mobile" or _G.__UH_FLY_MODE == nil then
		FLYING = false
		if _G.__UH_FLY_MODE == "mobile" then _G.__UH_FLY_MODE = nil end
	end

	for _, key in ipairs({
		"__UH_MOBILE_FLY_STEP",
		"__UH_MOBILE_FLY_RESPAWN",
		"__UH_MOBILE_FLY_JUMP",
		"__UH_MOBILE_FLY_UI_INPUT",
	}) do
		local connection = _G[key]
		if connection then
			pcall(function() connection:Disconnect() end)
		end
		_G[key] = nil
	end

	local player = cmdlp or Players.LocalPlayer
	local char = player and player.Character
	local hum = char and char:FindFirstChildOfClass("Humanoid")
	if hum then
		hum.PlatformStand = false
		hum.AutoRotate = true
	end

	local root = char and char:FindFirstChild("HumanoidRootPart")
	if root then
		for _, name in ipairs({
			"UHAdminMobileFlyVelocity",
			"UHAdminMobileFlyGyro",
			"VelocityHandler",
			"GyroHandler",
		}) do
			local obj = root:FindFirstChild(name)
			if obj then obj:Destroy() end
		end
	end

	local coreGui = game:GetService("CoreGui")
	local flyGui = coreGui:FindFirstChild("UHAdminMobileFly")
	if flyGui then flyGui:Destroy() end
end

