function sFLY(vfly, requestedSpeed)
	speedofthefly = math.clamp(tonumber(requestedSpeed) or tonumber(speedofthefly) or 10, 1, 200)
	speedofthevfly = math.clamp(tonumber(requestedSpeed) or tonumber(speedofthevfly) or 10, 1, 200)
	pcall(unvfly)
	pcall(unmobilefly)

	local player = cmdlp or Players.LocalPlayer
	if not player then return false end

	local keyboardControl = {F = 0, B = 0, L = 0, R = 0, Q = 0, E = 0}
	local controlModule
	local jumpUntil = 0
	local touchMode = UserInputService.TouchEnabled
	local activeSpeed = tonumber(vfly and speedofthevfly or speedofthefly) or 10

	if touchMode then
		pcall(function()
			local playerScripts = player:FindFirstChild("PlayerScripts") or player:WaitForChild("PlayerScripts", 5)
			local playerModule = playerScripts and (playerScripts:FindFirstChild("PlayerModule") or playerScripts:WaitForChild("PlayerModule", 5))
			local controlModuleScript = playerModule and (playerModule:FindFirstChild("ControlModule") or playerModule:WaitForChild("ControlModule", 5))
			if controlModuleScript then controlModule = require(controlModuleScript) end
		end)

		_G.__UH_FLY_JUMP = UserInputService.JumpRequest:Connect(function()
			if FLYING then jumpUntil = os.clock() + 0.35 end
		end)
	else
		_G.__UH_FLY_INPUT_BEGAN = UserInputService.InputBegan:Connect(function(input, gp)
			if gp then return end
			local k = input.KeyCode
			if k == Enum.KeyCode.W then keyboardControl.F = 1
			elseif k == Enum.KeyCode.S then keyboardControl.B = -1
			elseif k == Enum.KeyCode.A then keyboardControl.L = -1
			elseif k == Enum.KeyCode.D then keyboardControl.R = 1
			elseif k == Enum.KeyCode.Y then keyboardControl.Q = 1
			elseif k == Enum.KeyCode.T then keyboardControl.E = -1
			end
		end)

		_G.__UH_FLY_INPUT_ENDED = UserInputService.InputEnded:Connect(function(input)
			local k = input.KeyCode
			if k == Enum.KeyCode.W then keyboardControl.F = 0
			elseif k == Enum.KeyCode.S then keyboardControl.B = 0
			elseif k == Enum.KeyCode.A then keyboardControl.L = 0
			elseif k == Enum.KeyCode.D then keyboardControl.R = 0
			elseif k == Enum.KeyCode.Y then keyboardControl.Q = 0
			elseif k == Enum.KeyCode.T then keyboardControl.E = 0
			end
		end)
	end

	local function getChar()
		local char = player.Character
		return char, char and char:FindFirstChildOfClass("Humanoid"), char and char:FindFirstChild("HumanoidRootPart")
	end

	local function apply(root, hum)
		local bg = root:FindFirstChild("UHAdminFlyGyro") or Instance.new("BodyGyro")
		bg.Name = "UHAdminFlyGyro"
		bg.P = 100000
		bg.D = 1000
		bg.MaxTorque = Vector3.new(1e9, 1e9, 1e9)
		bg.Parent = root

		local bv = root:FindFirstChild("UHAdminFlyVelocity") or Instance.new("BodyVelocity")
		bv.Name = "UHAdminFlyVelocity"
		bv.MaxForce = Vector3.new(1e9, 1e9, 1e9)
		bv.P = 10000
		bv.Parent = root

		local camera = workspace.CurrentCamera
		local cf = camera and camera.CFrame or root.CFrame

		local move = Vector3.zero
		if touchMode then
			local moveIsWorldSpace = false
			if controlModule then
				pcall(function()
					local controlMove = controlModule:GetMoveVector()
					if controlMove then move = controlMove end
				end)
			end
			if move.Magnitude < 0.01 then
				move = hum.MoveDirection or Vector3.zero
				moveIsWorldSpace = true
			end

			local flatLook = Vector3.new(cf.LookVector.X, 0, cf.LookVector.Z)
			local flatRight = Vector3.new(cf.RightVector.X, 0, cf.RightVector.Z)
			if flatLook.Magnitude > 0.001 then flatLook = flatLook.Unit else flatLook = Vector3.new(0,0,-1) end
			if flatRight.Magnitude > 0.001 then flatRight = flatRight.Unit else flatRight = Vector3.new(1,0,0) end

			local horizontal
			if moveIsWorldSpace then
				horizontal = flatLook * move:Dot(flatLook) + flatRight * move:Dot(flatRight)
			else
				horizontal = flatRight * move.X + flatLook * (-move.Z)
			end
			local vertical = (move.Magnitude > 0.05 and cf.LookVector.Y * math.clamp(move.Magnitude, 0, 1) or 0)
			if os.clock() < jumpUntil then vertical = math.max(vertical, 1) end

			move = horizontal + Vector3.new(0, vertical, 0)
		else
			move = Vector3.new(cf.LookVector.X, 0, cf.LookVector.Z)
			local right = Vector3.new(cf.RightVector.X, 0, cf.RightVector.Z)
			if move.Magnitude > 0.001 then move = move.Unit else move = Vector3.new(0,0,-1) end
			if right.Magnitude > 0.001 then right = right.Unit else right = Vector3.new(1,0,0) end
			move = move * (keyboardControl.F + keyboardControl.B)
				+ right * (keyboardControl.R + keyboardControl.L)
				+ Vector3.new(0, keyboardControl.Q + keyboardControl.E, 0)
		end

		if move.Magnitude > 0.001 then
			bv.Velocity = move.Unit * activeSpeed
		else
			bv.Velocity = Vector3.zero
		end

		local flatLook = Vector3.new(cf.LookVector.X, 0, cf.LookVector.Z)
		if flatLook.Magnitude > 0.001 then
			flatLook = flatLook.Unit
		else
			flatLook = Vector3.new(0,0,-1)
		end
		bg.CFrame = CFrame.lookAt(root.Position, root.Position + flatLook, Vector3.yAxis)

		hum.AutoRotate = false
		if not touchMode and not vfly then
			hum.PlatformStand = true
		else
			hum.PlatformStand = false
		end
	end

	FLYING = true
	_G.__UH_FLY_MODE = "standard"

	_G.__UH_FLY_STEP = RunService.RenderStepped:Connect(function()
		if not FLYING then return end
		local char, hum, root = getChar()
		if char and hum and root and hum.Health > 0 then
			apply(root, hum)
		end
	end)

	local _, hum, root = getChar()
	if hum then hum.AutoRotate = false end
	if root then apply(root, hum) end

	return true
end

function unvfly()
	FLYING=false
	if _G.__UH_FLY_MODE == "standard" then _G.__UH_FLY_MODE = nil end
