 -- [[ LIB FUNCTIONS ]] --
 lib.lock = function(instance, par)
	 locks[instance] = true
	 instance.Parent = par or instance.Parent
	 instance.Name = "RightGrip"
 end
 lock = lib.lock
 locks = {}
 
 lib.find = function(t, v)	-- mmmmmm
	 for i, e in pairs(t) do
		 if i == v or e == v then
			 return i
		 end
	 end
	 return nil
 end
 
 lib.parseText = function(text, watch)
	local parsed = {}
	if type(text) ~= "string" then return parsed end
	local delimiter = tostring(watch or " ")
	if delimiter == "" then return {text} end
	local token, quote, escape = {}, nil, false
	local function push() if #token > 0 then parsed[#parsed + 1] = table.concat(token); token = {} end end
	for i=1,#text do
		local ch=text:sub(i,i)
		if escape then token[#token+1]=ch; escape=false
		elseif ch=="\\" and quote then escape=true
		elseif quote then if ch==quote then quote=nil else token[#token+1]=ch end
		elseif ch=="'" or ch=='"' then quote=ch
		elseif delimiter==opt.prefix and ch==delimiter then push()
		elseif delimiter==opt.tupleSeparator and ch==delimiter then push()
		elseif delimiter==" " and ch:match("%s") then push()
		else token[#token+1]=ch end
	end
	push(); return parsed
end

lib.parseCommand = function(text)
	if type(text) ~= "string" then return false end
	local prefix=tostring(opt.prefix or ";"); local source=text
	while source:sub(1,#prefix)==prefix do source=source:sub(#prefix+1) end
	if source:match("^%s*$") then return false end
	local segments,current,quote={}, {}, nil
	for i=1,#source do
		local ch=source:sub(i,i)
		if ch=="'" or ch=='"' then if quote==ch then quote=nil elseif not quote then quote=ch end; current[#current+1]=ch
		elseif ch==";" and not quote then segments[#segments+1]=table.concat(current); current={}
		else current[#current+1]=ch end
	end
	segments[#segments+1]=table.concat(current)
	local ran=false
	for _,segment in ipairs(segments) do
		local args=lib.parseText(segment," ")
		if #args>0 then local ok,err=cmd.run(args); if ok then ran=true else Util.Notify("Command failed: "..tostring(err)) end end
	end
	return ran
end

