 -- [uh admin ext] triangle visibility + the external walkfling command.
 -- Wrapped in a function so its locals never count against the admin core's local limit.
 Util.UhAdmin.RegisterCmds = function()
	 local function setHidden(v)
		 Util.FX.SetCfg("AdminTriHidden", v and true or false)
	 end
	 cmd.add({"hidetri", "hidetriangle"}, {"hidetri (hidetriangle)", "Hides the floating command triangle. Bring it back with showtri (or the Customization page)"}, function()
		 setHidden(true)
		 Notify({Description = "Command triangle hidden. Open the bar with '" .. opt.prefix .. "' and type showtri to bring it back.", Title = "Uh Admin", Duration = 5})
	 end)
	 cmd.add({"showtri", "showtriangle"}, {"showtri (showtriangle)", "Shows the floating command triangle again"}, function()
		 setHidden(false)
		 Notify({Description = "Command triangle is back.", Title = "Uh Admin", Duration = 3})
	 end)
	 cmd.add({"resettri", "triposition"}, {"resettri (triposition)", "Moves the floating command triangle back to the top centre of the screen"}, function()
		 if Util.UhAdmin.ResetTriPos then Util.UhAdmin.ResetTriPos() end
	 end)
	 cmd.add({"tri", "toggletri"}, {"tri (toggletri)", "Hides / shows the floating command triangle"}, function()
		 setHidden(not Util.FX.Cfg.AdminTriHidden)
	 end)

	 -- walkfling is the only fling command exposed by the external Uh Admin.
	 -- The other fling variants are selectable only from the main Fling Method dropdown.
	 local WalkFling = {Enabled = false, Running = false}
	 Util.UhAdmin.WalkFling = WalkFling

	 local function setWalkFling(enabled)
		 WalkFling.Enabled = enabled and true or false
		 if not WalkFling.Enabled or WalkFling.Running then return end
		 WalkFling.Running = true
		 task.spawn(function()
			 local movel = 0.1
			 while WalkFling.Enabled do
				 RunService.Heartbeat:Wait()
				 if not WalkFling.Enabled then break end
				 local c = Player.Character
				 local hrp = c and (c:FindFirstChild("HumanoidRootPart") or c:FindFirstChild("Torso") or c:FindFirstChild("UpperTorso"))
				 if c and c.Parent and hrp and hrp.Parent then
					 local vel = hrp.Velocity
					hrp.Velocity = vel * 10000 + Vector3.new(0, 10000, 0)
					RunService.RenderStepped:Wait()
					if WalkFling.Enabled and c.Parent and hrp.Parent then
						hrp.Velocity = vel
					end
					RunService.Stepped:Wait()
					if WalkFling.Enabled and c.Parent and hrp.Parent then
						hrp.Velocity = vel + Vector3.new(0, movel, 0)
						movel = movel * -1
					end
				end
			end
			WalkFling.Running = false
		end)
	 end

	 cmd.add({"walkfling", "wfling"}, {"walkfling (wfling)", "Enable walkfling"}, function()
		 setWalkFling(true)
		 Notify({Description = "Walkfling enabled", Title = "Uh Admin", Duration = 5})
	 end)

	 cmd.add({"unwalkfling", "unwfling"}, {"unwalkfling (unwfling)", "Disable walkfling"}, function()
		 setWalkFling(false)
		 Notify({Description = "Walkfling disabled", Title = "Uh Admin", Duration = 5})
	 end)
 end
 Util.UhAdmin.RegisterCmds()
 
