 local swimming = false
 local RunService = game:GetService("RunService")
 oldgrav = workspace.Gravity
 workspace.Gravity = 0
 local char = game.Players.LocalPlayer.Character
 local swimDied = function()
 workspace.Gravity = oldgrav
 swimming = false
 end
 local Humanoid = char:FindFirstChildWhichIsA("Humanoid")
 gravReset = Humanoid.Died:Connect(swimDied)
 local enums = Enum.HumanoidStateType:GetEnumItems()
 table.remove(enums, table.find(enums, Enum.HumanoidStateType.None))
 for i, v in pairs(enums) do
 Humanoid:SetStateEnabled(v, false)
 end
 Humanoid:ChangeState(Enum.HumanoidStateType.Swimming)
 swimbeat = RunService.Heartbeat:Connect(function()
 pcall(function()
 char.HumanoidRootPart.Velocity = ((Humanoid.MoveDirection ~= Vector3.new() or UserInputService:IsKeyDown(Enum.KeyCode.Space)) and char.HumanoidRootPart.Velocity or Vector3.new())
 end)
 end)
 swimming = true
 local Clip = false
 wait(0.1)
 local function NoclipLoop()
 if Clip == false and char ~= nil then
 for _, child in pairs(char:GetDescendants()) do
 if child:IsA("BasePart") and child.CanCollide == true then
 child.CanCollide = false
 end
 end
 end
 end
 Noclipping = RunService.Stepped:Connect(NoclipLoop)
 loadstring(game:HttpGet('https://raw.githubusercontent.com/DigitalityScripts/roblox-scripts/main/Leg%20Resize'))()
 end)

 
 cmd.add({"fpsbooster", "lowgraphics", "boostfps", "lowg"}, {"fpsbooster (lowgraphics, boostfps, lowg)", "Low graphics mode if the game is laggy"}, function()
	 local decalsyeeted = true
	 local g = game
	 local w = g.Workspace
	 local l = g.Lighting
	 local t = w.Terrain
	 sethiddenproperty(l,"Technology",2)
	 sethiddenproperty(t,"Decoration",false)
	 t.WaterWaveSize = 0
	 t.WaterWaveSpeed = 0
	 t.WaterReflectance = 0
	 t.WaterTransparency = 0
	 l.GlobalShadows = 0
	 l.FogEnd = 9e9
	 l.Brightness = 0
	 settings().Rendering.QualityLevel = "Level01"
	 for i, v in pairs(w:GetDescendants()) do
		 if v:IsA("BasePart") and not v:IsA("MeshPart") then
			 v.Material = "Plastic"
			 v.Reflectance = 0
		 elseif (v:IsA("Decal") or v:IsA("Texture")) and decalsyeeted then
			 v.Transparency = 1
		 elseif v:IsA("ParticleEmitter") or v:IsA("Trail") then
			 v.Lifetime = NumberRange.new(0)
		 elseif v:IsA("Explosion") then
			 v.BlastPressure = 1
			 v.BlastRadius = 1
		 elseif v:IsA("Fire") or v:IsA("SpotLight") or v:IsA("Smoke") or v:IsA("Sparkles") then
			 v.Enabled = false
		 elseif v:IsA("MeshPart") and decalsyeeted then
			 v.Material = "Plastic"
			 v.Reflectance = 0
			 v.TextureID = 10385902758728957
		 elseif v:IsA("SpecialMesh") and decalsyeeted  then
			 v.TextureId=0
		 elseif v:IsA("ShirtGraphic") and decalsyeeted then
			 v.Graphic=0
		 elseif (v:IsA("Shirt") or v:IsA("Pants")) and decalsyeeted then
			 v[v.ClassName.."Template"]=0
		 end
	 end
	 for i = 1,#l:GetChildren() do
		 e=l:GetChildren()[i]
		 if e:IsA("BlurEffect") or e:IsA("SunRaysEffect") or e:IsA("ColorCorrectionEffect") or e:IsA("BloomEffect") or e:IsA("DepthOfFieldEffect") then
			 e.Enabled = false
		 end
	 end
	 w.DescendantAdded:Connect(function(v)
		 wait()--prevent errors and shit
		if v:IsA("BasePart") and not v:IsA("MeshPart") then
			 v.Material = "Plastic"
			 v.Reflectance = 0
		 elseif v:IsA("Decal") or v:IsA("Texture") and decalsyeeted then
			 v.Transparency = 1
		 elseif v:IsA("ParticleEmitter") or v:IsA("Trail") then
			 v.Lifetime = NumberRange.new(0)
		 elseif v:IsA("Explosion") then
			 v.BlastPressure = 1
			 v.BlastRadius = 1
		 elseif v:IsA("Fire") or v:IsA("SpotLight") or v:IsA("Smoke") or v:IsA("Sparkles") then
			 v.Enabled = false
		 elseif v:IsA("MeshPart") and decalsyeeted then
			 v.Material = "Plastic"
			 v.Reflectance = 0
			 v.TextureID = 10385902758728957
		 elseif v:IsA("SpecialMesh") and decalsyeeted then
			 v.TextureId=0
		 elseif v:IsA("ShirtGraphic") and decalsyeeted then
			 v.ShirtGraphic=0
		 elseif (v:IsA("Shirt") or v:IsA("Pants")) and decalsyeeted then
			 v[v.ClassName.."Template"]=0
		 end
	 end)
 end)
 
