 cmd.add({"mobilefly", "mfly"}, {"mobilefly [speed] (mfly)", "Enable mobile/touch flight"}, function(speed)
	local requested = math.clamp(tonumber(speed) or 69, 1, 200)
	local touchCapable = UserInputService.TouchEnabled

	if not touchCapable then
		-- Keep the command useful on desktop too instead of silently doing nothing.
		sFLY(false, requested)
		Notify({
			Description = "Touch input not detected; keyboard flight enabled at " .. tostring(requested),
			Title = "Nameless Admin",
			Duration = 4,
		})
		return
	end

	local coreGui = game:GetService("CoreGui")
	local existing = coreGui:FindFirstChild("UHAdminMobileFly")
	if existing then existing:Destroy() end

	local screenGui = Instance.new("ScreenGui")
	screenGui.Name = "UHAdminMobileFly"
	screenGui.ResetOnSpawn = false
	screenGui.IgnoreGuiInset = true
	screenGui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
	screenGui.DisplayOrder = 2147483647
	screenGui.Parent = coreGui

	local button = Instance.new("TextButton")
	button.Name = "Toggle"
	button.AnchorPoint = Vector2.new(1, 0.5)
	button.Position = UDim2.new(1, -24, 0.5, 0)
	button.Size = UDim2.fromOffset(86, 46)
	button.BackgroundColor3 = Color3.fromRGB(12, 4, 20)
	button.BackgroundTransparency = 0.1
	button.TextColor3 = Color3.new(1, 1, 1)
	button.Font = Enum.Font.SourceSansBold
	button.TextScaled = true
	button.Text = "Unfly"
	button.AutoButtonColor = true
	button.Active = true
	button.Parent = screenGui

	local corner = Instance.new("UICorner")
	corner.CornerRadius = UDim.new(0, 10)
	corner.Parent = button

	local stroke = Instance.new("UIStroke")
	stroke.Thickness = 2
	stroke.Color = Color3.fromRGB(130, 70, 255)
	stroke.Parent = button

	local padding = Instance.new("UIPadding")
	padding.PaddingLeft = UDim.new(0, 8)
	padding.PaddingRight = UDim.new(0, 8)
	padding.Parent = button

	local dragging = false
	local dragStart, startPos

	button.InputBegan:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.Touch or input.UserInputType == Enum.UserInputType.MouseButton1 then
			dragging = true
			dragStart = input.Position
			startPos = button.Position
			input.Changed:Connect(function()
				if input.UserInputState == Enum.UserInputState.End then dragging = false end
			end)
		end
	end)

	_G.__UH_MOBILE_FLY_UI_INPUT = UserInputService.InputChanged:Connect(function(input)
		if not dragging then return end
		if input.UserInputType ~= Enum.UserInputType.Touch and input.UserInputType ~= Enum.UserInputType.MouseMovement then return end
		local delta = input.Position - dragStart
		button.Position = UDim2.new(
			startPos.X.Scale, startPos.X.Offset + delta.X,
			startPos.Y.Scale, startPos.Y.Offset + delta.Y
		)
	end)

	button.Activated:Connect(function()
		if _G.__UH_FLY_MODE == "mobile" then
			unmobilefly()
			button.Text = "Fly"
		else
			pcall(unvfly)
			mobilefly(requested)
			button.Text = "Unfly"
		end
	end)

	mobilefly(requested)
	Notify({
		Description = "Mobile flight enabled at " .. tostring(requested) .. ". Push the thumbstick and tilt the camera for vertical flight; jump gives a lift boost.",
		Title = "Nameless Admin",
		Duration = 5,
	})
end)

