 -- [[ Admin Player]]
 local _adminChatConnections = _adminChatConnections or {}
local function AdminChatted(_, Player)
	if not Player or _adminChatConnections[Player] then return end
	_adminChatConnections[Player]=Player.Chatted:Connect(function(Message)
		if Admin[Player.UserId] then lib.parseCommand(Message,Player) end
	end)
end
function CheckPermissions(Player)
	if Player and Admin[Player.UserId] then AdminChatted(nil,Player) end
end
Players.PlayerRemoving:Connect(function(Player)
	local connection=_adminChatConnections[Player]
	if connection then connection:Disconnect(); _adminChatConnections[Player]=nil end
end)

