 gui.txtSize = function(ui, x, y)
	 local textService = game:GetService("TextService")
	 return textService:GetTextSize(ui.Text, ui.TextSize, ui.Font, Vector2.new(x, y))
 end
 -- [uh admin ext] command list: sorted, tap = put it in the bar, long-press / mouse hold = description popup
 gui._showDesc = function(row, text)
	 local U = Util.UhAdmin
	 U.DescPinned = true
	 U.DescToken = (U.DescToken or 0) + 1
	 description.Text = (text and text ~= "") and text or "No description."
	 description.Visible = true
	 local size = gui.txtSize(description, 230, 240)
	 local sx, sy = size.X + 18, size.Y + 12
	 description.Size = UDim2.fromOffset(sx, sy)
	 local vp = Util.GetScreenSize()
	 local ap, as = row.AbsolutePosition, row.AbsoluteSize
	 local x = math.clamp(ap.X + 10, 6, math.max(6, vp.X - sx - 6))
	 local y = ap.Y + as.Y + 4
	 if y + sy > vp.Y - 6 then y = ap.Y - sy - 4 end
	 description.Position = UDim2.fromOffset(x, math.max(6, y))
	 gui._hideDesc(4) -- safety net so a missed release can never leave the popup stuck
 end
 gui._hideDesc = function(delay)
	 local U = Util.UhAdmin
	 local token = U.DescToken
	 task.delay(delay or 0, function()
		 if U.DescToken ~= token then return end
		 U.DescPinned = false
		 description.Visible = false
		 description.Text = ""
	 end)
 end
 gui._useCmd = function(cmdName)
	 gui.barSelect()
	 cmdInput.Text = cmdName .. " "
	 cmdInput:CaptureFocus()
 end
 gui._bindRow = function(row, cmdName, tbl)
	 local held, startPos, startT, shown = nil, Vector2.zero, 0, false
	 local function pos(input)
		 if input.UserInputType == Enum.UserInputType.Touch then
			 return Vector2.new(input.Position.X, input.Position.Y)
		 end
		 return UserInputService:GetMouseLocation()
	 end
	 row.InputBegan:Connect(function(input)
		 local ty = input.UserInputType
		 if ty ~= Enum.UserInputType.MouseButton1 and ty ~= Enum.UserInputType.Touch then return end
		 held, shown, startPos, startT = input, false, pos(input), os.clock()
		 task.delay(0.45, function()
			 if held ~= input or shown then return end
			 if (pos(input) - startPos).Magnitude > 12 then return end -- finger moved: it's a scroll, not a hold
			 shown = true
			 gui._showDesc(row, tbl[2][2])
			 pcall(Util.FX.Play, "tick", 1.1)
		 end)
	 end)
	 row.InputEnded:Connect(function(input)
		 if held ~= input then return end
		 held = nil
		 if shown then
			 gui._hideDesc(1.8)
		 elseif (pos(input) - startPos).Magnitude <= 12 and os.clock() - startT < 0.45 then
			 gui._useCmd(cmdName)
		 end
	 end)
 end
 gui.commands = function()
	 if not commandsFrame or not commandsList or not commandExample then
		 error("UhAdmin UI is not initialized (Commands window missing)")
	 end
	 if not commandsFrame.Visible then
		 commandsFrame.Visible = true
		 commandsList.CanvasSize = UDim2.new(0, 0, 0, 0)
	 end
	 for _, v in pairs(commandsList:GetChildren()) do
		 if v:IsA("TextLabel") and v ~= commandExample then
			 v:Destroy()
		 end
	 end
	 local names = {}
	 for cmdName in pairs(Commands) do
		 names[#names + 1] = cmdName
	 end
	 table.sort(names)
	 for idx, cmdName in ipairs(names) do
		 local tbl = Commands[cmdName]
		 local Cmd = commandExample:Clone()
		 Cmd.Name = cmdName
		 Cmd.LayoutOrder = idx
		 Cmd.Text = " " .. tbl[2][1]
		 Cmd.Parent = commandsList
		 gui._bindRow(Cmd, cmdName, tbl)
	 end
	 commandsList.CanvasSize = UDim2.new(0, 0, 0, #names * 20 + 10)
	 -- [fixed] Only centre on first open; preserve user-dragged position.
	 local U = Util.UhAdmin
	 if not U.CommandsOpened then
		 commandsFrame.Position = UDim2.new(0.5, -283/2, 0.5, -260/2)
		 U.CommandsOpened = true
	 end
	 commandsFilter.Text = ""
 end
 Util.UhAdmin.OpenList = function()
	 gui.commands()
 end
