 -- [fixed] Replaced deprecated mouse.KeyDown with UserInputService
 UserInputService.InputBegan:Connect(function(input, gp)
	 if gp then return end
	 if input.UserInputType ~= Enum.UserInputType.Keyboard then return end
	 local ok, keyText = pcall(function() return UserInputService:GetStringForKeyCode(input.KeyCode) end)
	 local ch = ok and type(keyText) == "string" and keyText:sub(1,1):lower() or ""
	 if ch == "" then return end
	 if ch == tostring(opt.prefix or ";"):sub(1,1):lower() then
		 gui.barSelect()
		 cmdInput.Text = ''
		 cmdInput:CaptureFocus()
		 task.wait(0.00005)
		 cmdInput.Text = ''
	 end
 end)

 -- [[ CLOSE THE COMMAND BAR ]] -- 
 cmdInput.FocusLost:Connect(function(enterPressed)
	 if enterPressed then
		 local pfx = (opt.prefix:gsub("%p", "%%%0"))
		 local word = ((cmdInput.Text:lower()):gsub("^%s*" .. pfx, "")):match("^%s*(%S+)") or ""
		 local known = (Commands[word] or Aliases[word]) and true or false
		 pcall(Util.UhAdmin.Fire, known and "run" or (word ~= "" and "unknown" or "close"))
		 if not known and word:find("fling", 1, true) and not word:find("antifling", 1, true) then
			 Notify({Description = "Standalone fling variants are disabled. Choose Fling 1, Fling 2, Fling 3, or NaN State from the Fling Method dropdown."; Title = "Uh Admin"; Duration = 6;})
		 end
		 wrap(function()
			 local entered=cmdInput.Text or ""
			 local prefix=tostring(opt.prefix or ";")
			 if entered:sub(1,#prefix)==prefix then entered=entered:sub(#prefix+1) end
			 lib.parseCommand(prefix .. entered)
		 end)
	 end
	 gui.barDeselect()
 end)
 
 cmdInput.Changed:Connect(function(p)
	 if p ~= "Text" then return end
	 if cmdInput.Text ~= "" then pcall(Util.UhAdmin.Fire, "type") end
	 gui.searchCommands()
