	ListBox.ScrollBarImageTransparency = 0.5
	ListBox.ScrollBarImageColor3 = UITextColor.Value
	Util.LinkDestroyI2C(ListBox, UITextColor.Changed:Connect(function(val)
		ListBox.ScrollBarImageColor3 = val
