local MainPage = UI.CreatePage()
MainPage.Interactable = false
CracktroFrame.InputEnded:Connect(function(input)
	if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
		if _totalrendertime < 1 or not IsUhhhhhhFullyLoaded then return end
		if Util.FX.TriangleDown or os.clock() - (Util.FX.TriangleLast or 0) < 0.3 then return end -- that press was on the triangle
		CracktroFrame.Interactable = false
		CracktroFrame.Visible = true
		MainPage.Interactable = false
		local tween = TweenService:Create(CracktroFrame, TweenInfo.new(0.5, Enum.EasingStyle.Cubic, Enum.EasingDirection.Out), {
			Position = UDim2.new(0.5, -362, 0.5, 0),
		})
		tween:Play()
		tween.Completed:Connect(function()
			CracktroFrame.Visible = false
			MainPage.Interactable = true
		end)
	end
end)
do -- [V16] SEARCH EVERYTHING + SAVED SEARCHES (very top of the main page)
	-- V15 only found ON/OFF switches. V16 indexes every control the UI builds (switches, buttons, dropdowns, sliders,
	-- text boxes) plus the Movesets / Dances / Dance Keybinds / Marketplace / My Modules lists and every Script Hub
	-- button, and lets you use them straight from the results:
	--   switch   tap = flip it            button  tap = press it (hold = nothing)
	--   dropdown tap = next, hold = previous option
	--   slider / text box: a box appears in the result, type a value and press enter
	--   moveset  tap = use it, hold = open its settings      dance  tap = play / stop, hold = open its settings
	-- Searches you actually use are saved in SaveData.SearchHistory (tree.ehehetilde) and are listed when the box is focused
	-- and empty: tap = search again, hold = remove it. Risky buttons (reset / delete / kill / hop / run all ...) ask for a
	-- second tap. Result rows are created on demand and reused, and typing is debounced, so it stays light on weak devices.
	local built, buildErr = pcall(function()
		local S = {
			Entries = {},
			Items = setmetatable({}, {__mode = "k"}),
			Headers = setmetatable({}, {__mode = "k"}),
			Titles = setmetatable({}, {__mode = "k"}),
			LastText = setmetatable({}, {__mode = "k"}),
			Pools = {switch = {}, action = {}, input = {}},
			PageSize = 8,
			Limit = 8,
			MaxShown = 56,
			HistoryMax = 15,
			HistoryShow = 7,
			Risky = {"clear all", "delete", "reset", "kill all", "server hop", "rejoin", "run all", "respawn", "buy module", "redownload", "reload"},
		}
		Util.Search = S
		S.Titles[MainPage] = "Main"

		local function plain(t)
			t = tostring(t == nil and "" or t)
			t = t:gsub("<[^>]*>", "")
			t = t:gsub("&lt;", "<")
			t = t:gsub("&gt;", ">")
			t = t:gsub("&amp;", "&")
			t = t:gsub("%s+", " ")
			t = t:gsub("^ ", "")
			t = t:gsub(" $", "")
			return t
		end
		local function esc(t)
			t = tostring(t == nil and "" or t)
			t = t:gsub("&", "&amp;")
			t = t:gsub("<", "&lt;")
			t = t:gsub(">", "&gt;")
			return t
		end
		local function trim(t)
			t = tostring(t == nil and "" or t)
			t = t:gsub("^%s+", "")
			t = t:gsub("%s+$", "")
			return t
		end
		local function fmt(n)
			if type(n) ~= "number" then return tostring(n) end
			local s = string.format("%.3f", n)
			s = s:gsub("0+$", "")
			s = s:gsub("%.$", "")
			return s
		end
		local function safe(fn, ...)
			local ok, v = pcall(fn, ...)
			if ok then return v end
			return nil
		end

		-- ============================== saved searches ==============================
		local function H()
			local h = SaveData.SearchHistory
			if type(h) ~= "table" then
				h = {}
				SaveData.SearchHistory = h
			end
			return h
		end
		do -- clean whatever an older / hand edited save file contained
			local raw = H()
			local clean, seen = {}, {}
			for _, v in ipairs(raw) do
				if type(v) == "string" then
					local s = trim(v)
					local key = s:lower()
					if s ~= "" and not seen[key] and #clean < S.HistoryMax then
						seen[key] = true
						clean[#clean + 1] = s
					end
				end
			end
			SaveData.SearchHistory = clean
		end
		S.Remember = function(q)
			q = trim(q)
			if #q < 2 or #q > 60 then return end
			local h = H()
			local key = q:lower()
			for i = #h, 1, -1 do
				if type(h[i]) ~= "string" or h[i]:lower() == key then
					table.remove(h, i)
				end
			end
			table.insert(h, 1, q)
			while #h > S.HistoryMax do
				table.remove(h)
			end
		end
		S.Forget = function(q)
			local h = H()
			for i = #h, 1, -1 do
				if h[i] == q then
					table.remove(h, i)
				end
			end
		end
		S.ClearHistory = function()
			table.clear(H())
		end

		-- ============================== public helpers ==============================
		-- give a page a name for the "where" line of results (Util.Search.Titles[page] = "Name")
		-- or start a new section on a page (Util.Search.Section(page, "Name"))
		S.Section = function(parent, name)
			S.Headers[parent] = name
		end
		-- attach extra behaviour to an item-list entry (used by Movesets / Dances):
		-- Group = "moveset" | "dance", Use = function, State = function -> "ACTIVE" | nil, Hint = text
		S.Hook = function(item, data)
			pcall(function()
				local e = S.Items[item]
				if e then
					for k, v in pairs(data) do
						e[k] = v
					end
				end
			end)
		end

		-- ============================== registration wrappers ==============================
		-- the originals stay untouched; result rows below are built with the originals so they never index themselves
		local origText, origSwitch, origButton = UI.CreateText, UI.CreateSwitch, UI.CreateButton
		local origDropdown, origSlider, origTextbox = UI.CreateDropdown, UI.CreateSlider, UI.CreateTextbox
		local origItem = UI.CreateItemListItem

		local function reg(e)
			pcall(function()
				S.Entries[#S.Entries + 1] = e
			end)
		end
		local function skipLabel(l)
			if l == "" then return true end
			if l:sub(1, 1) == "<" then return true end -- "< Back", "< Hurry back"
			local ll = l:lower()
			if ll:find("hurry back", 1, true) or ll:find("back to cool scene", 1, true) then return true end
			return false
		end
		local function itemTexts(item)
			local list = {}
			for _, c in ipairs(item:GetChildren()) do
				if c:IsA("Frame") then
					local tl = c:FindFirstChildWhichIsA("TextLabel")
					if tl then
						list[#list + 1] = {o = c.LayoutOrder, t = plain(tl.Text)}
					end
				end
			end
			table.sort(list, function(a, b)
				return a.o < b.o
			end)
			return list
		end

		UI.CreateText = function(parent, text, size, alignment)
			local label = origText(parent, text, size, alignment)
			pcall(function()
				local raw = tostring(text)
				local head = raw:match("^%s*<b>(.-)</b>%s*$")
				if head then
					head = plain(head)
					if head ~= "" then
						S.Headers[parent] = head
						if S.Titles[parent] == nil then
							S.Titles[parent] = head
						end
					end
				end
				S.LastText[parent] = {Label = label, Text = plain(raw)}
			end)
			return label
		end
		UI.CreateSwitch = function(parent, text, value)
			local lever, label = origSwitch(parent, text, value)
			reg({Kind = "switch", Obj = label, Parent = parent, Section = S.Headers[parent], Lever = lever,
				GetName = function() return plain(label.Text) end})
			return lever, label
		end
		UI.CreateButton = function(parent, text, size)
			local button, label = origButton(parent, text, size)
			pcall(function()
				if not skipLabel(plain(text)) then
					reg({Kind = "button", Obj = label, Parent = parent, Section = S.Headers[parent], Button = button,
						GetName = function() return plain(label.Text) end})
				end
			end)
			return button, label
		end
		UI.CreateDropdown = function(parent, text, array, value)
			local sel, label = origDropdown(parent, text, array, value)
			reg({Kind = "dropdown", Obj = label, Parent = parent, Section = S.Headers[parent], Select = sel, Options = array,
				GetName = function() return plain(label.Text) end})
			return sel, label
		end
		UI.CreateSlider = function(parent, text, value, min, max, step)
			local sel = origSlider(parent, text, value, min, max, step)
			pcall(function()
				local kids = parent:GetChildren()
				local obj
				for i = #kids, 1, -1 do
					local k = kids[i]
					if k:IsA("GuiObject") and k.LayoutOrder == #kids then
						obj = k
						break
					end
				end
				obj = obj or kids[#kids]
				reg({Kind = "input", Sub = "slider", Obj = obj, Parent = parent, Section = S.Headers[parent], Select = sel,
					Min = min or 1, Max = max or 10, Step = math.abs(step or 0),
					GetName = function() return plain(text) end})
			end)
			return sel
		end
		UI.CreateTextbox = function(parent, text, placeholder, size)
			local box = origTextbox(parent, text, placeholder, size)
			pcall(function()
				local related
				local prev = S.LastText[parent]
				if prev and prev.Label and prev.Label.Parent then
					local cont = box.Parent and box.Parent.Parent
					if cont and cont.LayoutOrder == prev.Label.Parent.LayoutOrder + 1 then
						if prev.Text ~= "" and #prev.Text <= 45 then
							related = prev.Text
						end
					end
				end
				reg({Kind = "input", Sub = "textbox", Obj = box, Parent = parent, Section = S.Headers[parent], Box = box,
					GetName = function()
						if related then return related end
						local ph = plain(box.PlaceholderText)
						if ph ~= "" then return ph end
						return "Text box"
					end,
					GetExtra = function() return plain(box.PlaceholderText) end})
			end)
			return box
		end
		UI.CreateItemListItem = function(parent)
			local item = origItem(parent)
			pcall(function()
				local cache
				local e = {Kind = "item", Obj = item, Parent = parent, Button = item,
					GetName = function()
						if cache then return cache end
						local list = itemTexts(item)
						local n = list[1] and list[1].t or ""
						n = n:gsub("%s*>%s*$", "")
						if n ~= "" then cache = n end
						return n
					end,
					GetDesc = function()
						local list = itemTexts(item)
						return list[2] and list[2].t or ""
					end,
					GetExtra = function()
						local n = item.Parent and item.Parent.Name or ""
						local own = cache or ""
						if own ~= "" and #n < 1500 and n:lower():find(own:lower(), 1, true) then
							return n
						end
						local list = itemTexts(item)
						return list[2] and list[2].t or ""
					end}
				S.Items[item] = e
				reg(e)
			end)
			return item
		end

		-- ============================== lookup ==============================
		local function alive(e)
			local ok, res = pcall(function()
				return e.Obj:IsDescendantOf(UIMainFrame)
			end)
			return ok and res == true
		end
		local function whereOf(e)
			local page
			local p = e.Parent
			local guard = 0
			while p ~= nil and p ~= UIMainFrame and guard < 40 do
				local t = S.Titles[p]
				if t then
					page = t -- keep walking up: the outermost titled frame is the page itself
				end
				p = p.Parent
				guard += 1
			end
			local sec = e.Section
			if page and sec and sec ~= page then
				return page .. " > " .. sec
			end
			return sec or page or "Settings"
		end
		local function kindWord(e)
			if e.Kind == "switch" then return "switch toggle" end
			if e.Kind == "button" then return "button" end
			if e.Kind == "dropdown" then return "dropdown option" end
			if e.Kind == "input" then
				return e.Sub == "slider" and "slider" or "textbox input"
			end
			if e.Group == "moveset" then return "moveset" end
			if e.Group == "dance" then return "dance" end
			return "item"
		end
		local function isRisky(e)
			if e.Kind ~= "button" then return false end
			local l = (safe(e.GetName) or ""):lower()
			for _, w in ipairs(S.Risky) do
				if l:find(w, 1, true) then return true end
			end
			return false
		end
		local function find(query)
			local q = query:lower()
			local words = {}
			for w in q:gmatch("%S+") do
				words[#words + 1] = w
			end
			local live, out = {}, {}
			for idx, e in ipairs(S.Entries) do
				if alive(e) then
					live[#live + 1] = e
					local okN, label = pcall(e.GetName)
					if okN and type(label) == "string" and label ~= "" then
						local where = whereOf(e)
						local extra = ""
						if e.GetExtra then
							local ex = safe(e.GetExtra)
							if type(ex) == "string" then
								extra = ex:sub(1, 600)
							end
						end
						local hay = (label .. " " .. where .. " " .. kindWord(e) .. " " .. extra):lower()
						local hit = true
						for _, w in ipairs(words) do
							if not hay:find(w, 1, true) then
								hit = false
								break
							end
						end
						if hit then
							local ll = label:lower()
							local score = 3
							if ll:sub(1, #q) == q then
								score = 1
							elseif ll:find(q, 1, true) then
								score = 2
							end
							out[#out + 1] = {Entry = e, Label = label, Score = score, Idx = idx}
						end
					end
				end
			end
			if #S.Entries - #live > 40 then
				S.Entries = live -- drop controls whose page was rebuilt / destroyed
			end
			table.sort(out, function(a, b)
				if a.Score ~= b.Score then
					return a.Score < b.Score
				end
				local la, lb = a.Label:lower(), b.Label:lower()
				if la ~= lb then
					return la < lb
				end
				return a.Idx < b.Idx
			end)
			return out
		end

		-- ============================== actions ==============================
		local function trigger(signal, ...)
			local args = table.pack(...)
			task.spawn(function()
				local fired = false
				if type(firesignal) == "function" then
					fired = pcall(firesignal, signal, table.unpack(args, 1, args.n))
				end
				if not fired and type(getconnections) == "function" then
					local ok, conns = pcall(getconnections, signal)
					if ok and type(conns) == "table" then
						for _, c in ipairs(conns) do
							local okc = pcall(function()
								c:Fire(table.unpack(args, 1, args.n))
							end)
							if okc then fired = true end
						end
					end
				end
				if not fired then
					Util.Notify("Your executor can't press buttons from the search (needs firesignal or getconnections).")
				end
			end)
		end
		local function applyInput(e, txt)
			if e.Sub == "slider" then
				local n = tonumber(txt)
				if not n then
					Util.Notify("That is not a number.")
					return
				end
				if e.Step and e.Step > 0 then
					n = e.Min + math.round((n - e.Min) / e.Step) * e.Step
				end
				e.Select.Value = math.clamp(n, e.Min, e.Max)
			else
				e.Box.Text = txt
				trigger(e.Box.FocusLost, true)
			end
		end

		-- ============================== UI: search box + results ==============================
		local SearchBox = origTextbox(MainPage, "", "Search everything... (fly, dance, hub)", 15)
		local Results = Util.Instance("Frame", MainPage)
		Results.AnchorPoint = Vector2.new(0.5, 0)
		Results.Size = UDim2.new(1, 0, 0, 0)
		Results.AutomaticSize = Enum.AutomaticSize.Y
		Results.BackgroundTransparency = 1
		Results.LayoutOrder = #MainPage:GetChildren()
		Results.Visible = false
		local ResultsList = Util.Instance("UIListLayout", Results)
		ResultsList.FillDirection = Enum.FillDirection.Vertical
		ResultsList.HorizontalAlignment = Enum.HorizontalAlignment.Center
		ResultsList.VerticalAlignment = Enum.VerticalAlignment.Top
		ResultsList.Padding = UDim.new(0, 0)
		ResultsList.SortOrder = Enum.SortOrder.LayoutOrder

		local Status = origText(Results, "", 11, Enum.TextXAlignment.Center)
		local StatusBox = Status.Parent
		StatusBox.Visible = false
		local before = {}
		for _, c in ipairs(Results:GetChildren()) do
			before[c] = true
		end
		UI.CreateSeparator(Results)
		for _, c in ipairs(Results:GetChildren()) do
			if not before[c] and c:IsA("Frame") then
				c.LayoutOrder = 100000
			end
		end

		local refresh, render, runEntry
		local historyOpen = false

		local function newSwitchRow()
			local lever, label = origSwitch(Results, "", false)
			local button = label.Parent
			local row = {Type = "switch", Lever = lever, Label = label, Container = button.Parent, Conns = {}}
			row.Container.Visible = false
			button.Activated:Connect(function()
				local e = row.Target
				if e and e.Lever then
					S.Remember(SearchBox.Text)
					e.Lever.Value = not e.Lever.Value -- the real switch's own handlers do the rest
				end
			end)
			return row
		end
		local function newActionRow()
			local button, label = origButton(Results, "", 15)
			label.TextXAlignment = Enum.TextXAlignment.Left
			local pad = Util.Instance("UIPadding", label)
			pad.PaddingLeft = UDim.new(0, 6)
			pad.PaddingRight = UDim.new(0, 6)
			local row = {Type = "action", Button = button, Label = label, Container = button.Parent, Conns = {}}
			row.Container.Visible = false
			button.InputBegan:Connect(function(input)
				local t = input.UserInputType
				if t == Enum.UserInputType.MouseButton1 or t == Enum.UserInputType.Touch then
					row.PressAt = os.clock()
				end
			end)
			button.Activated:Connect(function()
				local held = row.PressAt ~= nil and (os.clock() - row.PressAt) >= 0.5
				row.PressAt = nil
				local e = row.Target
				if e then
					local ok, err = pcall(runEntry, e, held, row)
					if not ok then
						warn("[Uhhhhhh] Search action failed: " .. tostring(err))
					end
				end
			end)
			return row
		end
		local function newInputRow()
			local box = origTextbox(Results, "", "", 14)
			local row = {Type = "input", Box = box, Container = box.Parent.Parent, Conns = {}}
			row.Container.Visible = false
			box.FocusLost:Connect(function()
				local txt = trim(box.Text)
				box.Text = ""
				local e = row.Target
				if e and txt ~= "" then
					local ok, err = pcall(applyInput, e, txt)
					if not ok then
						warn("[Uhhhhhh] Search input failed: " .. tostring(err))
					end
					S.Remember(SearchBox.Text)
					pcall(render, row, e)
				end
			end)
			return row
		end
		local used = {}
		local function acquire(kind)
			local pool = S.Pools[kind]
			local n = (used[kind] or 0) + 1
			local row = pool[n]
			if not row then
				if kind == "switch" then
					row = newSwitchRow()
				elseif kind == "action" then
					row = newActionRow()
				else
					row = newInputRow()
				end
				pool[n] = row
			end
			used[kind] = n
			return row
		end
		local function fit(row)
			pcall(function()
				if row.Type == "input" then return end
				local x = Results.AbsoluteSize.X
				if x < 120 then
					x = MainPage.AbsoluteSize.X
				end
				if row.Type == "switch" then
					local sz = TextService:GetTextSize(row.Label.ContentText, row.Label.TextSize, row.Label.Font, Vector2.new(math.max(60, x - 65), math.huge))
					row.Container.Size = UDim2.new(1, 0, 0, math.max(35, sz.Y))
				else
					local sz = TextService:GetTextSize(row.Label.ContentText, row.Label.TextSize, row.Label.Font, Vector2.new(math.max(60, x - 24), math.huge))
					row.Container.Size = UDim2.new(1, 0, 0, math.max(35, sz.Y + 14))
				end
			end)
		end
		local function sub(t, warnColor)
			if warnColor then
				return "\n<font size=\"11\" color=\"" .. warnColor .. "\">" .. esc(t) .. "</font>"
			end
			return "\n<font size=\"11\" transparency=\"0.5\">" .. esc(t) .. "</font>"
		end
		local function armed(e)
			return e.ArmedUntil ~= nil and os.clock() <= e.ArmedUntil
		end
		local function actionText(e)
			local k = e.Kind
			if k == "history" then
				return esc(e.Query) .. sub("recent search  -  tap = search again, hold = remove")
			elseif k == "clear" then
				return "Clear search history" .. sub("removes every saved search")
			elseif k == "more" then
				return "Show more results" .. sub(e.Count .. " more match")
			end
			local label = safe(e.GetName) or ""
			local where = whereOf(e)
			if armed(e) then
				return esc(label) .. sub("TAP AGAIN TO CONFIRM", "#FF5555")
			end
			if k == "dropdown" then
				local cur = e.Options[e.Select.Value]
				return esc(label) .. ": <b>" .. esc(tostring(cur)) .. "</b>" .. sub(where .. "  -  tap = next, hold = previous")
			end
			local state = e.State and safe(e.State)
			local head = esc(label)
			if state then
				head = head .. "  <b>[" .. esc(state) .. "]</b>"
			end
			local hint
			if k == "button" then
				hint = "tap to run"
			elseif e.Use then
				hint = e.Hint or "tap = use, hold = open"
			else
				hint = "tap to open"
			end
			return head .. sub(where .. "  -  " .. hint)
		end
		local function inputPlaceholder(e)
			local label = safe(e.GetName) or ""
			local where = whereOf(e)
			if e.Sub == "slider" then
				return "Set " .. label .. " = " .. fmt(e.Select.Value) .. "  (" .. fmt(e.Min) .. " to " .. fmt(e.Max) .. ")  -  " .. where
			end
			local cur = e.Box.Text or ""
			if #cur > 24 then
				cur = cur:sub(1, 24) .. "..."
			end
			return "Set " .. label .. (cur ~= "" and (" = " .. cur) or "") .. "  -  " .. where
		end
		render = function(row, e)
			if row.Type == "switch" then
				row.Lever.Value = e.Lever.Value
				row.Label.Text = esc(safe(e.GetName) or "") .. sub(whereOf(e))
			elseif row.Type == "action" then
				row.Label.Text = actionText(e)
			else
				row.Box.PlaceholderText = inputPlaceholder(e)
			end
			fit(row)
		end

		runEntry = function(e, alt, row)
			local k = e.Kind
			if k == "history" then
				if alt then
					S.Forget(e.Query)
					refresh()
				else
					SearchBox.Text = e.Query -- the text-changed signal runs the search
				end
				return
			elseif k == "clear" then
				S.ClearHistory()
				refresh()
				return
			elseif k == "more" then
				S.Limit = math.min(S.Limit + S.PageSize, S.MaxShown)
				refresh()
				return
			end
			if isRisky(e) and not armed(e) then
				e.ArmedUntil = os.clock() + 3
				render(row, e)
				task.delay(3.1, function()
					if row.Target == e then
						pcall(render, row, e)
					end
				end)
				return
			end
			e.ArmedUntil = nil
			S.Remember(SearchBox.Text)
			if k == "dropdown" then
				local n = #e.Options
				if n > 0 then
					local dir = alt and -1 or 1
					e.Select.Value = ((e.Select.Value - 1 + dir) % n) + 1
				end
			elseif k == "button" then
				trigger(e.Button.Activated)
			elseif k == "item" then
				if e.Use and not alt then
					e.Use()
				else
					trigger(e.Button.Activated)
				end
			end
			render(row, e)
		end

		local function resetRows()
			for _, pool in pairs(S.Pools) do
				for _, r in ipairs(pool) do
					for _, c in ipairs(r.Conns) do
						c:Disconnect()
					end
					table.clear(r.Conns)
					r.Target = nil
					r.Container.Visible = false
				end
			end
			table.clear(used)
			StatusBox.Visible = false
		end
		local function place(entry, order)
			local kind = "action"
			if entry.Kind == "switch" then
				kind = "switch"
			elseif entry.Kind == "input" then
				kind = "input"
			end
			local okR, row = pcall(acquire, kind)
			if not okR or not row then
				warn("[Uhhhhhh] Search row failed: " .. tostring(row))
				return nil
			end
			row.Target = entry
			row.Container.LayoutOrder = order
			row.Container.Visible = true
			if kind == "switch" then
				table.insert(row.Conns, entry.Lever.Changed:Connect(function(v)
					row.Lever.Value = v -- keep the row in sync if the switch is flipped somewhere else
				end))
			end
			local okD, err = pcall(render, row, entry)
			if not okD then
				warn("[Uhhhhhh] Search render failed: " .. tostring(err))
			end
			return row
		end

		refresh = function()
			resetRows()
			local query = trim(SearchBox.Text)
			local placed = {}
			if query == "" then
				local h = H()
				if #h == 0 or not (historyOpen or SearchBox:IsFocused()) then
					Results.Visible = false
					return
				end
				Results.Visible = true
				Status.Text = "Recent searches"
				StatusBox.LayoutOrder = 0
				StatusBox.Visible = true
				for i = 1, math.min(#h, S.HistoryShow) do
					local r = place({Kind = "history", Query = h[i]}, i)
					if r then placed[#placed + 1] = r end
				end
				local r = place({Kind = "clear"}, S.HistoryShow + 1)
				if r then placed[#placed + 1] = r end
			else
				Results.Visible = true
				local found = find(query)
				local shown = math.min(#found, S.Limit)
				for i = 1, shown do
					local r = place(found[i].Entry, i)
					if r then placed[#placed + 1] = r end
				end
				if shown == 0 then
					Status.Text = "No matching options. Try another word."
					StatusBox.LayoutOrder = 90000
					StatusBox.Visible = true
				elseif #found > shown then
					local r = place({Kind = "more", Count = #found - shown}, shown + 1)
					if r then placed[#placed + 1] = r end
				end
			end
			task.delay(0.06, function()
				for _, r in ipairs(placed) do
					fit(r) -- measure again once the layout has settled
				end
			end)
		end
		S.Refresh = refresh

		SearchBox.Focused:Connect(function()
			historyOpen = true
			pcall(refresh) -- show saved searches / pick up pages that were rebuilt while the same words were in the box
		end)
		SearchBox.FocusLost:Connect(function(enterPressed)
			local q = trim(SearchBox.Text)
			if enterPressed and q ~= "" then
				local ok, found = pcall(find, q)
				if ok and #found > 0 then
					S.Remember(q)
				end
			end
			task.delay(1.2, function()
				if trim(SearchBox.Text) == "" and not SearchBox:IsFocused() then
					historyOpen = false
					pcall(refresh) -- hides the saved searches again
				end
			end)
		end)
		local token = 0
		SearchBox:GetPropertyChangedSignal("Text"):Connect(function()
			token += 1
			local mine = token
			S.Limit = S.PageSize
			task.delay(0.12, function()
				if mine == token then
					local ok, err = pcall(refresh)
					if not ok then
						warn("[Uhhhhhh] Feature search failed: " .. tostring(err))
					end
				end
			end)
		end)
	end)
	if not built then
		warn("[Uhhhhhh] Search bar failed to build: " .. tostring(buildErr))
	end
end
