do -- [custom] CUSTOMIZATION PAGE: 10 triangle + 10 intro + 10 notification + 5 extra UI options
	local FX = Util.FX
	local CPage = UI.CreatePage()
	CPage.ZIndex = 1
	CPage.Position = UDim2.new(0.5, 360, 0.5, 0)
	CPage.Interactable = false
	CPage.Visible = false
	UI.CreateButton(MainPage, "Customization &gt;", 20).Activated:Connect(function()
		CPage.Interactable = false
		CPage.Visible = true
		MainPage.Interactable = false
		local tween = TweenService:Create(CPage, TweenInfo.new(0.5, Enum.EasingStyle.Cubic, Enum.EasingDirection.In), {
			Position = UDim2.new(0.5, 0, 0.5, 0),
		})
		tween:Play()
		tween.Completed:Connect(function()
			CPage.Interactable = true
		end)
	end)
	UI.CreateButton(CPage, "&lt; Back", 20).Activated:Connect(function()
		CPage.Interactable = false
		MainPage.Interactable = false
		local tween = TweenService:Create(CPage, TweenInfo.new(0.5, Enum.EasingStyle.Cubic, Enum.EasingDirection.Out), {
			Position = UDim2.new(0.5, 360, 0.5, 0),
		})
		tween:Play()
		tween.Completed:Connect(function()
			MainPage.Interactable = true
			CPage.Visible = false
		end)
	end)
	UI.CreateText(CPage, "<b>CUSTOMIZATION</b>", 15, Enum.TextXAlignment.Center)
	UI.CreateText(CPage, "Everything here is saved and applies instantly. Triangle changes show on the cool scene (home) and the loading screen. Intro changes show on the next start, or press Preview Intro.", 10, Enum.TextXAlignment.Center)
	local Canvas = UI.CreateCanvas(CPage)
	local previewing = false

	local function build()
		local function section(title)
			UI.CreateSeparator(Canvas)
			UI.CreateText(Canvas, "<b>" .. title .. "</b>", 14, Enum.TextXAlignment.Center)
		end
		local function sw(label, key)
			UI.CreateSwitch(Canvas, label, FX.Cfg[key]).Changed:Connect(function(val)
				FX.SetCfg(key, val)
			end)
		end
		local function sl(label, key, min, max, step)
			UI.CreateSlider(Canvas, label, FX.Cfg[key], min, max, step).Changed:Connect(function(val)
				FX.SetCfg(key, math.clamp(val, min, max))
			end)
		end
		local function dd(label, key, list)
			UI.CreateDropdown(Canvas, label, list, FX.Cfg[key]).Changed:Connect(function(val)
				FX.SetCfg(key, val)
			end)
		end
		-- kind: nil = plain text, "hex" = required #RRGGBB, "hexopt" = optional #RRGGBB (empty = follow the theme)
		local function tb(label, key, placeholder, maxlen, kind)
			UI.CreateText(Canvas, label, 11, Enum.TextXAlignment.Left)
			local box = UI.CreateTextbox(Canvas, tostring(FX.Cfg[key]), placeholder, 18)
			box.FocusLost:Connect(function()
				local s = (box.Text:gsub("[^\32-\126]", "")):sub(1, maxlen or 40)
				if kind then
					if s == "" and kind == "hexopt" then
						-- empty = follow the UI theme
					elseif not Util.ParseHex(s) then
						box.Text = tostring(FX.Cfg[key])
						Util.UINotify("Invalid color, use hex like #FF8800")
						return
					elseif s:sub(1, 1) ~= "#" then
						s = "#" .. s
					end
				end
				box.Text = s
				FX.SetCfg(key, s)
			end)
		end

		-- ═════ TRIANGLE (10) ═════
		section("TRIANGLE")
		dd("Triangle Color Mode", "TriColorMode", {"Theme (follows UI color)", "Custom color", "Rainbow"})
		tb("Triangle custom color (hex, used by Custom color)", "TriColor", "#FFFFFF", 7, "hex")
		sl("Triangle Size", "TriSize", 0.5, 1.5, 0.05)
		sl("Triangle Spin Speed", "TriSpin", 0, 3, 0.1)
		sl("Face Transparency", "TriFaceTr", 0, 1, 0.02)
		sl("Edge Thickness", "TriEdge", 0.5, 3, 0.1)
		sw("Show Vertex Orbs", "TriNodes")
		sw("Show Faces (off = wireframe)", "TriFaces")
		sw("React To Music", "TriMusic")
		sw("Hold 5s To Explode", "TriExplode")

		-- ═════ INTRO (10) ═════
		section("INTRO")
		tb("Intro title text (max 20 characters)", "IntroTitle", "STEVETHEREALONE", 20)
		tb("Intro subtitle (empty = default)", "IntroSub", "default subtitle", 80)
		tb("Intro scrolling text (empty = random)", "IntroMarquee", "random", 80)
		dd("Intro Color", "IntroColorMode", {"Rainbow", "Custom color", "White"})
		tb("Intro custom color (hex, used by Custom color)", "IntroColor", "#FFFFFF", 7, "hex")
		sw("Warp Starfield", "IntroStars")
		sw("God Rays", "IntroRays")
		sw("Scanline + Letterbox Bars", "IntroScan")
		sw("HUD Brackets + Counter", "IntroHud")
		sl("Effects Intensity (shake / flash)", "IntroIntensity", 0, 2, 0.1)
		UI.CreateButton(Canvas, "Preview Intro", 20).Activated:Connect(function()
			if previewing then return end
			previewing = true
			task.spawn(function()
				local ok, err = pcall(FX.Intro, UIMainFrame, {TimePosition = 0}, FX.MarqueeText("this is your intro preview                    "))
				if not ok then
					warn("[Customization] intro preview failed: " .. tostring(err))
				end
				previewing = false
			end)
		end)

		-- ═════ NOTIFICATIONS (10) ═════
		section("NOTIFICATIONS")
		dd("Notification Mode", "NotifMode", {
			"Default (Roblox popup + UI bar)",
			"Everything in the UI bar",
			"Everything as Roblox popup",
			"Silent",
		})
		sl("Duration (seconds)", "NotifDuration", 1, 15, 1)
		tb("Roblox popup title", "NotifTitle", "Nooby's Uh Modded Reanimation", 40)
		dd("UI bar position", "NotifPos", {"Below window", "Above window", "Top of screen", "Bottom of screen"})
		sl("UI bar width", "NotifWidth", 200, 600, 10)
		sl("UI bar text size", "NotifSize", 12, 26, 1)
		sw("Show progress bar", "NotifProgress")
		tb("UI bar color (hex, empty = follow theme)", "NotifColor", "theme", 7, "hexopt")
		sw("Play sound on notification", "NotifSound")
		sl("Slide animation speed", "NotifSpeed", 0.5, 3, 0.1)
		UI.CreateButton(Canvas, "Test Notification", 20).Activated:Connect(function()
			Util.UINotify("This is a test notification")
			Util.Notify("This is a test notification")
		end)

		-- ═════ EXTRA UI (5) ═════
		section("EXTRA UI")
		sl("Background Transparency", "UIBgTr", 0, 0.8, 0.05)
		sl("Border Thickness", "UIBorder", 0.5, 4, 0.5)
		sl("Corner Roundness", "UIRound", 0, 16, 1)
		sw("Glow Effect", "UIGlow")
		tb("Accent color override (hex, empty = follow theme)", "UIAccent", "theme", 7, "hexopt")

		-- ═════ COMMAND TRIANGLE ═════
		section("COMMAND TRIANGLE")
		sw("Hide Command Triangle", "AdminTriHidden")
		sw("Restore tab while hidden", "AdminTriTab")
		UI.CreateButton(Canvas, "Reset Triangle Position", 20).Activated:Connect(function()
			FX.SetCfg("AdminTriPos", "")
			if Util.UhAdmin and Util.UhAdmin.ResetTriPos then Util.UhAdmin.ResetTriPos() end
			Util.UINotify("Triangle moved back to the top centre")
		end)
		UI.CreateText(Canvas, "Drag the triangle anywhere (mouse or finger). Hold it for a moment to hide it. A small tab stays at the top edge: tap it to bring the triangle back (or type showtri / flip the switch above). The command bar also opens with the prefix key.", 10, Enum.TextXAlignment.Center)
	end
	build()
	UI.CreateButton(CPage, "Reset All Customization", 20).Activated:Connect(function()
		FX.ResetCfg()
		Util.ClearAllChildrenGui(Canvas)
		build()
		Util.UINotify("Customization reset to default")
	end)
end
