	SeatSit = not SaveData.NoSeatSitEnabled,
	ToolGrab = SaveData.ToolGrabEnabled,
	ScaleGravity = SaveData.ScaleGravityEnabled,
	PatchmaVoidFloat = SaveData.PatchmaVoidFloat,
	AntiExplosions = true,
