	Debris:AddItem(w, 1)
end

local RIGHTGRIP_C0 = CFrame.new(0, -1, 0, 1, 0, 0, 0, 0, 1, 0, -1, 0)
Util.PredictionFling = function(target)
	if typeof(target) == "Instance" then
		if target:IsA("Model") then
			target = target:FindFirstChild("HumanoidRootPart") or target.PrimaryPart or target:FindFirstChildWhichIsA("BasePart")
		end
		if target and target:IsA("BasePart") then
			if not target:IsDescendantOf(workspace) then
				return CFrame.identity, true
			end
			local t = os.clock()
			local t2 = math.sin(t * 15) + 1
			local cf = target.CFrame * CFrame.Angles(1.57, 0, 0)
			if not Util.Fling.UseGlue() then
				cf += target.AssemblyLinearVelocity * t2 + Vector3.new(0, -workspace.Gravity * 0.5 * t2 * t2 + math.sin(t * 60), 0)
				if cf.Position.Y < target.Position.Y - 1 then
					cf = cf.Rotation + Vector3.new(cf.Position.X, target.Position.Y - 1, cf.Position.Z)
				end
			end
			--cf += Vector3.new(0, -0.5, 0)
			local oldpos = target:GetAttribute("_Uhhhhhh_LastPosition")
			if not oldpos then
				oldpos = target.Position
				target:SetAttribute("_Uhhhhhh_LastPosition", oldpos)
			end
			if (target.Position - oldpos).Magnitude > 200 then
				target:SetAttribute("_Uhhhhhh_LastPosition", nil)
				return cf, true
			end
			return cf, false
		end
	end
	if typeof(target) == "CFrame" then
		return target, false
	end
	if typeof(target) == "Vector3" then
		return CFrame.new(target), false
	end
	return CFrame.identity, true
end
Util.PredictionFlingPart = function(target)
	if typeof(target) == "Instance" then
		if target:IsA("Model") then
			target = target:FindFirstChild("HumanoidRootPart") or target.PrimaryPart or target:FindFirstChildWhichIsA("BasePart")
		end
		if target and target:IsA("BasePart") then
			return target
		end
	end
end

-- [nooby mod] FLING METHODS ---------------------------------------------------
-- 1 = Default Fling, 2 = Weak Fling, 3 = Nooby's Method, 4 = NaN State Fling
Util.Fling = {}
Util.Fling.Names = {
	"Default Fling",
	"Weak Fling (just trips them)",
	"Nooby's Method (clip + nullzone)",
	"NaN State Fling",
	"Fling 1 (Nameless / Source)",
	"Fling 2 (Carpet)",
	"Fling 3 (Hidden / Flight)",
}
Util.Fling.Descriptions = {
	"default fling: spins into the target at crazy velocity and sends them flying",
	"weak fling: only trips people over, doesn't send them to the void",
	"nooby's method: clips inside their HumanoidRootPart, flings them to the nullzone and stays attached until they die",
	"NaN state fling: sticks to their root with a NaN humanoid state, falls back to a velocity fling if they only get pushed",
	"Fling 1: adapted from Nameless Admin's classic high-velocity multi-position fling sequence",
	"Fling 2: adapted from the carpet-animation target-following fling sequence",
	"Fling 3: adapted from the hidden-fling target sweep + flight sequence",
}
Util.Fling.WeakDuration = 0.4        -- how long a weak fling lasts (seconds)
Util.Fling.NaNWindow = 0.6           -- seconds to wait for the NaN state to work before escalating
Util.Fling.NaNEscalateDistance = 60  -- target moved less than this = it only got pushed
Util.Fling.NoobyMaxTime = 15         -- safety cap for nooby's method (god-mode targets can't die)
-- GitHub/legacy fling variants are kept inside the shared method engine so the
-- external Uh Admin exposes walkfling only; these three are dropdown methods.
Util.Fling.SourceFling1Duration = 2.0
Util.Fling.SourceFling2Duration = 0.9
Util.Fling.SourceFling3Duration = 1.35
do
	local saved = SaveData.FlingMethod
	if type(saved) ~= "number" then
		saved = (SaveData.Reanimator and SaveData.Reanimator.LimbUseNaNFling) and 4 or 1
	end
	Util.Fling.Method = math.clamp(math.floor(saved), 1, #Util.Fling.Names)
end
Util.Fling.SetMethod = function(m)
	m = math.clamp(math.floor(tonumber(m) or 1), 1, #Util.Fling.Names)
	Util.Fling.Method = m
	SaveData.FlingMethod = m
	SaveData.Reanimator = SaveData.Reanimator or {}
	SaveData.Reanimator.LimbUseNaNFling = (m == 4) -- keeps old saves in sync
	Util.Notify("Fling method: " .. Util.Fling.Names[m])
end
Util.Fling.GetPart = function(target)
	if typeof(target) == "Instance" then
		if target:IsA("Model") then
			local hum = target:FindFirstChildOfClass("Humanoid")
			target = (hum and hum.RootPart) or target:FindFirstChild("HumanoidRootPart") or target.PrimaryPart or target:FindFirstChildWhichIsA("BasePart")
		end
		if target and target:IsA("BasePart") then
			return target
		end
	end
	return nil
end
Util.Fling.TargetAlive = function(target)
	if typeof(target) ~= "Instance" then return true end
	if not target:IsDescendantOf(workspace) then return false end
	if target:IsA("Model") then
		local hum = target:FindFirstChildOfClass("Humanoid")
		if hum and hum.Health <= 0 then return false end
	end
	local part = Util.Fling.GetPart(target)
	if not part then return false end
	local p = part.Position
	if p.X ~= p.X or p.Y ~= p.Y or p.Z ~= p.Z then return false end
	if p.Y < FallenPartsDestroyHeight - 100 then return false end
	return true
end
-- [fling debug] set to false to silence the "fling start" diagnostics
Util.Fling.Debug = true
-- "Use Physics Glue" needs sethiddenproperty(part, "PhysicsRepRootPart", ...) to work. If the executor
-- can't set it, glue-mode flings (0.1-0.5s, no velocity prediction) just miss, so fall back to the
-- prediction fling instead.
Util.Fling.GlueState = nil -- nil = not probed yet
Util.Fling.UseGlue = function()
	if not Reanimate.UsePhysicsRepRootPart then return false end
	if Util.Fling.GlueState == nil then
		local root = Player.Character and Player.Character:FindFirstChild("HumanoidRootPart")
		if not root then return true end -- nothing to probe with yet, don't cache
		local ok = pcall(sethiddenproperty, root, "PhysicsRepRootPart", root)
		pcall(sethiddenproperty, root, "PhysicsRepRootPart", nil)
		Util.Fling.GlueState = ok and true or false
		if not ok then
			Util.Notify("Physics Glue isn't supported by your executor, using prediction fling instead")
		end
	end
	return Util.Fling.GlueState
end
Util.Fling.ReportStart = function(ft)
	if not Util.Fling.Debug then return end
	task.spawn(function()
		pcall(function()
			local root = Player.Character and Player.Character:FindFirstChild("HumanoidRootPart")
			local owned = root and root.ReceiveAge == 0
			Util.Notify(string.format(
				"fling start: method=%s glue=%s rootOwned=%s",
				tostring(ft.Mode), tostring(Util.Fling.UseGlue()), tostring(owned)
			))
		end)
	end)
end
-- Picks the queue's first target and works out where to put the RootPart.
-- returns: target entry (or nil when finished), CFrame, "target was flung away"
Util.Fling.Step = function(queue, t, defaultduration)
	local ft = queue[1]
	if not ft then return nil, CFrame.identity, false end
	local isinstance = typeof(ft.Target) == "Instance"
	local part = Util.Fling.GetPart(ft.Target)
	if not ft.Time then
		ft.Mode = Util.Fling.Method
		ft.Start = t
		ft.StartPos = part and part.Position or nil
		local dur = ft.Duration
		if not dur then
			if ft.Mode == 2 then
				dur = Util.Fling.WeakDuration
			elseif ft.Mode == 3 and isinstance then
				dur = Util.Fling.NoobyMaxTime
			elseif ft.Mode == 4 then
				dur = math.max(defaultduration, Util.Fling.NaNWindow + 1)
			elseif ft.Mode == 5 then
				dur = Util.Fling.SourceFling1Duration
			elseif ft.Mode == 6 then
				dur = math.max(defaultduration, Util.Fling.SourceFling2Duration)
			elseif ft.Mode == 7 then
				dur = Util.Fling.SourceFling3Duration
			else
				dur = defaultduration
			end
		end
		ft.Time = t + dur
		Util.Fling.ReportStart(ft)
	elseif t > ft.Time then
		table.remove(queue, 1)
		return nil, CFrame.identity, false
	end
	if isinstance then
		if not part or not part:IsDescendantOf(workspace) then
			table.remove(queue, 1)
			return nil, CFrame.identity, false
		end
		local p = part.Position
		if p.X ~= p.X or p.Y ~= p.Y or p.Z ~= p.Z then -- target got NaN'd: it's gone, don't follow it (would NaN our own RootPart)
			table.remove(queue, 1)
			return nil, CFrame.identity, true
		end
		if ft.Mode == 3 and not Util.Fling.TargetAlive(ft.Target) then -- nooby's method: until they die
			table.remove(queue, 1)
			return nil, CFrame.identity, true
		end
		-- NaN state fling only pushed them? escalate to a velocity fling so they actually fly
		if ft.Mode == 4 and not ft.Escalated and t - ft.Start > Util.Fling.NaNWindow then
			local moved = ft.StartPos and (p - ft.StartPos).Magnitude or math.huge
			if moved < Util.Fling.NaNEscalateDistance then
				ft.Escalated = true
				ft.Mode = 1
				ft.Time = math.max(ft.Time, t + 1)
			end
		end
	end
	local flingcf, flinged
	if isinstance and (ft.Mode == 2 or ft.Mode == 3 or ft.Mode == 4 or ft.Mode == 5 or ft.Mode == 6 or ft.Mode == 7) then
		-- Modes 2-7 deliberately use the target's current replicated position. This avoids
		-- feeding a stale prediction into the source-style sequences and keeps NaN-safe modes
		-- isolated from the player's own RootPart.
		if ft.Mode == 2 then
			flingcf = CFrame.new(part.Position + Vector3.new(0, -2, 0))
		elseif ft.Mode == 6 then
			local speed = part.AssemblyLinearVelocity.Magnitude
			if speed <= 28 then
				flingcf = CFrame.new(part.Position + part.AssemblyLinearVelocity * 0.5)
			else
				flingcf = part.CFrame
			end
		elseif ft.Mode == 5 then
			local hum = ft.Target:IsA("Model") and ft.Target:FindFirstChildOfClass("Humanoid") or nil
			local moveDir = hum and hum.MoveDirection or Vector3.zero
			local speed = part.AssemblyLinearVelocity.Magnitude
			local elapsed = math.max(0, t - ft.Start)
			local interval = 0.075
			local lowSpeedOffsets = {
				Vector3.new(0, 1.5, 0),
				Vector3.new(0, -1.5, 0),
				Vector3.new(2.25, 1.5, -2.25),
				Vector3.new(-2.25, -1.5, 2.25),
				Vector3.new(0, 1.5, 0),
				Vector3.new(0, -1.5, 0),
			}
			local highSpeedOffsets = {
				Vector3.new(0, 1.5, hum and hum.WalkSpeed or 16),
				Vector3.new(0, -1.5, -(hum and hum.WalkSpeed or 16)),
				Vector3.new(0, 1.5, hum and hum.WalkSpeed or 16),
				Vector3.new(0, 1.5, speed / 1.25),
				Vector3.new(0, -1.5, -speed / 1.25),
				Vector3.new(0, 1.5, speed / 1.25),
				Vector3.new(0, -1.5, 0),
				Vector3.new(0, -1.5, 0),
				Vector3.new(0, -1.5, 0),
				Vector3.new(0, -1.5, 0),
			}
			local offsets = speed < 50 and lowSpeedOffsets or highSpeedOffsets
			local index = (math.floor(elapsed / interval) % #offsets) + 1
			local extra = moveDir * math.min(speed, 100) / 1.25
			local offset = offsets[index] + extra
			local angle = math.rad(math.floor(elapsed / interval) * 100)
			flingcf = CFrame.new(part.Position + offset) * CFrame.Angles(angle, 0, 0)
		elseif ft.Mode == 7 then
			local offsets = {
				Vector3.new(0, 0, 4),
				Vector3.new(0, 0, -2),
				Vector3.new(0, 0, 0),
				Vector3.new(0, 0, -3),
				Vector3.new(0, 0, 2),
				Vector3.new(0, 0, 0),
				Vector3.new(0, 0, -1),
				Vector3.new(0, 0, -1),
			}
			local interval = 0.04
			local elapsed = math.max(0, t - ft.Start)
			local index = (math.floor(elapsed / interval) % #offsets) + 1
			flingcf = part.CFrame * CFrame.new(offsets[index])
		else
			flingcf = part.CFrame
		end
		flinged = false
	else
		flingcf, flinged = Util.PredictionFling(ft.Target)
	end
	if flinged then
		table.remove(queue, 1)
		return nil, CFrame.identity, true
	end
	return ft, flingcf, false
end
Util.Fling.ApplyRoot = function(RootPart, ft, flingcf)
	local mode = ft.Mode or 1
	local t = os.clock()
	local jitter = Vector3.new(0, 0, math.random(0, 1) * 0.005)
	if mode == 4 then
		-- NaN state fling: stay inside their root, velocity stays clean, the NaN comes from the humanoid state
		RootPart.CFrame = CFrame.new(flingcf.Position + jitter) * CFrame.Angles(0, t * 15, 0)
		RootPart.Velocity, RootPart.RotVelocity = Vector3.zero, Vector3.zero
	elseif mode == 2 then
		-- weak fling: low speed shove at leg height, enough to trip, not enough to launch
		RootPart.CFrame = CFrame.new(flingcf.Position + jitter) * CFrame.Angles(0, t * 10, 0)
		RootPart.Velocity = Vector3.new(math.sin(t * 25) * 22, 0, math.cos(t * 25) * 22)
		RootPart.RotVelocity = Vector3.new(0, 30, 0)
	elseif mode == 3 and typeof(ft.Target) == "Instance" then
		-- nooby's method: clipped inside their HumanoidRootPart, re-attached every frame while they fall
		RootPart.CFrame = CFrame.new(flingcf.Position + jitter) * CFrame.Angles(t * 31, t * 47, 0)
		RootPart.Velocity, RootPart.RotVelocity = Vector3.new(0, -16384, 0), Vector3.one * 16384
	elseif mode == 5 then
		-- Fling 1: source-style high-velocity position cycling.
		RootPart.CFrame = flingcf + jitter
		RootPart.Velocity = Vector3.new(9e7, 9e8, 9e7)
		RootPart.RotVelocity = Vector3.new(9e8, 9e8, 9e8)
	elseif mode == 6 then
		-- Fling 2: source-style carpet follow/prediction. Keep velocity neutral so the
		-- target-following behavior remains stable instead of fighting the animation.
		RootPart.CFrame = flingcf + jitter
		RootPart.Velocity, RootPart.RotVelocity = Vector3.zero, Vector3.zero
	elseif mode == 7 then
		-- Fling 3: source-style rapid target sweep, with the flight velocity used by sFLY.
		RootPart.CFrame = flingcf + jitter
		RootPart.Velocity = Vector3.new(9e7, 9e8, 9e7)
		RootPart.RotVelocity = Vector3.new(9e8, 9e8, 9e8)
	else
		-- default fling
		RootPart.CFrame = flingcf + jitter
		RootPart.Velocity, RootPart.RotVelocity = Vector3.new(0, -16384, 0), Vector3.one * 16384
	end
end
Util.Fling.ApplyHumanoid = function(Humanoid, ft, lastspawn)
	local nan = (ft and ft.Mode or Util.Fling.Method) == 4
	if nan then
		if os.clock() - lastspawn > 0.1 then
			pcall(sethiddenproperty, Humanoid, "MoveDirectionInternal", Vector3.new(0/0, 0/0, 0/0))
		else
			pcall(sethiddenproperty, Humanoid, "MoveDirectionInternal", Vector3.zero)
		end
		pcall(sethiddenproperty, Humanoid, "NetworkHumanoidState", Enum.HumanoidStateType.Freefall.Value)
	else
		pcall(sethiddenproperty, Humanoid, "NetworkHumanoidState", Enum.HumanoidStateType.Flying.Value)
	end
end

SaveData.Reanimator = SaveData.Reanimator or {}

local LimbReanimator = {}
LimbReanimator.Name = "Limbs"
SaveData.Reanimator.LimbMode = SaveData.Reanimator.LimbMode or 0
SaveData.Reanimator.LimbVelocity = SaveData.Reanimator.LimbVelocity or 0
SaveData.Reanimator.LimbInitMode = SaveData.Reanimator.LimbInitMode or 2
SaveData.Reanimator.LimbReplicateFPS10 = not not SaveData.Reanimator.LimbReplicateFPS10
SaveData.Reanimator.LimbRoleplay = not not SaveData.Reanimator.LimbRoleplay
SaveData.Reanimator.LimbUseNaNFling = not not SaveData.Reanimator.LimbUseNaNFling
LimbReanimator.Mode = SaveData.Reanimator.LimbMode
if LimbReanimator.Mode >= 7 then LimbReanimator.Mode = 2 end -- plugin mode: resolved by name once plugins load
-- 0 = hide rootpart (defaults to 2 when streaming is enabled)
-- 1 = put rootpart just under void (defaults to 2 when streaming is enabled)
-- 2 = keep rootpart streamed, puts rootpart below character
-- 3 = currentangle styled
-- 4 = rootpart is torso (most interpolated mode)
-- 5 = rootpart in the sky (defaults to 2 when streaming is enabled)
-- 6 = rootpart in the very sky (defaults to 2 when streaming is enabled)
-- 7+ = user plugins from UhhhhhhReanim/Plugins
LimbReanimator.Velocity = SaveData.Reanimator.LimbVelocity
-- 0 = no velocity
-- 1 = copy from fake character
-- 2 = fling-y velocity
LimbReanimator.InitMode = SaveData.Reanimator.LimbInitMode
-- 0 = just reset
-- 1 = time permadeath, and reset
-- 2 = time permadeath, "without reset"
LimbReanimator.ReplicateFPS10 = SaveData.Reanimator.LimbReplicateFPS10
LimbReanimator.FlingEnabled = not SaveData.Reanimator.LimbRoleplay
-- [nooby mod] NaN fling is now Util.Fling.Method == 4 (Fling Method dropdown on the main page)
LimbReanimator.FlingTargets = {}
LimbReanimator._TempNotFling = {}
LimbReanimator.BuiltinModeNames = {"RootPart in very void", "RootPart in void", "Keep RootPart Streamed", "CurrentAngle Style", "RootPart is Torso", "RootPart in sky", "RootPart in very sky"}
LimbReanimator.PluginModes = {}
function LimbReanimator.GetModeNames()
	local names = table.clone(LimbReanimator.BuiltinModeNames)
	for _,pm in LimbReanimator.PluginModes do
		table.insert(names, pm.Name)
	end
	return names
end
function LimbReanimator.RegisterMode(def, file)
	if type(def) ~= "table" then error("plugin must return a table") end
	if def.Name == nil and #def > 0 then
		for _,d in ipairs(def) do LimbReanimator.RegisterMode(d, file) end
		return
	end
	if type(def.Name) ~= "string" or type(def.GetRootCFrame) ~= "function" then
		error("plugin needs Name (string) and GetRootCFrame (function)")
	end
	table.insert(LimbReanimator.PluginModes, {Name = def.Name, GetRootCFrame = def.GetRootCFrame, File = file})
end
function LimbReanimator.ResolveSavedMode()
	local saved = SaveData.Reanimator.LimbModeName
	if type(saved) ~= "string" then return end
	for i,pm in LimbReanimator.PluginModes do
		if pm.Name == saved then
			LimbReanimator.Mode = 6 + i
			SaveData.Reanimator.LimbMode = LimbReanimator.Mode
			return
		end
	end
end
function LimbReanimator.ShowHitboxes()
	Util.UINotify("Just a useless option")
	pcall(function()
		Util.ShowPartHitbox(Player.Character.HumanoidRootPart)
	end)
end
function LimbReanimator.Fling(target, duration)
	if not LimbReanimator.FlingEnabled then return end
	if not target then return false end
	for _,v in LimbReanimator.FlingTargets do
		if v.Target == target then
			return false
		end
	end
	if target == Reanimate.Character then return false end
	if target == Player.Character then return false end
	if typeof(target) == "Instance" then
		if LimbReanimator._TempNotFling[target] then return end
		LimbReanimator._TempNotFling[target] = true
		task.delay(1, function()
			LimbReanimator._TempNotFling[target] = nil
		end)
	end
	table.insert(LimbReanimator.FlingTargets, {
		Target = target,
		Duration = duration
	})
	if typeof(target) == "Instance" then
		if target:IsA("Model") then
			local h = Util.Instance("Highlight")
			h.Adornee = target
			h.FillColor = Color3.new(1, 0, 0)
			h.OutlineColor = Color3.new(1, 0, 0)
			h.FillTransparency = 0.5
			h.OutlineTransparency = 0
			h.Parent = target
			TweenService:Create(h, TweenInfo.new(5), {
				FillTransparency = 1,
				OutlineTransparency = 1
			}):Play()
			game.Debris:AddItem(h, 5)
		end
	end
	return true
end
function LimbReanimator.SetRootPartMode(mode)
	assert(typeof(mode) == "number")
	LimbReanimator.Mode = mode
end
function LimbReanimator.Config(parent)
	UI.CreateText(parent, "as mentioned in the README, this only works for SOME games,\nbecause 'modern' games create the Animator automatically which breaks limb reanimation", 10, Enum.TextXAlignment.Center)
	local modenames = LimbReanimator.GetModeNames()
	local dmode = UI.CreateDropdown(parent, "RootPart Mode", modenames, LimbReanimator.Mode + 1)
	local dvel = UI.CreateDropdown(parent, "RootPart Velocity", {"No Velocity", "Follow Character", "Fling-like"}, LimbReanimator.Velocity + 1)
	local dinit = UI.CreateDropdown(parent, "Init Mode", {"Reset Character", "CDSB + Reset", "CDSB + SSE + Kill"}, LimbReanimator.InitMode + 1)
	dmode.Changed:Connect(function(val)
		LimbReanimator.Mode = val - 1
		SaveData.Reanimator.LimbMode = val - 1
		SaveData.Reanimator.LimbModeName = modenames[val]
	end)
	dvel.Changed:Connect(function(val)
		LimbReanimator.Velocity = val - 1
		SaveData.Reanimator.LimbVelocity = val - 1
	end)
	dinit.Changed:Connect(function(val)
		LimbReanimator.InitMode = val - 1
		SaveData.Reanimator.LimbInitMode = val - 1
	end)
	UI.CreateSwitch(parent, "Show me how I look!", LimbReanimator.ReplicateFPS10).Changed:Connect(function(val)
		LimbReanimator.ReplicateFPS10 = val
		SaveData.Reanimator.LimbReplicateFPS10 = val
	end)
	UI.CreateSwitch(parent, "Target Fling Enabled", LimbReanimator.FlingEnabled).Changed:Connect(function(val)
		LimbReanimator.FlingEnabled = val
		SaveData.Reanimator.LimbRoleplay = not val
	end)
	UI.CreateText(parent, "vvv touch player = they lose ownership vvv", 10, Enum.TextXAlignment.Center)
	UI.CreateText(parent, "fling style is chosen with the 'Fling Method' dropdown on the main page\n(Default / Weak / Nooby's / NaN State / Fling 1 / Fling 2 / Fling 3)", 10, Enum.TextXAlignment.Center)
	Util.LinkDestroyI2C(dmode, RunService.Heartbeat:Connect(function()
		dmode.Value = math.min(LimbReanimator.Mode + 1, #modenames)
		dvel.Value = LimbReanimator.Velocity + 1
		dinit.Value = LimbReanimator.InitMode + 1
	end))
end
function LimbReanimator.Start()
	local LimbNames = {"Head", "Torso", "Left Arm", "Right Arm", "Left Leg", "Right Leg"}
	local rootposition = Vector3.new(
		math.random(-65536, 65536),
		math.random(-70000, -60000),
		math.random(-65536, 65536)
	)
	local rootposition2 = Vector3.new(
		math.random(-2048, 2048),
		math.random(-500, -100) + FallenPartsDestroyHeight,
		math.random(-2048, 2048)
	)
	local skyposition = Vector3.new(
		math.random(-2048, 2048),
		math.random(1000, 2000),
		math.random(-2048, 2048)
	)
	local veryskyposition = Vector3.new(
		math.random(-65536, 65536),
		math.random(60000, 70000),
		math.random(-65536, 65536)
	)
	local InitCFrame = nil
	if Player.Character then
		local h = Player.Character:FindFirstChildOfClass("Humanoid")
		if h and h.RootPart then
			local r = h.RootPart
			InitCFrame = r.CFrame
			if h:GetState() ~= Enum.HumanoidStateType.Dead then
				h:SetStateEnabled(Enum.HumanoidStateType.Dead, true)
				h:ChangeState(Enum.HumanoidStateType.Dead)
			end
		end
	end

	local LimbMapping = loadstring(readfile("UhhhhhhReanim/BuiltinModules/d_limbmap.lua"))()

	local FakeTools = {}
	local function CreateFakeTool()
		local FakeTool = Instance.new("Tool")
		FakeTool.Name = "faketool"
		local FakeToolHandle = Instance.new("Part")
		FakeToolHandle.Name = "Handle"
		FakeToolHandle.Transparency = 1
		FakeToolHandle.Color = Color3.new(0, 0, 1)
		FakeToolHandle.CanCollide = false
		FakeToolHandle.Massless = true
		FakeToolHandle.Parent = FakeTool
		FakeTool.Parent = Reanimate.Character
		local RightGrip = Instance.new("Weld")
		RightGrip.Name = "RightGrip"
		RightGrip.Parent = FakeToolHandle
		RightGrip.Part0 = Reanimate.Character and Reanimate.Character:FindFirstChild("Right Arm")
		RightGrip.Part1 = FakeToolHandle
		RightGrip.C0 = RIGHTGRIP_C0
		Util.LinkDestroyI2C(FakeTool, FakeTool:GetPropertyChangedSignal("Grip"):Connect(function()
			RightGrip.C1 = FakeTool.Grip
		end))
		RightGrip.C1 = FakeTool.Grip
		return FakeTool
	end

	local BaseParts = {}
	local UnknownMotor6Ds = {}
	local CharOnDesc = function(v)
		if v:IsA("BasePart") then
			if not table.find(BaseParts, v) then
				table.insert(BaseParts, v)
				v.CanCollide = false
				v:GetPropertyChangedSignal("CanCollide"):Connect(function()
					if v.CanCollide then v.CanCollide = false end
				end)
			end
		elseif v:IsA("Motor6D") then
			repeat task.wait() until (not v:IsDescendantOf(workspace)) or (v.Part0 and v.Part1)
			if not v:IsDescendantOf(workspace) then return end
			local p0, p1 = v.Part0, v.Part1
			if p0 and p1 then
				p0, p1 = p0.Name, p1.Name
				for _,map in LimbMapping do
					if map.Part0 == p0 and map.Part1 == p1 then
						map.Reference = v
						return
					end
				end
			end
			table.insert(UnknownMotor6Ds, v)
		elseif v:IsA("Animator") then
			task.defer(v.Destroy, v)
		elseif v:IsA("LocalScript") and v.Parent == Player.Character then
			v.Enabled = false
			v:GetPropertyChangedSignal("Enabled"):Connect(function()
				if v.Enabled then v.Enabled = false end
			end)
			v:GetPropertyChangedSignal("Disabled"):Connect(function()
				if not v.Disabled then v.Disabled = true end
			end)
		elseif v:IsA("Tool") and v.Parent == Player.Character then
			if not FakeTools[v] then
				FakeTools[v] = true
				local fake = CreateFakeTool()
				fake.Grip = v.Grip
				local h = v:FindFirstChild("Handle")
				if h ~= nil then
					fake.Handle.Size = h.Size
				end
				Util.LinkDestroyI2C(fake, RunService.PreSimulation:Connect(function()
					if v.Parent == Player.Character then
						fake.Grip = v.Grip
						local h = v:FindFirstChild("Handle")
						if h ~= nil then
							fake.Handle.Size = h.Size
						end
					else
						fake:Destroy()
						FakeTools[v] = nil
					end
				end))
				Util.LinkDestroyI2C(fake, v.ChildAdded:Connect(function(v)
					if v.ClassName == "StringValue" and v.Name == "toolanim" then
						local w = Instance.new("StringValue")
						w.Name = "toolanim"
						w.Value = v.Value
						w.Parent = fake
						Debris:AddItem(v, 1)
						Debris:AddItem(w, 1)
					end
				end))
				fake.Handle.Touched:Connect(function(t)
					local h = v:FindFirstChild("Handle")
					if h and t and h:IsDescendantOf(workspace) and t:IsDescendantOf(workspace) then
						h.CanTouch = true
						pcall(firetouchinterest, h, t, 0)
					end
				end)
				fake.Handle.TouchEnded:Connect(function(t)
					local h = v:FindFirstChild("Handle")
					if h and t and h:IsDescendantOf(workspace) and t:IsDescendantOf(workspace) then
						h.CanTouch = true
						pcall(firetouchinterest, h, t, 1)
					end
				end)
			end
		end
	end
	local lastspawn = 0
	local CharConn = Player.CharacterAdded:Connect(function(character)
		local camcfr = Camera.CFrame
		RunService.PreRender:Once(function()
			RunService.PreAnimation:Wait()
			Camera.CFrame = camcfr
		end)
		lastspawn = os.clock()
		table.clear(BaseParts)
		table.clear(UnknownMotor6Ds)
		for _,map in LimbMapping do
			map.Reference = nil
		end
		character.DescendantAdded:Connect(CharOnDesc)
		for _,v in character:GetDescendants() do
			task.spawn(CharOnDesc, v)
		end
		local humanoid = character:WaitForChild("Humanoid", 5)
		local stupid = humanoid:FindFirstChildWhichIsA("Animator")
		if stupid then
			stupid:Destroy()
		end
		if not Reanimate.UseLoadAnimationHook then
			stupid = character:FindFirstChild("Animate")
			while not stupid do
				character.ChildAdded:Wait()
				stupid = character:FindFirstChild("Animate")
			end
			stupid:Destroy()
		end
	end)
	Player.CharacterAdded:Wait()
	Reanimate.CreateCharacter(InitCFrame)

	local lastrep = 0
	local function UpdateTransforms(ReanimCharacter, RootPart, rootcf, rootvel, flingtarget, flingcf)
		if not RootPart:IsGrounded() then
			if flingtarget then
				Util.Fling.ApplyRoot(RootPart, flingtarget, flingcf)
				pcall(sethiddenproperty, RootPart, "PhysicsRepRootPart", Util.Fling.UseGlue() and Util.PredictionFlingPart(flingtarget.Target) or nil)
			else
				RootPart.CFrame = rootcf + Vector3.new(0, 0, math.random(0, 1) * 0.005)
				RootPart.Velocity, RootPart.RotVelocity = rootvel, Vector3.zero
				pcall(sethiddenproperty, RootPart, "PhysicsRepRootPart", nil)
			end
		end
		local dorep = true
		if LimbReanimator.ReplicateFPS10 then
			dorep = false
			local b = os.clock()
			local a = b - lastrep
			if a >= 1 / 10 then
				dorep = true
				a %= 1 / 10
				lastrep = b - a
			end
		end
		for _,v in UnknownMotor6Ds do
			Util.SetMotor6DTransform(v, CFrame.identity)
		end
		for _,map in LimbMapping do
			local v = map.Reference
			if v then
				if flingtarget then
					Util.SetMotor6DTransform(v, CFrame.identity)
				else
					local cf = CFrame.identity
					local p0, p1 = ReanimCharacter:FindFirstChild(map.RPart0), ReanimCharacter:FindFirstChild(map.RPart1)
					if map.RPart0 == "ROOT" then
						p0 = RootPart
					end
					if p0 and p1 then
						if map.Type == 1 then
							cf = p0.CFrame:ToObjectSpace(p1.CFrame)
						end
						if map.Type == 2 then
							local offset = map.Offset or CFrame.identity
							local c0, c1 = CFrame.new(map.C0), CFrame.new(map.C1)
							local transform = offset * (p0.CFrame * c0):ToObjectSpace(p1.CFrame * c1) * offset:Inverse()
							cf = v.C0 * transform * v.C1:Inverse()
						end
					end
					if dorep or not map.CFrame then
						map.CFrame = cf
					end
					Util.SetMotor6DOffset(v, map.CFrame)
				end
			end
		end
	end

	Reanimate.Starting = false
	while not Reanimate.Stopping do
		RunService.PreSimulation:Wait()
		workspace.FallenPartsDestroyHeight = 0/0
		local ReanimOkay = false
		local Character, Humanoid, RootPart = Player.Character, nil, nil
		if Character then
			Humanoid = Character:FindFirstChildOfClass("Humanoid")
			if Humanoid then
				Humanoid.AutoRotate = false
				if Humanoid.WalkSpeed < 1 then
					Humanoid.WalkSpeed = 16
				end
				if Humanoid.JumpPower < 1 then
					Humanoid.JumpPower = 50
				end
				RootPart = Humanoid.RootPart
				if RootPart and Humanoid:GetState() ~= Enum.HumanoidStateType.Dead then
					Humanoid:ChangeState(Enum.HumanoidStateType.Physics)
					ReanimOkay = LimbReanimator.FlingTargets[1] == nil
				end
			end
		end
		local rootcf = CFrame.new(LimbReanimator.Mode == 5 and skyposition or LimbReanimator.Mode == 6 and veryskyposition or rootposition)
		local rootvel = Vector3.zero
		local ltm = Reanimate.LocalTransparencyModifier
		local ReanimCharacter = Reanimate.Character
		if ReanimCharacter then
			local RCHumanoid = ReanimCharacter:FindFirstChildOfClass("Humanoid")
			local RCRootPart = ReanimCharacter:FindFirstChild("HumanoidRootPart")
			local RCTorso = ReanimCharacter:FindFirstChild("Torso")
			if Camera then
				Camera.CameraSubject = RCHumanoid
			end
			for _,v in BaseParts do
				v.CanCollide = false
				v.Velocity = Vector3.zero
				v.RotVelocity = Vector3.zero
				if not v:FindFirstAncestorWhichIsA("Tool") then
					local lltm = ltm
					if Reanimate.FirstPersonBody then
						lltm = 0
						if v.Name == "Head" then
							lltm = ltm
						else
							local lol = v:FindFirstChild("AccessoryWeld")
							if lol and lol:IsA("Weld") and lol.Part1 and lol.Part1.Name == "Head" then
								lltm = ltm
							end
						end
					end
					v.LocalTransparencyModifier = lltm
				end
			end
			for _,v in ReanimCharacter:GetChildren() do
				if v:IsA("BasePart") then
					if table.find(LimbNames, v.Name) then
						v.Transparency = ReanimOkay and 1 or Reanimate.PlaceholderTransparency
					end
				end
			end
			if Character and Humanoid and RootPart then
				RunService.Heartbeat:Wait()
				local t = os.clock()
				if RCRootPart and RCTorso then
					if LimbReanimator.Mode == 1 then
						rootcf = CFrame.new(rootposition2)
					end
					if LimbReanimator.Mode == 5 then
						rootcf = CFrame.new(skyposition)
					end
					if LimbReanimator.Mode == 6 then
						rootcf = CFrame.new(veryskyposition)
					end
					if LimbReanimator.Mode == 2 or workspace.StreamingEnabled then
						rootcf = CFrame.new(RCRootPart.Position + Vector3.new(0, -16, 0))
					end
					if LimbReanimator.Mode == 3 then
						rootcf = RCRootPart.CFrame
					end
					if LimbReanimator.Mode == 4 then
						rootcf = RCTorso.CFrame
					end
					if LimbReanimator.Velocity == 1 then
						rootvel = RCRootPart.Velocity
					elseif LimbReanimator.Velocity == 2 then
						rootvel = Vector3.new(0, 16384, 0)
					end
					if LimbReanimator.Mode >= 7 then
						local pm = LimbReanimator.PluginModes[LimbReanimator.Mode - 6]
						local usedplugin = false
						if pm and not pm.Failed then
							local ok, pcf, pvel = pcall(pm.GetRootCFrame, {
								RootPart = RCRootPart,
								Torso = RCTorso,
								Character = ReanimCharacter,
								Time = t,
								FallenPartsDestroyHeight = FallenPartsDestroyHeight,
								Streaming = workspace.StreamingEnabled,
							})
							if ok and typeof(pcf) == "CFrame" then
								rootcf = pcf
								if typeof(pvel) == "Vector3" then rootvel = pvel end
								usedplugin = true
							else
								pm.Failed = true
								Util.Notify("Plugin '" .. pm.Name .. "' failed and was disabled: " .. tostring(ok and "GetRootCFrame must return a CFrame" or pcf))
							end
						end
						if not usedplugin then
							rootcf = CFrame.new(RCRootPart.Position + Vector3.new(0, -16, 0))
						end
					end
				end
				local flingtarget, flingcf = Util.Fling.Step(LimbReanimator.FlingTargets, t, Util.Fling.UseGlue() and 0.5 or 2)
				UpdateTransforms(ReanimCharacter, RootPart, rootcf, rootvel, flingtarget, flingcf)
				Util.Fling.ApplyHumanoid(Humanoid, flingtarget, lastspawn)
			end
			RunService.PreRender:Wait()
			if Reanimate:ShouldRotationType() then
				Reanimate:CameraLockCharacter()
			end
			if Character and Humanoid and RootPart then
				-- render/physics pass: the fling is only applied in the Heartbeat pass above (that is the state
				-- that gets sent to the server). Here the RootPart goes back to its hidden position so your own
				-- client never simulates the RootPart inside the target (that is a client-only fling).
				UpdateTransforms(ReanimCharacter, RootPart, rootcf, rootvel, nil, CFrame.identity)
			end
		end
	end
	CharConn:Disconnect()
	if Player.Character then
		local h = Player.Character:FindFirstChild("Humanoid")
		if h then
			h:SetStateEnabled(Enum.HumanoidStateType.Dead, true)
			h:ChangeState(Enum.HumanoidStateType.Dead)
		end
	end
	Reanimate.Stopping = false
	Reanimate.DestroyCharacter()
end

