function HatReanimator.ShowHitboxes()
	if Player.Character then
		for _,v in Player.Character:GetChildren() do
			if v:IsA("Accessory") then
				local handle = v:FindFirstChild("Handle")
				if handle and handle:IsA("BasePart") then
					if handle:GetAttribute("_Uhhhhhh_HasCollide") then
						Util.ShowPartHitbox(handle)
					end
				end
			end
		end
	end
end
HatReanimator.FlingTargets = {}
HatReanimator._TempNotFling = {}
HatReanimator.BuiltinFlingNames = {"Disabled (RP)", "Classic Respawn", "Biggest Hat", "All Hats", "Use Tool Handle"}
HatReanimator.PluginFlingMethods = {}
function HatReanimator.GetFlingNames()
	local names = table.clone(HatReanimator.BuiltinFlingNames)
	for _,fm in HatReanimator.PluginFlingMethods do
		table.insert(names, fm.Name)
	end
	return names
end
function HatReanimator.RegisterFlingMethod(def, file)
	if type(def) ~= "table" then error("fling method must return a table") end
	if def.Name == nil and #def > 0 then
		for _,d in ipairs(def) do HatReanimator.RegisterFlingMethod(d, file) end
		return
	end
	if type(def.Name) ~= "string" or type(def.Run) ~= "function" then
		error("fling method needs Name (string) and Run (function)")
	end
	table.insert(HatReanimator.PluginFlingMethods, {Name = def.Name, Run = def.Run, File = file})
end
function HatReanimator.ResolveSavedFling()
	local saved = SaveData.Reanimator.HatsFlingMethodName
	if type(saved) ~= "string" then return end
	for i,fm in HatReanimator.PluginFlingMethods do
		if fm.Name == saved then
			HatReanimator.FlingMethod = 3 + i
			SaveData.Reanimator.HatsFlingMethod = HatReanimator.FlingMethod
			return
		end
	end
end
function HatReanimator.Fling(target, duration)
	if HatReanimator.FlingMethod == -1 then return end
	if not target then return false end
	for _,v in HatReanimator.FlingTargets do
		if v.Target == target then
			return false
		end
	end
	if target == Reanimate.Character then return false end
	if target == Player.Character then return false end
	if typeof(target) == "Instance" then
		if HatReanimator._TempNotFling[target] then return end
		HatReanimator._TempNotFling[target] = true
		task.delay(1, function()
			HatReanimator._TempNotFling[target] = nil
		end)
	end
	table.insert(HatReanimator.FlingTargets, {
		Target = target,
		Duration = duration
	})
	if typeof(target) == "Instance" then
		if target:IsA("Model") then
			local h = Util.Instance("Highlight")
			h.Adornee = target
			h.FillColor = Color3.new(1, 0, 0)
			h.OutlineColor = Color3.new(1, 0, 0)
			h.FillTransparency = 0.5
			h.OutlineTransparency = 0
			h.Parent = target
			TweenService:Create(h, TweenInfo.new(5), {
				FillTransparency = 1,
				OutlineTransparency = 1
			}):Play()
			game.Debris:AddItem(h, 5)
		end
	end
	return true
end
