		CM.FlySpeed = math.clamp(tonumber(CM.FlySpeed) or 50, 5, 300)
		CM.FlyKey = math.clamp(math.floor(tonumber(CM.FlyKey) or 2), 1, 5)
		local FlyKeys = {"None", "F", "Y", "O", "I"}
		Reanimate.Fly = false -- never starts flying on its own
		UI.CreateSeparator(MainPage)
		UI.CreateText(MainPage, "Fly & WalkSpeed", 15, Enum.TextXAlignment.Center)
		UI.CreateSwitch(MainPage, "Custom WalkSpeed", CM.WalkEnabled).Changed:Connect(function(val)
			CM.WalkEnabled = val
		end)
		UI.CreateSlider(MainPage, "WalkSpeed", CM.WalkSpeed, 1, 250, 1).Changed:Connect(function(val)
			CM.WalkSpeed = math.clamp(val, 1, 250)
		end)
		local FlySwitch = UI.CreateSwitch(MainPage, "Fly  (E = up, Q = down)", false)
		FlySwitch.Changed:Connect(function(val)
			Reanimate.Fly = val
			Util.UINotify("Fly " .. (val and "ON" or "OFF"))
		end)
		UI.CreateSlider(MainPage, "Fly Speed", CM.FlySpeed, 5, 300, 5).Changed:Connect(function(val)
			CM.FlySpeed = math.clamp(val, 5, 300)
		end)
		UI.CreateDropdown(MainPage, "Fly Toggle Key", FlyKeys, CM.FlyKey).Changed:Connect(function(val)
			CM.FlyKey = val
		end)
		UserInputService.InputBegan:Connect(function(input, gpe)
			if gpe or input.UserInputType ~= Enum.UserInputType.Keyboard then return end
			local name = FlyKeys[CM.FlyKey]
			if name and name ~= "None" and input.KeyCode == Enum.KeyCode[name] then
				FlySwitch.Value = not FlySwitch.Value
			end
		end)
		local flyAtt, flyLV, flyVel = nil, nil, Vector3.zero
		local function flyCleanup()
			if flyLV then
				pcall(flyLV.Destroy, flyLV)
				flyLV = nil
			end
			if flyAtt then
				pcall(flyAtt.Destroy, flyAtt)
				flyAtt = nil
			end
			flyVel = Vector3.zero
		end
		local wasWalk = false
		RunService.PreSimulation:Connect(function(dt)
			local ch = Reanimate.Character
			local hum = ch and ch:FindFirstChildOfClass("Humanoid")
			local root = hum and hum.RootPart
			if not hum or not root then
				flyCleanup()
				return
			end
			if CM.WalkEnabled then
				wasWalk = true
				if hum.WalkSpeed ~= CM.WalkSpeed then
					hum.WalkSpeed = CM.WalkSpeed
				end
			elseif wasWalk then
				wasWalk = false
				hum.WalkSpeed = 16
			end
			if not Reanimate.Fly then
				if flyLV then flyCleanup() end
				return
			end
			if not flyLV or flyLV.Parent ~= root then
				flyCleanup()
				flyAtt = Instance.new("Attachment")
				flyAtt.Name = Util.RandomString(12)
				flyAtt.Parent = root
				flyLV = Instance.new("LinearVelocity")
				flyLV.Name = Util.RandomString(12)
				flyLV.Attachment0 = flyAtt
				flyLV.RelativeTo = Enum.ActuatorRelativeTo.World
				flyLV.VelocityConstraintMode = Enum.VelocityConstraintMode.Vector
				flyLV.MaxForce = math.huge
				flyLV.VectorVelocity = Vector3.zero
				flyLV.Parent = root
			end
			local mv = Reanimate.Control.Move
			if mv.Magnitude > 1 then mv = mv.Unit end
			local camcf = Reanimate.Camera:GetMovementCFrame()
			local dir = camcf:VectorToWorldSpace(Vector3.new(mv.X, 0, mv.Z))
			local up = 0
			if not UserInputService:GetFocusedTextBox() then
				if UserInputService:IsKeyDown(Enum.KeyCode.E) or Reanimate.Control.Jump then up += 1 end
				if UserInputService:IsKeyDown(Enum.KeyCode.Q) then up -= 1 end
			end
			local target = (dir + Vector3.new(0, up, 0)) * CM.FlySpeed
			flyVel = flyVel:Lerp(target, 1 - math.exp(-14 * dt))
			flyLV.VectorVelocity = flyVel
		end)
	end
