	UI.CreateSeparator(MainPage)
	-- [custom] PERFORMANCE: Anti Lag (strip textures) + Hide All Players -----------
	do
		UI.CreateText(MainPage, "Performance", 15, Enum.TextXAlignment.Center)
		pcall(function() Util.Search.Section(MainPage, "Performance") end)

		-- ===================== ANTI LAG =====================
		-- ON : blanks every texture in the Workspace (Decal, Texture, SurfaceAppearance,
		--      MeshPart/SpecialMesh textures, clothing) and remembers the originals.
		-- OFF: writes every remembered original back.
		-- Skipped on purpose: Accessories/Tools and your own character, because the
		-- reanimator matches hats by MeshId + TextureId and would break otherwise.
		local AntiLag = {}
		do
			local TextureProps = {
				Decal = {"Texture"},
				Texture = {"Texture"},
				SurfaceAppearance = {"ColorMap", "MetalnessMap", "NormalMap", "RoughnessMap"},
				MeshPart = {"TextureID"},
				SpecialMesh = {"TextureId"},
				Shirt = {"ShirtTemplate"},
				Pants = {"PantsTemplate"},
				ShirtGraphic = {"Graphic"},
			}
			local Saved = setmetatable({}, {__mode = "k"}) -- [Instance] = {prop = original}
			local enabled = false
			local token = 0 -- bumps on every toggle so an old sweep/restore stops itself
			local addedConn = nil
			local CHUNK = 1500

			local function isProtected(inst)
				if inst:FindFirstAncestorWhichIsA("Accoutrement") or inst:FindFirstAncestorWhichIsA("Tool") then
					return true
				end
				local mine = Player.Character
				if mine and inst:IsDescendantOf(mine) then return true end
				local rc = Reanimate.Character
				if rc and inst:IsDescendantOf(rc) then return true end
				return false
			end

			local function strip(inst)
				local props = TextureProps[inst.ClassName]
				if not props or Saved[inst] then return end
				if isProtected(inst) then return end
				local rec = nil
				for _, p in ipairs(props) do
					local ok, v = pcall(function() return inst[p] end)
					if ok and v ~= nil and v ~= "" then
						rec = rec or {}
						rec[p] = v
						pcall(function() inst[p] = "" end)
					end
				end
				if rec then Saved[inst] = rec end
			end

			function AntiLag.Set(on)
				on = on and true or false
				if on == enabled then return end
				enabled = on
				token += 1
				local my = token
				if addedConn then
					addedConn:Disconnect()
					addedConn = nil
				end
				if on then
					addedConn = workspace.DescendantAdded:Connect(strip)
					task.spawn(function()
						local list = workspace:GetDescendants()
						for i = 1, #list do
							if token ~= my then return end
							strip(list[i])
							if i % CHUNK == 0 then task.wait() end
						end
					end)
				else
					task.spawn(function()
						local list = {}
						for inst in pairs(Saved) do list[#list + 1] = inst end
						for i = 1, #list do
							if token ~= my then return end -- toggled on again; leftovers stay tracked
							local inst = list[i]
							local rec = Saved[inst]
							if rec then
								for p, v in pairs(rec) do
									pcall(function() inst[p] = v end)
								end
								Saved[inst] = nil
							end
							if i % CHUNK == 0 then task.wait() end
						end
					end)
				end
			end
		end

		-- ===================== HIDE ALL PLAYERS =====================
		-- ON : takes every OTHER player's character out of the Workspace (client only,
		--      so nothing renders and nothing simulates for them). New joins/respawns
		--      are hidden automatically.
		-- OFF: puts every character back where it was.
		local PlayerHider = {}
		do
			local enabled = false
			local records = {}   -- [Player] = {Char = Model, Parent = Instance}
			local watchers = {}  -- [Player] = {CharAdded = conn, CharParent = conn}
			local joinConn, leaveConn = nil, nil

			local function hide(plr, char)
				if not enabled or plr == Player then return end
				local parent = char.Parent
				if not parent then return end
				records[plr] = {Char = char, Parent = parent}
				pcall(function() char.Parent = nil end)
			end

			local function watchChar(plr, char)
				local w = watchers[plr]
				if not w then return end
				if w.CharParent then w.CharParent:Disconnect() end
				w.CharParent = char:GetPropertyChangedSignal("Parent"):Connect(function()
					if enabled and char.Parent ~= nil then hide(plr, char) end
				end)
				hide(plr, char)
			end

			local function watchPlayer(plr)
				if plr == Player or watchers[plr] then return end
				local w = {}
				watchers[plr] = w
				w.CharAdded = plr.CharacterAdded:Connect(function(char)
					watchChar(plr, char)
				end)
				if plr.Character then watchChar(plr, plr.Character) end
			end

			local function unwatchPlayer(plr)
				local w = watchers[plr]
				if w then
					if w.CharAdded then w.CharAdded:Disconnect() end
					if w.CharParent then w.CharParent:Disconnect() end
					watchers[plr] = nil
				end
				records[plr] = nil
			end

			function PlayerHider.Set(on)
				on = on and true or false
				if on == enabled then return end
				enabled = on
				if on then
					for _, plr in ipairs(Players:GetPlayers()) do watchPlayer(plr) end
					joinConn = Players.PlayerAdded:Connect(watchPlayer)
					leaveConn = Players.PlayerRemoving:Connect(unwatchPlayer)
				else
					if joinConn then joinConn:Disconnect() joinConn = nil end
					if leaveConn then leaveConn:Disconnect() leaveConn = nil end
					for plr in pairs(watchers) do
						local w = watchers[plr]
						if w.CharAdded then w.CharAdded:Disconnect() end
						if w.CharParent then w.CharParent:Disconnect() end
					end
					watchers = {}
					for plr, rec in pairs(records) do
						local char = rec.Char
						if char and plr.Character == char and char.Parent == nil then
							local parent = rec.Parent
							if not (parent and parent:IsDescendantOf(game)) then parent = workspace end
							pcall(function() char.Parent = parent end)
						end
					end
					records = {}
				end
			end
		end

		UI.CreateSwitch(MainPage, "Anti Lag (remove all textures)", false).Changed:Connect(function(val)
			AntiLag.Set(val)
			Util.UINotify("Anti Lag " .. (val and "ON" or "OFF"))
		end)
		UI.CreateSwitch(MainPage, "Hide All Players", false).Changed:Connect(function(val)
			PlayerHider.Set(val)
			Util.UINotify("Hide All Players " .. (val and "ON" or "OFF"))
		end)
		UI.CreateSeparator(MainPage)
	end
