	-- [nooby mod] TOGGLE KILL -------------------------------------------------------
	local ToggleKill = false
	local _killThreads = {}  -- tracks active kill loops per target character

	-- Cancels every active kill loop (called when Toggle Kill is switched off)
	local function _StopAllKillThreads()
		for target, thread in pairs(_killThreads) do
			pcall(task.cancel, thread)
		end
		_killThreads = {}
	end

	-- Starts a per-heartbeat loop that keeps firing firetouchinterest on targetCharacter
	-- until their health reaches 0 or Toggle Kill is turned off.
	local function _StartKillLoop(targetCharacter)
		if not firetouchinterest then return end
		if _killThreads[targetCharacter] then return end  -- already running for this target
		if targetCharacter == Reanimate.Character then return end  -- never target own fake char
		if targetCharacter == Player.Character then return end      -- never target self
		_killThreads[targetCharacter] = task.spawn(function()
			while ToggleKill do
				local char = Player.Character
				local hum = char and char:FindFirstChildOfClass("Humanoid")
				local tool = char and char:FindFirstChildOfClass("Tool")
				if not tool then
					tool = Player.Backpack:FindFirstChildOfClass("Tool")
					if tool and hum then hum:EquipTool(tool) end
				end
				local handle = tool and tool:FindFirstChild("Handle")
				local tHum = targetCharacter and targetCharacter:FindFirstChildOfClass("Humanoid")
				local tRoot = tHum and tHum.RootPart
				if not char or not handle or not tHum or not tRoot then
					task.wait(0.1)  -- wait and retry if something is missing
				elseif tHum.Health <= 0 then
					break  -- target died, stop the loop
				else
					local origGrip = tool.Grip
					tool.Grip = CFrame.new()
					tool.Grip = handle.CFrame:ToObjectSpace(tRoot.CFrame):Inverse()
					firetouchinterest(handle, tRoot, 0)
					firetouchinterest(handle, tRoot, 1)
					tool.Grip = origGrip
				end
				game:GetService("RunService").Heartbeat:Wait()
			end
			_killThreads[targetCharacter] = nil
		end)
	end

	UI.CreateSwitch(MainPage, "Toggle Kill", ToggleKill).Changed:Connect(function(val)
		ToggleKill = val
		if not val then _StopAllKillThreads() end  -- cancel all loops on disable
	end)
	-- Warning: Toggle Kill touches targets with your real character's tool, so reanimation modes where
	-- the RootPart is your torso / CurrentAngle style would kill YOU too.
	UI.CreateText(MainPage, '<font color="rgb(255,170,60)"><b>WARNING:</b> only use Toggle Kill with the <b>Keep RootPart Streamed</b>, <b>RootPart in void</b>, <b>RootPart in very void</b>, <b>RootPart in sky</b> or <b>RootPart in very sky</b> modes. With <b>RootPart is Torso</b> or <b>CurrentAngle Style</b> it will kill you too.</font>', 10, Enum.TextXAlignment.Center)
	-- Kill All: starts a kill loop on every other player (Toggle Kill must be on)
	UI.CreateButton(MainPage, "Kill All", 20).Activated:Connect(function()
		if not ToggleKill then return end  -- requires Toggle Kill to be enabled
		for _, plr in ipairs(Players:GetPlayers()) do
			if plr ~= Player and plr.Character then
				local tHum = plr.Character:FindFirstChildOfClass("Humanoid")
				if tHum and tHum.Health > 0 then
					_StartKillLoop(plr.Character)
				end
			end
		end
	end)
	-- END TOGGLE KILL -------------------------------------------------------
	UI.CreateSwitch(MainPage, "Key+Click Teleport", Reanimate.CtrlClick).Changed:Connect(function(val)
