	end)
	local Maus = Player:GetMouse()
	local HoldingCtrl = UI.CreateSwitch(MainPage, "TP Key Held", false)
	local _lastclick = nil
	local _lastclickgpe = false
	local _lastclicktick = 0
	local _lastclickpos = Vector3.zero
	UserInputService.InputBegan:Connect(function(input, gpe)
		if input.UserInputType == Enum.UserInputType.Keyboard then
			if input.KeyCode == selectedkey then
				HoldingCtrl.Value = true
			end
		end
		if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
			_lastclick = input
			_lastclickgpe = gpe
			_lastclicktick = os.clock()
			_lastclickpos = input.Position
		end
	end)
	UserInputService.InputEnded:Connect(function(input, gpe)
		if input.UserInputType == Enum.UserInputType.Keyboard then
			if input.KeyCode == selectedkey then
				HoldingCtrl.Value = false
			end
		end
		if _lastclick and _lastclick == input and not _lastclickgpe then
			if input.UserInputType == Enum.UserInputType.MouseButton1 or (os.clock() - _lastclicktick < 0.3 and (input.Position - _lastclickpos).Magnitude < 10) then
				if Reanimate.CtrlClick and HoldingCtrl.Value then
					if Maus.Target and Maus.Target.Parent then
						ReanimCharacterTeleport(Maus.Hit.Position + Vector3.new(0, 3, 0))
						return
					end
				end
				-- Fling is suppressed when Toggle Kill is active
				if Reanimate.ClickFling and not ToggleKill then
					if Maus.Target and Maus.Target.Parent then 
						local target = Maus.Target.Parent
						if target:IsA("Accessory") then
							target = target.Parent
						end
						if target:FindFirstChildOfClass("Humanoid") then
							if ReanimateFling(target) then return end
						end
					end
				end
				-- Toggle Kill: start a loop that fires until the target dies
				if ToggleKill then
					if Maus.Target and Maus.Target.Parent then
						local target = Maus.Target.Parent
						if target:IsA("Accessory") then
							target = target.Parent
						end
						if target ~= Player.Character and target ~= Reanimate.Character and target:FindFirstChildOfClass("Humanoid") then
							_StartKillLoop(target)
							return
						end
					end
				end
			end
		end
	end)
	UI.CreateButton(MainPage, "Teleport to 0, highest, 0", 20).Activated:Connect(function()
		local hit = workspace:Raycast(Vector3.new(0, 4500, 0), Vector3.new(0, -4500 + FallenPartsDestroyHeight, 0))
		if hit and hit.Position == hit.Position then
			ReanimCharacterTeleport(hit.Position + Vector3.new(0, 5, 0))
		else
			ReanimCharacterTeleport(Vector3.new(0, 0, 0))
		end
	end)
	UI.CreateButton(MainPage, "Teleport to 'LastSafe'", 20).Activated:Connect(function()
		ReanimCharacterTeleport(Vector3.new(0, FallenPartsDestroyHeight - 5000, 0))
	end)
	local TeleportToPlayerSel = UI.CreateText(MainPage, "<font color=\"#AAAAAA\">(enter a player name)</font>", 15, Enum.TextXAlignment.Center)
	local TeleportToPlayer = UI.CreateTextbox(MainPage, "", "Teleport To Player", 20)
	TeleportToPlayer:GetPropertyChangedSignal("Text"):Connect(function()
		local sel = Util.QueryPlayerSelector(TeleportToPlayer.Text)
		if sel then
			TeleportToPlayerSel.Text = `{sel.DisplayName} (@{sel.Name})`
		else
			if #TeleportToPlayer.Text == 0 then
				TeleportToPlayerSel.Text = "<font color=\"#AAAAAA\">(enter a player name)</font>"
			else
				TeleportToPlayerSel.Text = "<font color=\"#FF7777\">(player not found)</font>"
			end
		end
	end)
	TeleportToPlayer.FocusLost:Connect(function(enter)
		if enter then
			local sel = Util.QueryPlayerSelector(TeleportToPlayer.Text)
			if sel and sel.Character then
				local r = sel.Character:FindFirstChild("LowerTorso") or sel.Character:FindFirstChild("Torso")
				if r and r:IsA("BasePart") then
					ReanimCharacterTeleport(r.CFrame.Position)
				end
			end
			TeleportToPlayer.Text = ""
		end
	end)
end
-- [nooby mod] SERVER HOP ------------------------------------------------------
do
	local TeleportService = cloneref(game:GetService("TeleportService"))
	local LocalPlayer = Players.LocalPlayer
	SaveData.ServerHopMode = tonumber(SaveData.ServerHopMode) or 1
	if SaveData.ServerHopSkipVisited == nil then SaveData.ServerHopSkipVisited = true end
	if type(SaveData.ServerHopVisited) ~= "table" then SaveData.ServerHopVisited = {} end
	if type(SaveData.ServerHopReexec) ~= "string" then SaveData.ServerHopReexec = "" end
	if SaveData.ServerHopAutoExec == nil then SaveData.ServerHopAutoExec = true end -- [custom] ON by default
	if type(SaveData.ServerHopAutoPath) ~= "string" then SaveData.ServerHopAutoPath = "" end
	local VISIT_MEMORY = 3600 -- seconds a visited server is skipped for

	local function pruneVisited()
		local now, count = os.time(), 0
		for id, when in pairs(SaveData.ServerHopVisited) do
			if type(when) ~= "number" or now - when > VISIT_MEMORY then
				SaveData.ServerHopVisited[id] = nil
			else
				count += 1
			end
		end
		if count > 200 then SaveData.ServerHopVisited = {} end
	end
	pruneVisited()

	UI.CreateSeparator(MainPage)
	UI.CreateText(MainPage, "Server Hop", 15, Enum.TextXAlignment.Center)
	UI.CreateDropdown(MainPage, "Hop Mode", {
		"Random server",
		"Fewest players",
		"Most players (not full)",
	}, SaveData.ServerHopMode).Changed:Connect(function(val)
		SaveData.ServerHopMode = val
	end)
	UI.CreateSwitch(MainPage, "Skip servers I visited (1h)", SaveData.ServerHopSkipVisited).Changed:Connect(function(val)
		SaveData.ServerHopSkipVisited = val
	end)
	UI.CreateSwitch(MainPage, "Auto Execute after hop / rejoin", SaveData.ServerHopAutoExec).Changed:Connect(function(val)
		SaveData.ServerHopAutoExec = val
	end)
	UI.CreateText(MainPage, "Auto Execute runs this script again by itself in the new server.\nIt looks for its own file in your executor's workspace folder, so normally you set nothing.\nIf it can't find it, type the file name or a raw https:// link below (optional override).", 10, Enum.TextXAlignment.Center)
	local ReexecBox = UI.CreateTextbox(MainPage, SaveData.ServerHopReexec, "override: file name or link (optional)", 20)
	ReexecBox.FocusLost:Connect(function()
		SaveData.ServerHopReexec = ReexecBox.Text
	end)
	local HopStatus = UI.CreateText(MainPage, "<font color=\"#AAAAAA\">(ready)</font>", 12, Enum.TextXAlignment.Center)
	local function status(msg)
		HopStatus.Text = msg
	end

	-- [custom] Auto Execute: find this script's own file so the user doesn't have to type it
	local SELF_MARK = "Nooby's Uh Modded Reanimation"
	local function fileLooksLikeUs(path)
		local ok, data = pcall(readfile, path)
		if not ok or type(data) ~= "string" then return false end
		return data:sub(1, 4000):find(SELF_MARK, 1, true) ~= nil and data:find("_G.UhhhhhhLoaded", 1, true) ~= nil
	end
	local function findOwnFile()
		local saved = SaveData.ServerHopAutoPath
		if saved ~= "" and isfile(saved) and fileLooksLikeUs(saved) then
			return saved
		end
		local seen = 0
		for _, folder in {"", "."} do
			local okl, files = pcall(listfiles, folder)
			if okl and type(files) == "table" then
				for _, path in files do
					local low = path:lower()
					if (low:match("%.lua$") or low:match("%.txt$")) and not low:find("uhhhhhhreanim", 1, true) and isfile(path) then
						seen += 1
						if seen > 120 then break end
						if fileLooksLikeUs(path) then
							SaveData.ServerHopAutoPath = path
							return path
						end
						if seen % 8 == 0 then task.wait() end
					end
				end
				if seen > 0 then break end
			end
		end
		return nil
	end
	local function queueReexec()
		if not SaveData.ServerHopAutoExec then return true end
		local queue = queue_on_teleport or (syn and syn.queue_on_teleport) or (fluxus and fluxus.queue_on_teleport)
		if ismissing(queue) then
			Util.Notify("your executor has no queue_on_teleport, re-execute the script manually after hopping")
			return false
		end
		local src = SaveData.ServerHopReexec
		if type(src) ~= "string" then src = "" end
		src = src:gsub("^%s+", ""):gsub("%s+$", "")
		if #src == 0 then
			-- optional: getgenv().UhhhhhhReexec = "https://..." before running the script
			local okg, envsrc = pcall(function() return getgenv().UhhhhhhReexec end)
			if okg and type(envsrc) == "string" and envsrc ~= "" then src = envsrc end
		end
		if #src == 0 then
			status("auto execute: looking for this script's file...")
			src = findOwnFile() or ""
		end
		if #src == 0 then
			status("auto execute: couldn't find this script's file. Type its file name (or a raw link) in the box above.")
			Util.Notify("Auto Execute couldn't find this script's file. Type its file name or link in the Server Hop box.")
			return false
		end
		local body
		if src:lower():match("^https?://") then
			body = ("loadstring(game:HttpGet(%q))()"):format(src)
		else
			body = ("loadstring(readfile(%q))()"):format(src)
		end
		pcall(queue, "if not game:IsLoaded() then game.Loaded:Wait() end task.wait(2) " .. body)
		return true
	end

	local function fetchServers(desc)
		local list, cursor = {}, nil
		for _ = 1, 2 do -- up to 200 servers
			local url = ("https://games.roblox.com/v1/games/%d/servers/Public?sortOrder=%s&excludeFullGames=true&limit=100"):format(game.PlaceId, desc and "Desc" or "Asc")
			if cursor then url ..= "&cursor=" .. cursor end
			local ok, res = pcall(request, {Url = url, Method = "GET"})
			if not ok or type(res) ~= "table" then return list, "server list request failed" end
			if res.StatusCode == 429 then return list, "rate limited by Roblox, wait a minute and try again" end
			if res.StatusCode ~= 200 then return list, "server list error (HTTP " .. tostring(res.StatusCode) .. ")" end
			local okj, data = pcall(HttpService.JSONDecode, HttpService, res.Body)
			if not okj or type(data) ~= "table" or type(data.data) ~= "table" then return list, "bad server list response" end
			for _, s in data.data do table.insert(list, s) end
			cursor = data.nextPageCursor
			if type(cursor) ~= "string" then break end
		end
		return list
	end

	local function pickPool(servers)
		local mode = SaveData.ServerHopMode
		local visited = SaveData.ServerHopVisited
		local skip = SaveData.ServerHopSkipVisited
		local all, fresh = {}, {}
		for _, s in servers do
			if type(s) == "table" and type(s.id) == "string" and s.id ~= game.JobId
				and (tonumber(s.playing) or 0) < (tonumber(s.maxPlayers) or math.huge) then
				table.insert(all, s)
				if not (skip and visited[s.id]) then table.insert(fresh, s) end
			end
		end
		local pool = #fresh > 0 and fresh or all
		if mode == 2 then
			table.sort(pool, function(a, b) return (tonumber(a.playing) or 0) < (tonumber(b.playing) or 0) end)
		elseif mode == 3 then
			table.sort(pool, function(a, b) return (tonumber(a.playing) or 0) > (tonumber(b.playing) or 0) end)
		else
			for i = #pool, 2, -1 do
				local j = math.random(1, i)
				pool[i], pool[j] = pool[j], pool[i]
			end
		end
		return pool
	end

	local function tryTeleport(jobid)
		local failedmsg = nil
		local conn = TeleportService.TeleportInitFailed:Connect(function(plr, result, msg)
			if plr == LocalPlayer then
				failedmsg = (type(msg) == "string" and msg ~= "") and msg or tostring(result)
			end
		end)
		_G.UhhhhhhLoaded = nil -- so the re-executed copy is allowed to start
		local ok, err = pcall(TeleportService.TeleportToPlaceInstance, TeleportService, game.PlaceId, jobid, LocalPlayer)
		if not ok then failedmsg = tostring(err) end
		local start = os.clock()
		while not failedmsg and os.clock() - start < 8 do
			task.wait(0.2)
		end
		conn:Disconnect()
		if failedmsg then _G.UhhhhhhLoaded = true end -- we're still here, keep the guard
		return failedmsg == nil, failedmsg
	end

	local hopping = false
	UI.CreateButton(MainPage, "Server Hop", 20).Activated:Connect(function()
		if hopping then return end
		hopping = true
		task.spawn(function()
			status("looking for servers...")
			local servers, err = fetchServers(SaveData.ServerHopMode ~= 2)
			if #servers == 0 then
				hopping = false
				status(err or "no public servers found")
				return
			end
			local pool = pickPool(servers)
			if #pool == 0 then
				hopping = false
				status("no other servers available right now")
				return
			end
			SaveData.ServerHopVisited[game.JobId] = os.time()
			pruneVisited()
			queueReexec()
			for i = 1, math.min(4, #pool) do
				local s = pool[i]
				status(("hopping to %s (%d/%d players)..."):format(s.id:sub(1, 8), tonumber(s.playing) or 0, tonumber(s.maxPlayers) or 0))
				local ok, why = tryTeleport(s.id)
				if ok then
					hopping = false
					status("teleporting...")
					return
				end
				SaveData.ServerHopVisited[s.id] = os.time()
				status("that one failed (" .. tostring(why) .. "), trying the next...")
				task.wait(1)
			end
			hopping = false
			status("couldn't join any server, try again")
		end)
	end)
	UI.CreateButton(MainPage, "Rejoin This Server", 20).Activated:Connect(function()
		if hopping then return end
		hopping = true
		task.spawn(function()
			status("rejoining...")
			queueReexec()
			_G.UhhhhhhLoaded = nil
			local ok, err
			if #Players:GetPlayers() <= 1 then
				ok, err = pcall(TeleportService.Teleport, TeleportService, game.PlaceId, LocalPlayer)
			else
				ok, err = pcall(TeleportService.TeleportToPlaceInstance, TeleportService, game.PlaceId, game.JobId, LocalPlayer)
			end
			if not ok then
				_G.UhhhhhhLoaded = true
				status("rejoin failed: " .. tostring(err))
			end
			task.wait(5)
			hopping = false
		end)
	end)
end
