-- [nooby mod V12] Nooby's Script Hub (NOT FROM SCRIPTHUB): its own page on the main UI.
-- Separate from the built-in ScriptHub. Wrapped in do...end so it adds zero top-level locals.
do
	local NoobysHubScripts = {
		{"Nameless Admin (NEWEST)", "https://rawscripts.net/raw/Universal-Script-Nameless-admin-NEWEST-124628"},
		{"Nameless Admin (FilteringEnabled)", "https://raw.githubusercontent.com/FilteringEnabled/NamelessAdmin/main/Source"},
		{"Uhhhhhh Modded (awes fork)", "https://raw.githubusercontent.com/testing734/UhhhhhhModded/refs/heads/main/uhhhhhh%20awes%20fork"},
		{"Uhhhhhh Modded (betabetafork)", "https://raw.githubusercontent.com/testing734/UhhhhhhModded/refs/heads/main/betabetafork"},
		{"Uh Reanimate", "https://rawscripts.net/raw/Universal-Script-uh-reanimate-134885"},
	}
	local hubBusy = false
	local function hubNotify(text)
		pcall(Util.Notify, text)
	end
	-- fetch + compile + run one script; every step is protected so one bad script can't break the UI
	local function runHubScript(name, url)
		local ok, err = pcall(function()
			local src = game:HttpGet(url)
			if type(src) ~= "string" or src == "" then
				error("empty response", 0)
			end
			local fn, cerr = loadstring(src)
			if not fn then
				error(tostring(cerr or "loadstring failed"), 0)
			end
			fn()
		end)
		if ok then
			hubNotify("Nooby's script hub: ran " .. name)
		else
			warn("[nooby's script hub] Failed to execute " .. name .. " (" .. url .. "): " .. tostring(err))
			hubNotify("Nooby's script hub: " .. name .. " failed (see console)")
		end
		return ok
	end
	local function runHubGuarded(fn)
		if hubBusy then
			hubNotify("Nooby's script hub: still running a script, wait a moment")
			return
		end
		hubBusy = true
		task.spawn(function()
			pcall(fn)
			hubBusy = false
		end)
	end

	local NoobyHubPage = UI.CreatePage()
	pcall(function() Util.Search.Titles[NoobyHubPage] = "Script Hub" end)
	NoobyHubPage.ZIndex = 1
	NoobyHubPage.Position = UDim2.new(0.5, 360, 0.5, 0)
	NoobyHubPage.Interactable = false
	NoobyHubPage.Visible = false
	UI.CreateButton(MainPage, "Nooby's Script Hub (NOT FROM SCRIPTHUB) &gt;", 15).Activated:Connect(function()
		NoobyHubPage.Interactable = false
		NoobyHubPage.Visible = true
		MainPage.Interactable = false
		local tween = TweenService:Create(NoobyHubPage, TweenInfo.new(0.5, Enum.EasingStyle.Cubic, Enum.EasingDirection.In), {
			Position = UDim2.new(0.5, 0, 0.5, 0),
		})
		tween:Play()
		tween.Completed:Connect(function()
			NoobyHubPage.Interactable = true
		end)
	end)
	UI.CreateButton(NoobyHubPage, "&lt; Hurry back", 20).Activated:Connect(function()
		NoobyHubPage.Interactable = false
		MainPage.Interactable = false
		local tween = TweenService:Create(NoobyHubPage, TweenInfo.new(0.5, Enum.EasingStyle.Cubic, Enum.EasingDirection.Out), {
			Position = UDim2.new(0.5, 360, 0.5, 0),
		})
		tween:Play()
		tween.Completed:Connect(function()
			MainPage.Interactable = true
			NoobyHubPage.Visible = false
		end)
	end)
	UI.CreateText(NoobyHubPage, "Nooby's Script Hub", 30, Enum.TextXAlignment.Center)
	UI.CreateText(NoobyHubPage, "(NOT FROM SCRIPTHUB)", 12, Enum.TextXAlignment.Center)
	UI.CreateSeparator(NoobyHubPage)
	UI.CreateButton(NoobyHubPage, "* Run all " .. #NoobysHubScripts .. " scripts *", 20).Activated:Connect(function()
		runHubGuarded(function()
			for _, entry in ipairs(NoobysHubScripts) do
				runHubScript(entry[1], entry[2])
				task.wait(0.5)
			end
		end)
	end)
	UI.CreateSeparator(NoobyHubPage)
	for _, entry in ipairs(NoobysHubScripts) do
		local name, url = entry[1], entry[2]
		UI.CreateButton(NoobyHubPage, name, 15).Activated:Connect(function()
			runHubGuarded(function()
				runHubScript(name, url)
			end)
		end)
	end
end
