local InitLogsText = UI.CreateText(InitLogsPage, "Loading...", 12, Enum.TextXAlignment.Left)
local function _contentgetgithubraw(path)
	InitLogsText.Text ..= "\n[LOG] [GitGET] GET api./" .. path
	local s, resp = pcall(request, {
		Method = "GET",
		Url = "https://api.github.com/repos/STEVE-916-create/Uhhhhhh/contents/content/" .. path,
		Headers = {
			Accept = "application/vnd.github.VERSION.raw"
		}
	})
	if s and resp and resp.StatusCode == 200 then
		return resp.Body
	end
	if s and resp then
		InitLogsText.Text ..= "\n[WARN] [GitGET] GET api./" .. path .. " " .. resp.StatusCode
	elseif s then
		InitLogsText.Text ..= "\n[WARN] [GitGET] GET api./" .. path .. " NIL"
	else
		InitLogsText.Text ..= "\n[WARN] [GitGET] GET api./" .. path .. " ERR " .. resp
	end
	InitLogsText.Text ..= "\n[LOG] [GitGET] GET raw./" .. path
	s, resp = pcall(request, {
		Method = "GET",
		Url = "https://raw.githubusercontent.com/STEVE-916-create/Uhhhhhh/main/content/" .. path,
	})
	if s and resp and resp.StatusCode == 200 then
		return resp.Body
	end
	if s and resp then
		InitLogsText.Text ..= "\n[WARN] [GitGET] GET raw./" .. path .. " " .. resp.StatusCode
	elseif s then
		InitLogsText.Text ..= "\n[WARN] [GitGET] GET raw./" .. path .. " NIL"
	else
		InitLogsText.Text ..= "\n[WARN] [GitGET] GET raw./" .. path .. " ERR " .. resp
	end
	return nil
end
--[[ ════════════════════════════════════════════════════════════════════
  Util.Security  —  BACKGROUND MALWARE SCANNER  (replaces the old "megadetector")
  ────────────────────────────────────────────────────────────────────
  • Walks the executor workspace ONE FILE AT A TIME on a low-priority
    background thread (a file every cfg.FileDelay seconds) and backs off
    whenever the frame rate drops, so it never competes with the game.
  • Only reads script-like files (.lua / .luau / .txt). Media, downloaded
    content, the quarantine folder and files over 3 MB are skipped.
    Big files are analysed in 64 KB chunks with a frame of rest in between.
  • Uses weighted scoring instead of "contains a spawn call", so normal
    modules are left alone:
        score >= 100  MALICIOUS   blocked from loading; deletable (see below)
        score >=  60  SUSPICIOUS  warning only, never deleted
  • AUTO-DELETE is EXPERIMENTAL and OFF by default (SaveData.SecurityAutoDelete).
    Before a file is deleted a copy is kept in UhhhhhhReanim/Quarantine as
    *.quarantined (not runnable). Files in BuiltinModules are report-only.
  • Every signature is assembled at runtime by J() so this block can never
    match (and delete) the very script that contains it.
  • User modules are also checked right before they are loaded
    (Util.Security.GateModule), because a background scan that is still
    walking the workspace would otherwise be too late.
  Stored at Util.Security so it costs zero extra top-level locals.
════════════════════════════════════════════════════════════════════ ]]
do
	local built, sec = pcall(function()
		local Security = {
			Findings = {},
			Stats = {Scanned = 0, PassScanned = 0, Flagged = 0, Deleted = 0, Skipped = 0, Passes = 0},
			StatusText = "Security: starting...",
			OnStatus = nil,     -- function(text)       status line for the UI
			OnMalicious = nil,  -- function(path, report) first time a file is MALICIOUS
			_gen = 0,
			_running = false,
			_idle = false,
			_scanNow = false,
			_frame = 1 / 60,
			_conn = nil,
		}
		local Stats = Security.Stats

		local cfg = {
			FileDelay = 0.6,          -- seconds of rest after every scanned file
			ListDelay = 0.25,         -- seconds of rest after listing a folder
			PassDelay = 300,          -- idle time between full passes
			ChunkSize = 65536,
			ChunkOverlap = 4096,      -- must stay larger than LineWindow
			LineWindow = 3000,        -- how far past a spawn call we look on the same line
			MaxFileBytes = 3 * 1024 * 1024,
			MaxFrameTime = 1 / 24,    -- pause scanning while frames are slower than this
			EscapeLimit = 400,
			MaliciousScore = 100,
			SuspiciousScore = 60,
			Roots = {"UhhhhhhReanim/Modules", ""},  -- user modules first, then the whole workspace
			SkipDirs = {
				"uhhhhhhreanim/content",
				"uhhhhhhreanim/muzik",
				"uhhhhhhreanim/assets",
				"uhhhhhhreanim/quarantine",
			},
			ReportOnlyDirs = {"uhhhhhhreanim/builtinmodules"},
			Extensions = {lua = true, luau = true, txt = true},
			QuarantineDir = "UhhhhhhReanim/Quarantine",
		}

		local function J(...) return table.concat({...}) end

		-- id, weight, f = plain needle (or p = true for a Lua pattern) / any = list of plain needles.
		-- All matching runs on lower-cased text.
		local SIGS = {
			{id = "cookie_header", w = 100, f = J("_|warning:-do-not-", "share-this"), desc = "contains a Roblox login-cookie header"},
			{id = "cookie_ref", w = 100, f = J("roblo", "security"), desc = "reads or sends the account login cookie"},
			{id = "webhook", w = 60, any = {J("/api/web", "hooks/"), J("webhook.", "lewisakura"), J("hooks.", "hyra.io")}, desc = "sends data to a Discord webhook"},
			{id = "buy_prompt", w = 60, p = true, f = J("prompt%a*", "purchase"), desc = "pops up Robux purchase prompts"},
			{id = "trade_api", w = 60, f = J("trades.", "roblox.com"), desc = "uses the Roblox trade API"},
			{id = "buy_api", w = 60, f = J("/purchases/", "products"), desc = "calls the Roblox purchase API directly"},
			{id = "auth_api", w = 60, any = {J("auth.", "roblox.com"), J("accountsettings.", "roblox.com"), J("billing.", "roblox.com")}, desc = "talks to the Roblox account/auth API"},
			{id = "payouts", w = 60, f = J("/pay", "outs"), desc = "touches group payout endpoints"},
			{id = "stealer_words", w = 60, any = {J("cookie", "logger"), J("cookie", "grabber"), J("token", "grabber"), J("robux", "stealer"), J("steal", "cookie"), J("grab", "ify"), J("ip", "logger")}, desc = "contains stealer / IP-logger keywords"},
			{id = "decode_exec", w = 40, f = J("loadstring(string.", "char("), desc = "runs a decoded string.char payload"},
			{id = "balance_api", w = 25, f = J("economy.", "roblox.com"), desc = "queries the Roblox economy API"},
			{id = "csrf", w = 25, f = J("x-csrf-", "token"), desc = "handles X-CSRF tokens"},
			{id = "obfuscator", w = 25, any = {J("moon", "sec"), J("lur", "aph"), J("iron", "brew")}, desc = "is hidden by a script obfuscator"},
			{id = "paste_host", w = 25, any = {J("pastebin.com/", "raw"), J("hast", "ebin"), J("rentry", ".co"), J("ghost", "bin"), J("paste", ".ee/r")}, desc = "loads code from an editable paste site"},
		}

		-- Spawn-style calls that hide a payload in a long string on the same line.
		-- The first entry is the original megadetector rule (kept at full weight).
		local SPAWNERS = {
			{J("task", ".spawn"), 100},
			{J("task", ".defer"), 60},
			{J("task", ".delay"), 60},
			{J("coroutine", ".wrap"), 60},
		}

		-- ── helpers ──────────────────────────────────────────────────────
		local function normalize(p) return (tostring(p):gsub("\\", "/")) end
		local function shortName(p) return normalize(p):match("([^/]+)$") or tostring(p) end
		local function under(path, list)
			local p = normalize(path):lower() .. "/"
			for _, dir in ipairs(list) do
				if p:find(dir .. "/", 1, true) then return true end
			end
			return false
		end
		local function shouldScan(path)
			local ext = shortName(path):match("%.([%w_]+)$")
			return ext ~= nil and cfg.Extensions[ext:lower()] == true
		end
		local function lineOf(content, abs)
			if not abs then return nil end
			return select(2, content:sub(1, abs):gsub("\n", "")) + 1
		end
		local function addHit(state, content, id, weight, desc, abs)
			if state.hits[id] then return end
			state.hits[id] = {id = id, weight = weight, desc = desc, line = lineOf(content, abs)}
			state.score += weight
		end
		local function reasonText(report, n)
			local out = {}
			for i = 1, math.min(n or 3, #report.reasons) do
				local r = report.reasons[i]
				out[i] = r.desc .. (r.line and (" (line " .. r.line .. ")") or "")
			end
			return table.concat(out, "; ")
		end
		local function log(text)
			pcall(function() InitLogsText.Text ..= "\n[SECURITY] " .. text end)
		end
		local function notify(text)
			pcall(Util.UINotify, text)
		end
		local function status(prefix)
			local text = string.format("%s | scanned this pass: %d | flagged: %d | deleted: %d", prefix, Stats.PassScanned, Stats.Flagged, Stats.Deleted)
			Security.StatusText = text
			if Security.OnStatus then pcall(Security.OnStatus, text) end
		end

		-- ── analysis ─────────────────────────────────────────────────────
		local function scanChunk(content, pos, state)
			local low = content:sub(pos, pos + cfg.ChunkSize + cfg.ChunkOverlap - 1):lower()
			local hits, flags = state.hits, state.flags

			for i = 1, #SIGS do
				local sig = SIGS[i]
				if not hits[sig.id] then
					local at
					if sig.any then
						for j = 1, #sig.any do
							at = low:find(sig.any[j], 1, true)
							if at then break end
						end
					else
						at = low:find(sig.f, 1, not sig.p)
					end
					if at then addHit(state, content, sig.id, sig.w, sig.desc, pos + at - 1) end
				end
			end

			for i = 1, #SPAWNERS do
				local needle, weight = SPAWNERS[i][1], SPAWNERS[i][2]
				local id = "spawn_payload_" .. i
				if not hits[id] then
					local init = 1
					while true do
						local s, e = low:find(needle, init, true)
						if not s then break end
						local win = low:sub(e + 1, e + cfg.LineWindow)
						local nl = win:find("\n", 1, true)
						if nl then win = win:sub(1, nl - 1) end
						if win:find("%[=*%[") then
							addHit(state, content, id, weight, "hides a long-string payload right after " .. needle, pos + s - 1)
							break
						end
						init = e + 1
					end
				end
			end

			if not hits.raw_ip then
				for ip in low:gmatch("https?://(%d+%.%d+%.%d+%.%d+)") do
					if not (ip:find("^127%.") or ip:find("^10%.") or ip:find("^192%.168%.") or ip:find("^0%.")) then
						addHit(state, content, "raw_ip", 25, "talks to a bare IP address", nil)
						break
					end
				end
			end

			if not flags.ls and low:find("loadstring", 1, true) then flags.ls = true end
			if not flags.http and (low:find("httpget", 1, true) or low:find("httppost", 1, true) or low:find("getasync", 1, true) or low:find("postasync", 1, true)) then
				flags.http = true
			end
			if not flags.spawn and (low:find(SPAWNERS[1][1], 1, true) or low:find(SPAWNERS[4][1], 1, true)) then
				flags.spawn = true
			end
			state.esc += select(2, low:gsub("\\x%x%x", "")) + select(2, low:gsub("\\%d%d%d", ""))
		end

		-- Returns a report table, or nil if the scan was cancelled (gen changed).
		-- Pass `gen` only from the background thread: it makes the analysis yield between chunks.
		function Security.Analyze(content, gen)
			local state = {score = 0, hits = {}, flags = {}, esc = 0}
			local n, pos = #content, 1
			while pos <= n do
				scanChunk(content, pos, state)
				pos += cfg.ChunkSize
				if gen and pos <= n then
					task.wait()
					if Security._gen ~= gen then return nil end
				end
			end
			local f = state.flags
			if f.ls and f.http and f.spawn then
				addHit(state, content, "spawn_loader", 25, "spawns a remote loadstring loader", nil)
			end
			if state.esc >= cfg.EscapeLimit then
				addHit(state, content, "escapes", 25, "is packed with escape-sequence obfuscation", nil)
			end
			local reasons = {}
			for _, h in pairs(state.hits) do table.insert(reasons, h) end
			table.sort(reasons, function(a, b) return a.weight > b.weight end)
			local verdict = "CLEAN"
			if state.score >= cfg.MaliciousScore then
				verdict = "MALICIOUS"
			elseif state.score >= cfg.SuspiciousScore then
				verdict = "SUSPICIOUS"
			end
			return {verdict = verdict, score = state.score, reasons = reasons}
		end

		-- ── response (log / notify / experimental auto-delete) ───────────
		function Security.Enabled() return SaveData.SecurityScan ~= false end
		function Security.AutoDelete() return SaveData.SecurityAutoDelete == true end

		local function deleteFile(path, content)
			pcall(makefolder, cfg.QuarantineDir)
			local safe = (normalize(path):gsub("[^%w%._%-]", "_"))
			local copied = pcall(writefile, cfg.QuarantineDir .. "/" .. safe .. "." .. os.time() .. ".quarantined", content)
			pcall(delfile, path)
			local gone = false
			pcall(function() gone = not isfile(path) end)
			return gone, copied
		end

		local reported, byKey = {}, {}
		local function respond(path, report, content, blocked)
			local key = normalize(path) .. "|" .. report.score .. "|" .. #content
			local first = not reported[key]
			reported[key] = true
			local why = reasonText(report)
			local name = shortName(path)
			local malicious = report.verdict == "MALICIOUS"

			local deleted, copied = false, false
			if malicious and Security.AutoDelete() and not under(path, cfg.ReportOnlyDirs) then
				deleted, copied = deleteFile(path, content)
			end

			if first then
				Stats.Flagged += 1
				local finding = {path = path, verdict = report.verdict, score = report.score, why = why, deleted = deleted, time = os.time()}
				byKey[key] = finding
				table.insert(Security.Findings, finding)
			elseif deleted and byKey[key] then
				byKey[key].deleted = true
			end

			if deleted then
				Stats.Deleted += 1
				log("DELETED " .. path .. " [score " .. report.score .. "]: " .. why .. (copied and (" (copy kept in " .. cfg.QuarantineDir .. ")") or ""))
				notify("Auto-deleted " .. name .. ": " .. why)
			elseif first then
				log(report.verdict .. " " .. path .. " [score " .. report.score .. "]: " .. why)
				if malicious then
					notify((blocked and "Blocked malicious module " or "Malicious file found: ") .. name .. ": " .. why)
				else
					notify("Suspicious file: " .. name .. " (details in Init Logs)")
				end
			end

			if first and malicious and Security.OnMalicious then
				pcall(Security.OnMalicious, path, report)
			end
			return deleted
		end

		-- Called by ForceModuleReload right before a user module is loadstring'd.
		-- Returns a reason string if the module must NOT be loaded, otherwise nil.
		function Security.GateModule(path, content)
			if not Security.Enabled() or type(content) ~= "string" then return nil end
			local ok, report = pcall(Security.Analyze, content)
			if not ok or not report or report.verdict == "CLEAN" then return nil end
			respond(path, report, content, true)
			if report.verdict == "MALICIOUS" then return reasonText(report) end
			return nil
		end

		-- ── background walker ────────────────────────────────────────────
		local function waitFrameHealthy(gen)
			local waited = 0
			while Security._frame > cfg.MaxFrameTime and waited < 5 and Security._gen == gen do
				task.wait(0.25)
				waited += 0.25
			end
		end

		local function scanFile(path, gen)
			local ok, content = pcall(readfile, path)
			if not ok or type(content) ~= "string" or #content == 0 then return end
			if #content > cfg.MaxFileBytes then
				Stats.Skipped += 1
				return
			end
			local report = Security.Analyze(content, gen)
			if not report then return end
			Stats.Scanned += 1
			Stats.PassScanned += 1
			if report.verdict ~= "CLEAN" then respond(path, report, content, false) end
		end

		-- One full pass. Returns false if it was cancelled.
		local function runPass(gen)
			local queue, head, seen = {}, 1, {}
			for _, root in ipairs(cfg.Roots) do
				seen[normalize(root):lower()] = true
				table.insert(queue, {dir = true, path = root})
			end
			while head <= #queue do
				if Security._gen ~= gen then return false end
				local item = queue[head]
				head += 1
				if item.dir then
					local ok, list = pcall(listfiles, item.path)
					if ok and type(list) == "table" then
						for i, p in ipairs(list) do
							local key = normalize(p):lower()
							if not seen[key] then
								seen[key] = true
								if not under(p, cfg.SkipDirs) then
									local okf, isdir = pcall(isfolder, p)
									if okf and isdir then
										table.insert(queue, {dir = true, path = p})
									elseif shouldScan(p) then
										table.insert(queue, {path = p})
									end
								end
							end
							if i % 40 == 0 then task.wait() end
						end
					end
					task.wait(cfg.ListDelay)
				else
					waitFrameHealthy(gen)
					if Security._gen ~= gen then return false end
					status("Security: scanning " .. shortName(item.path))
					pcall(scanFile, item.path, gen)
					task.wait(cfg.FileDelay)
				end
			end
			return true
		end

		local function loop(gen)
			while Security._gen == gen do
				Stats.PassScanned = 0
				if not runPass(gen) then return end
				Stats.Passes += 1
				if Stats.Passes == 1 then
					log("First full scan finished: " .. Stats.PassScanned .. " files checked, " .. Stats.Flagged .. " flagged.")
				end
				status("Security: idle (pass " .. Stats.Passes .. " done)")
				Security._scanNow = false
				Security._idle = true
				local waited = 0
				while Security._gen == gen and not Security._scanNow and waited < cfg.PassDelay do
					task.wait(1)
					waited += 1
				end
				if Security._gen == gen then Security._idle = false end
			end
		end

		function Security.Start()
			if not Security.Enabled() or Security._running then return end
			Security._running = true
			Security._gen += 1
			local gen = Security._gen
			Security._conn = RunService.Heartbeat:Connect(function(dt)
				Security._frame = Security._frame * 0.9 + dt * 0.1
			end)
			status("Security: starting")
			task.spawn(function()
				pcall(loop, gen)
			end)
		end

		function Security.Stop()
			Security._gen += 1
			Security._running = false
			Security._idle = false
			if Security._conn then
				Security._conn:Disconnect()
				Security._conn = nil
			end
			status("Security: background scan is OFF")
		end

		function Security.ScanNow()
			if not Security._running then
				notify("Turn on Background Malware Scan first")
			elseif Security._idle then
				Security._scanNow = true
				notify("Starting a new security scan")
			else
				notify("A security scan is already running")
			end
		end

		return Security
	end)
	if built and type(sec) == "table" then
		Util.Security = sec
	else
		warn("[Uhhhhhh] Security module failed to load: " .. tostring(sec))
	end
end

local UserModulesListor = {}
local function ForceModuleReload(force)
	IsUhhhhhhFullyLoaded = false
	InitLogsText.Text = "Init Logs -- This is where you check what happened."
	ClearModules()
	table.clear(UserModulesListor)
	Util.UINotify("Checking hashes...", 0.05)
	InitLogsText.Text ..= "\n[LOG] Checking SHA1 hashes..."
	local filesofbuiltins = {"v_moveset1.lua", "v_moveset2.lua", "v_moveset3.lua", "v_dance1.lua", "v_dance2.lua", "d_limbmap.lua", "d_hatsmap.lua"}
	local filesofbuiltins_m = {"v_moveset1.lua", "v_moveset2.lua", "v_moveset3.lua", "v_dance1.lua", "v_dance2.lua"}
	local filesofbuiltins_d = {"d_limbmap.lua", "d_hatsmap.lua"}
	SaveData.ContentHash = SaveData.ContentHash or {}
	if force ~= "SKIPHASH" then
		xpcall(function()
			local s, resp = pcall(request, {
				Method = "GET",
				Url = "https://api.github.com/repos/STEVE-916-create/Uhhhhhh/contents/content/",
			})
			if s and resp and resp.StatusCode == 200 then
				s, resp = pcall(HttpService.JSONDecode, HttpService, resp.Body)
				if s and resp then
					for _,file in resp do
						if file.name and file.sha then
							if SaveData.ContentHash[file.name] ~= file.sha then
								SaveData.ContentHash[file.name] = file.sha
								if table.find(filesofbuiltins, file.name) then
									local path = "UhhhhhhReanim/BuiltinModules/" .. file.name
									if isfile(path) then
										InitLogsText.Text ..= "\n[LOG] BuiltinModules/" .. file.name .. " has been updated on the repo."
										delfile(path)
									end
								else
									local path = AssetGetPathFromFilename(file.name)
									if isfile(path) then
										InitLogsText.Text ..= "\n[LOG] Downloaded Asset " .. file.name .. " removed because outdated."
										delfile(path)
									end
								end
							end
						end
					end
				end
			end
			InitLogsText.Text ..= "\n[LOG] Checked all SHA1 hashes..."
		end, function()
			InitLogsText.Text ..= "\n[WARN] SHA1 hashes check failed!"
		end)
	else
		InitLogsText.Text ..= "\n[WARN] Chill. We are just reloading user modules."
		InitLogsText.Text ..= "\n[LOG] Checked all SHA1 hashes..."
	end
	local wasold = false
	if SaveData.VanillaModuleCache then
		wasold = true
		SaveData.VanillaModuleCache = nil
	end
	-- [custom] module loading modes: 1 = default (one at a time), 2 = splitted (2 at a time), 3 = instant (all at once)
	-- V15: 4 = slow (one file at a time, paced with a pause between every read / load, easiest on performance)
	local loadMode = tonumber(SaveData.ModuleLoadMode)
	if loadMode ~= 2 and loadMode ~= 3 and loadMode ~= 4 then loadMode = 1 end
	local SLOW_STEP_DELAY = 0.35 -- seconds to rest between each read and each load in Slow mode
	local function SlowPause()
		if loadMode == 4 then
			task.wait(SLOW_STEP_DELAY)
		end
	end
	InitLogsText.Text ..= "\n[LOG] Module load mode: " .. ({"Default", "Splitted (2 at a time)", "Instant", "Slow (1 at a time, paced)"})[loadMode]
	if loadMode == 3 then
		InitLogsText.Text ..= "\n[WARN] Instant mode loads every module at once and may crash your device!"
	elseif loadMode == 4 then
		InitLogsText.Text ..= "\n[LOG] Slow mode: one module at a time with a short pause between each, this takes longer."
	end
	-- `work` reads / downloads a file, `apply` loadstrings + registers it. Registration always happens in list order.
	local function RunPhase(items, work, apply)
		if loadMode == 4 then
			-- Slow: strictly one file at a time. Every step is pcall'd so a single bad file can never stop the rest,
			-- and we rest between the read and the load so the game never gets a burst of work.
			for i, x in items do
				local ok, data = pcall(work, i, x)
				if not ok then
					InitLogsText.Text ..= "\n[ERROR] Slow load: reading step failed: " .. tostring(data)
					data = nil
				end
				SlowPause()
				if ok and apply then
					local okA, errA = pcall(apply, i, x, data)
					if not okA then
						InitLogsText.Text ..= "\n[ERROR] Slow load: load step failed: " .. tostring(errA)
					end
					SlowPause()
				end
			end
			return
		end
		if loadMode == 1 then
			for i, x in items do
				local okW, data = pcall(work, i, x)
				if not okW then
					InitLogsText.Text ..= "\n[ERROR] Load step failed, skipping this file: " .. tostring(data)
				elseif apply then
					task.wait()
					apply(i, x, data)
				end
			end
			return
		end
		local size = loadMode == 2 and 2 or math.max(1, #items)
		local i = 1
		while i <= #items do
			local last = math.min(i + size - 1, #items)
			local results, pending = {}, last - i + 1
			for k = i, last do
				task.spawn(function()
					local ok, res = pcall(work, k, items[k])
					results[k] = (ok and res) or ""
					pending -= 1
				end)
			end
			while pending > 0 do
				task.wait()
			end
			if apply then
				for k = i, last do
					apply(k, items[k], results[k])
				end
			end
			if loadMode == 2 then
				task.wait()
			end
			i = last + 1
		end
	end
	InitLogsText.Text ..= "\n[LOG] Loading maps..."
	RunPhase(filesofbuiltins_d, function(i, x)
		Util.UINotify("Loading maps...", 0.15 + (i / #filesofbuiltins_d) * 0.15)
		local path = "UhhhhhhReanim/BuiltinModules/" .. x
		local exist = false
		local s, a = pcall(isfile, path)
		if s and a then exist = true end
		if force == "ALL" then exist = false end
		if exist then
			InitLogsText.Text ..= "\n[LOG] " .. x .. " already downloaded :D"
		else
			InitLogsText.Text ..= "\n[LOG] Downloading MAP " .. x .. "..."
			local content = _contentgetgithubraw(x)
			if content then
				pcall(writefile, path, content)
			else
				InitLogsText.Text ..= "\n[ERROR] Failed to load MAP " .. x .. ": Download failed."
				SaveData.ContentHash[x] = nil
			end
		end
	end)
	InitLogsText.Text ..= "\n[LOG] Loading builtin (also called vanilla) modules..."
	RunPhase(filesofbuiltins_m, function(i, x)
		Util.UINotify("Loading modules...", 0.325 + (i / #filesofbuiltins_m) * 0.475)
		local path = "UhhhhhhReanim/BuiltinModules/" .. x
		local exist = false
		local s, a = pcall(isfile, path)
		if s and a then exist = true end
		if wasold then exist = false end
		if force == "ALL" then exist = false end
		local data = ""
		if exist then
			InitLogsText.Text ..= "\n[LOG] Reading local VANILLA " .. x .. "..."
			data = readfile(path)
		else
			InitLogsText.Text ..= "\n[LOG] Downloading VANILLA " .. x .. "..."
			local content = _contentgetgithubraw(x)
			if content then
				pcall(writefile, path, content)
				data = content
			else
				InitLogsText.Text ..= "\n[ERROR] Failed to load VANILLA " .. x .. ": Download failed."
				SaveData.ContentHash[x] = nil
			end
		end
		return data
	end, function(i, x, data)
		InitLogsText.Text ..= "\n[LOG] Loadstringing VANILLA " .. x .. "..."
		xpcall(function()
			local func, comperr = loadstring(data, "Uhhhhhh :: VANILLA " .. x)
			if func then
				local names, logging = AddModules(func())
				InitLogsText.Text ..= logging
			elseif comperr then
				error("COMPILE FAILED: " .. comperr)
			end
		end, function(msg)
			InitLogsText.Text ..= "\n[ERROR] Failed to load VANILLA " .. x .. ": See traceback below."
			InitLogsText.Text ..= "\n[ERROR] " .. table.concat(string.split(debug.traceback("VANILLA " .. x .. ": " .. msg), "\n"), "\n[ERROR] ")
		end)
	end)
	Util.UINotify("Loading modules...", 0.8)
	InitLogsText.Text ..= "\n[LOG] Loading user modules..."
	local userfiles = {}
	local okList, listed = pcall(listfiles, "UhhhhhhReanim/Modules/")
	if not okList or type(listed) ~= "table" then
		InitLogsText.Text ..= "\n[WARN] Could not list UhhhhhhReanim/Modules/ (folder missing?), skipping user modules."
		listed = {}
	end
	for _,path in listed do
		local okFile, isF = pcall(isfile, path)
		if okFile and isF then
			table.insert(userfiles, path)
		end
	end
	RunPhase(userfiles, function(i, path)
		local x = path:sub(23)
		local data = nil
		xpcall(function()
			InitLogsText.Text ..= "\n[LOG] Reading local USER " .. x .. "..."
			data = readfile(path)
		end, function(msg)
			InitLogsText.Text ..= "\n[ERROR] Failed to read USER " .. x .. ": " .. tostring(msg)
		end)
		return data
	end, function(i, path, data)
		if type(data) ~= "string" or data == "" then return end
		local x = path:sub(23)
		xpcall(function()
			local blocked = Util.Security and Util.Security.GateModule(path, data)
			if blocked then
				InitLogsText.Text ..= "\n[SECURITY] Blocked USER " .. x .. " from loading: " .. blocked
				return
			end
			InitLogsText.Text ..= "\n[LOG] Loadstringing USER " .. x .. "..."
			local func, comperr = loadstring(data, "Uhhhhhh :: " .. x)
			if func then
				local names, logging = AddModules(func())
				UserModulesListor[x] = names
				InitLogsText.Text ..= logging
			elseif comperr then
				error("COMPILE FAILED: " .. comperr)
			end
		end, function(msg)
			InitLogsText.Text ..= "\n[ERROR] Failed to load USER " .. x .. ": See traceback below."
			InitLogsText.Text ..= "\n[ERROR] " .. table.concat(string.split(debug.traceback("USER " .. x .. ": " .. msg), "\n"), "\n[ERROR] ")
		end)
	end)
	do -- [nooby mod] load user Plugins (RootPart methods) and FlingMethods
		local function LoadExtensionFolder(folder, label, register)
			local okl, files = pcall(listfiles, folder)
			if not okl or type(files) ~= "table" then return 0 end
			local loaded = 0
			for _,path in files do
				if isfile(path) and path:lower():match("%.lua$") then
					local x = path:match("[^/\\]+$") or path
					xpcall(function()
						InitLogsText.Text ..= "\n[LOG] Reading " .. label .. " " .. x .. "..."
						local data = readfile(path)
						local blocked = Util.Security and Util.Security.GateModule(path, data)
						if blocked then
							InitLogsText.Text ..= "\n[SECURITY] Blocked " .. label .. " " .. x .. " from loading: " .. blocked
							return
						end
						local func, comperr = loadstring(data, "Uhhhhhh :: " .. label .. " :: " .. x)
						if not func then error("COMPILE FAILED: " .. tostring(comperr)) end
						register(func(), x)
						loaded += 1
					end, function(msg)
						InitLogsText.Text ..= "\n[ERROR] Failed to load " .. label .. " " .. x .. ": " .. tostring(msg)
					end)
					SlowPause()
				end
			end
			return loaded
		end
		local np = LoadExtensionFolder("UhhhhhhReanim/Plugins", "PLUGIN", LimbReanimator.RegisterMode)
		local nf = LoadExtensionFolder("UhhhhhhReanim/FlingMethods", "FLING", HatReanimator.RegisterFlingMethod)
		LimbReanimator.ResolveSavedMode()
		HatReanimator.ResolveSavedFling()
		InitLogsText.Text ..= "\n[LOG] Loaded " .. #LimbReanimator.PluginModes .. " RootPart plugin(s), " .. #HatReanimator.PluginFlingMethods .. " fling method(s)."
		if Util.RefreshReanimatorConfig then pcall(Util.RefreshReanimatorConfig) end
	end
	InitLogsText.Text ..= "\n[LOG] Refreshing Dance keybinds..."
	RefreshKeybinds()
	InitLogsText.Text ..= "\n[LOG] Loaded " .. (#MovementStyles + #DanceableDances) .. " modules - " .. #MovementStyles .. " Movesets, " .. #DanceableDances .. " Dances."
	InitLogsText.Text ..= "\n[LOG] Init complete!"
	Util.UINotify("Init complete" .. (InitLogsText.Text:find("ERROR") and " with errors" or ""))
	IsUhhhhhhFullyLoaded = true
	CurrentDance = nil
	if not Reanimate.Character then return end
	Reanimate.CreateCharacter()
end
UI.CreateSeparator(MainPage)
UI.CreateText(MainPage, "<b>MODULES MANAGEMENT</b>", 15, Enum.TextXAlignment.Center)
do -- [custom] module loading mode
	SaveData.ModuleLoadMode = math.floor(tonumber(SaveData.ModuleLoadMode) or 1)
	if SaveData.ModuleLoadMode < 1 or SaveData.ModuleLoadMode > 4 then
		SaveData.ModuleLoadMode = 1
	end
	local LoadModeInfo = {
		"Default: loads the modules one at a time, the normal way.",
		"Splitted: reads and loads 2 modules at a time. Lighter on weak devices.",
		"<font color=\"#FF5555\"><b>WARNING:</b> Instant loads ALL modules at once. It is the fastest, but it may freeze or crash your device. Avoid it on mobile or low-end PCs.</font>",
		"Slow: reads and loads 1 module at a time with a short pause between each. Saves performance on weak devices, but loading takes longer.",
	}
	local LoadModeNote = "\n(applies on the next Reload Modules / restart)"
	local LoadModeText
	UI.CreateDropdown(MainPage, "Module Loading", {
		"Default",
		"Splitted (2 at a time)",
		"Instant (may crash!)",
		"Slow (1 at a time, saves performance)",
	}, SaveData.ModuleLoadMode).Changed:Connect(function(val)
		SaveData.ModuleLoadMode = val
		LoadModeText.Text = (LoadModeInfo[val] or LoadModeInfo[1]) .. LoadModeNote
		if val == 3 then
			Util.UINotify("Warning: Instant module loading may crash your device!")
		end
	end)
	LoadModeText = UI.CreateText(MainPage, (LoadModeInfo[SaveData.ModuleLoadMode] or LoadModeInfo[1]) .. LoadModeNote, 10, Enum.TextXAlignment.Center)
end
UI.CreateButton(MainPage, "Reload Modules", 20).Activated:Connect(function()
	CracktroFrame.Interactable = false
	CracktroFrame.Visible = true
	MainPage.Interactable = false
	local tween = TweenService:Create(CracktroFrame, TweenInfo.new(0.5, Enum.EasingStyle.Cubic, Enum.EasingDirection.In), {
		Position = UDim2.new(0.5, 0, 0.5, 0),
	})
	tween:Play()
	tween.Completed:Connect(function()
		CracktroFrame.Interactable = true
	end)
